window.__D("text/pelach-harimon/c001",{"p":[[4801940213,"הנקודה, ונמצא כאן ד' מדרי' משכיל ב' מעיינות בשכל ומח', וכולם מתאחדים עם המשכיל, השכל בודאי מקבל תמיד מן האין גם המח' והבינה יש בהם עומק אחר עומק ובעלי הבנה נק' נבונים שמבינים דבר מתוך דבר<sup data-n=\"773\">16</sup>, והנה לכאורה שעומק האחרון גדול מן הראשון, אבל האמת שגדול הראשון מן האחרון והוא להיות שעומק הראשון מקור לכל העמקים, ולכן המח' לבוש פנימי לקבל בתוכו אור חדש בכל רגע כנ\"ל בנהר ומגלה ההעלם.\n<b>ועם</b> כל המשלים דים ונהר ומח' ודבור יובן למעלה, הנה א\"ס ב\"ה פשוט בתכלית והוא לבדו הוא רק שנתאווה להיות לו דירה<sup data-n=\"774\">17</sup> כו' לכן נתלבש ברצון דלהיטיב ומח' דאנא אמלוך מלכות דא\"ס<sup data-n=\"775\">18</sup>, וזהו הנקרא מקורא דכולא<sup data-n=\"776\">19</sup>, והנה מא\"ס זה היה נמתח העולם עד בלי די בבחי' א\"ס ממש רק ע\"י צמצום נתלבש בבחי' נקודת חכמה עילאה דאצי', חכים ולא בחכמה ידיעא<sup data-n=\"777\">20</sup>, ומהנקודה נעשה קו, והם הב' בחי' דחכ', והם בודאי בגדר א\"ס, שהחכ' מאין תמצא<sup data-n=\"778\">21</sup> ובא להתרחבות נהר דבינה עד שנתלבש במל' דאצי' שנק' ים<sup data-n=\"779\">22</sup> להיות מלכותו בכל משלה<sup data-n=\"780\">23</sup> (ונמצא למעלה יש ה' מדרי' ד' דנהר וים מדרי' חמישית), ונמשכה בעולמות בב' בחי' עלמא דאתכסייא ועלמא דאתגלייא<sup data-n=\"781\">24</sup>, עלמא דאתגליא חומר הנבראים הנק' יבשה וארץ, ועלמא דאתכסייא מח' שבדבור, וכמו בקי\"ס שנתגלה מאצי' לבריאה<sup data-n=\"782\">25</sup> (שהיו נשמות דבריאה) ע\"י קריעת ים מל' דאצי', כן לעתיד בכדי שיתגלה מקורא דכולא, הוא ע\"י שיקרע נהר דבינה ויתגלה ההעלם, וזהו שם נשמחה בו, השמחה הוא בהשגה דבינה כאשר משיג בכי טוב, אבל הנה לית מח' תפיסא בי' כלל<sup data-n=\"783\">26</sup> לכן צריך לענין הקריעה, שע\"י הקריעה יתגלה עבר הנהר, והוא כל יכול, וכל מה שיתגלה ממדרי' גבוה ביותר יותר יבא בגילוי כי כך רצונו ית' שיתגלה לעין כל והתחלת הקריעה יהיה בנהר, אבל באמת יהיה הקריעה עד רום המעלות עד שיתגלה העלם עצמיות והכל יעבור ברגל בבחי' יבשה והתגלות, וכמ\"ש ולא יכנף עוד מוריך<sup data-n=\"784\">27</sup>.",[["773","16","<b>שמבינים דבר מתוך דבר</b>: חגיגה יד, א."],["774","17","<b>שנתאווה להיות לו דירה</b>: ראה תניא רפל\"ו (ובהנסמן בליקוט פירושים לשם). ביאוה\"ז תזריע עב, ג. מאמרי אדה\"א הנחות תקע\"ז ע' שכט. שערי אורה צז, ב. לקמן מאמר ד\"ה אם בחוקותי הג' (קרוב לסופו) פיסקא אך הנה ידוע. סה\"מ תרל\"ח ע' לט הערה 138."],["775","18","<b>דאנא אמלוך מלכות דא\"ס</b>: ראה גם לעיל מאמר ד\"ה הפך ים הא' ובהערה 21."],["776","19","<b>מקורא דכולא</b>: זהר בראשית לג, א."],["777","20","<b>חכים ולא בחכמה ידיעא</b>: ת\"ז בהקדמה יז, ב."],["778","21","<b>שהחכ' מאין תמצא</b>: איוב כח, יב."],["779","22","<b>במל' דאצי' שנק' ים</b>: ראה זהר בהעלותך קנ, ב. הנסמן במאמרי אדה\"א שמות ח\"ב ע' תסג."],["780","23","<b>מלכותו בכל משלה</b>: ע\"פ תהלים קג, יט."],["781","24","<b>עלמא דאתכסייא ועלמא דאתגלייא</b>: ראה זהר בראשית יח, א. ויצא (ס\"ת) קנב, א. קנח, רע\"ב. וארא כט, ב. ת\"ז בהקדמה א, סע\"א ואילך."],["782","25","<b>בקי\"ס שנתגלה מאצי' לבריאה</b>: ראה גם לקמן מאמר ד\"ה ונקדשתי תקצ\"ח ובהערה 58."],["783","26","<b>לית מח' תפיסא בי' כלל</b>: ראה ת\"ז בהקדמה יז, א."],["784","27","<b>ולא יכנף עוד מוריך</b>: ישעי' ל, כ."]]],[4801940084,"<b>יו\"ט ב' של פסח תר\"א</b>\n<b>הפך</b> ים ליבשה<sup data-n=\"785\">1</sup> בנהר יעברו ברגל<sup data-n=\"786\">2</sup>, קי\"ס הכנה למ\"ת<sup data-n=\"787\">3</sup> ולעתיד בקיעת הנהר יהיה הכנה לעוה\"ב<sup data-n=\"788\">4</sup>, וכמ\"ש והניף ידו על הנהר<sup data-n=\"789\">5</sup> לעתיד, וכתיב כי רוצה ה' בעמו<sup data-n=\"790\">6</sup> במ\"ת (ולעתיד), יפאר ענוים בישועה בקי\"ס. הענין הוא הנה כתיב כי אל דיעות הוי'<sup data-n=\"791\">7</sup> ב' דיעות ד\"ע ודע\"ת, ד\"ע מיש לאין דעת תחתון מאין ליש, ולכאורה אינו כ\"א ב' מדרי' יש ואין, אבל באמת הם ד'<sup data-n=\"792\">8</sup>, אין אמיתי ואין של היש, ויש אמיתי ויש גשמי. הענין הוא הנה בת\"ז אומר אנת הוא דאפיקת<sup data-n=\"793\">9</sup> עשר תיקונין וקרינן להון ע\"ס, והע\"ס הם עצמות אלקות, ולא יתהווה מהם יש וחומר גשמי כ\"א ע\"י מל' וכמ\"ש מלכותך מלכות כל עולמים<sup data-n=\"794\">10</sup>, מלכותך אין הכלול ביש אמיתי, מלכות כ\"ע אין של היש, והנה בין אין הכלול ביש אמיתי לאין הנמשך ביש גשמי יש פרסה מפסיק, והוא הפרסה בין אצי' לבריאה<sup data-n=\"795\">11</sup>, והוא להיות ששרש הפרסה הוא באין הכלול ביש אמיתי וגם באין של היש. ויובן על פי ב' משלים, הא' מכח הצומח שבארץ שנרקב הגרעין ובא לכלל אין ומקבל מיש אמיתי דכח הצומח ובא מאין הכללי לפרטי וליש גשמי והפרסה הוא הארץ וחומר העפר. ומשל הב' מכח התנועה שהוא בלתי מוגבל והתנועה שביד מוגבלת בדבר הנעשה, וחומר היד הוא הפרסה. והנה יש עוד בחי' אין אמיתי למעלה מבחי' יש אמיתי דמל' והוא בחי' חכ\"ע דאצי' כי החכמה מאין תמצא<sup data-n=\"796\">12</sup>, עד\"ז בתפלה מתבונן בפסוד\"ז הנקרא שבחו של מקום<sup data-n=\"797\">13</sup> להשביח את המקום דיש גשמי (בהארת האין של היש), ואח\"כ ק\"ש ותפלה אין הכלול ביש אמיתי, ונק' ים ויבשה, ק\"ש ים אין של היש עלמא דאתכסייא, שמ\"ע המשכה מיש אמיתי ואח\"כ תורה ומצות, ועד\"ז היא הפלוגתא שבגמרא חד אמר שמים קדמה<sup data-n=\"798\">14</sup> בסדר ההשתלשלות וחד אמר ארץ קדמה בשרש ההשתלשלות כי נעוץ תחילתן בסופן<sup data-n=\"799\">15</sup>, סוף מעשה עלה במחשבה תחילה<sup data-n=\"800\">16</sup> באין הכלול ביש אמיתי, וחד אמר כאחד נבראו כמו שהם כלולים ביש אמיתי. ויש פי' שארץ קדמה גם לזה, והוא כמו שהם באין",[["785","1","<b>הפך ים ליבשה</b>: דרוש ר' הלל.\nראה לעיל מאמר ד\"ה הפך ים הא' הערה 1."],["786","2","<b>הפך ים. . ברגל</b>: תהלים סו, ו."],["787","3","<b>קי\"ס הכנה למ\"ת</b>: ראה שער האמונה לב, ב ובהערה 9. לעיל מאמר ד\"ה הפך ים הא'. וש\"נ."],["788","4","<b>בקיעת הנהר יהיה הכנה לעוה\"ב</b>: ראה גם לעיל שם. וש\"נ."],["789","5","<b>והניף ידו על הנהר</b>: ישעי' יא, טו."],["790","6","<b>כי רוצה ה' בעמו</b>: תהלים קמט, ד."],["791","7","<b>כי אל דיעות הוי'</b>: שמו\"א ב, ג. ראה מאמרי אדה\"א ויקרא ח\"א ע' רסב. וש\"נ. לקמן מאמר ד\"ה ענין יצי\"מ וקי\"ס ובהערה 86."],["792","8","<b>הם ד'</b>: ראה שערי אורה סב, ב ואילך ובהערה 30. תו\"ח וארא ח\"א נ, ד הערה 69."],["793","9","<b>בת\"ז אומר אנת הוא דאפיקת</b>: בהקדמה יז, א (סידור אדה\"ז סדר מנחת ערב שבת)."],["794","10","<b>מלכותך מלכות כל עולמים</b>: תהלים קמה, יג."],["795","11","<b>הפרסה בין אצי' לבריאה</b>: ראה ע\"ח שער דרושי נקודות ש\"ח, פ\"ב. לקוטי הש\"ס להאריז\"ל חולין ס, ב ד\"ה לכי ומעטי (כ, ב). הנסמן במאמרי אדה\"א דברים ח\"ג ע' תתפא. ראה גם לקמן מאמר ד\"ה וזכרתי הר\"ת על יד הערה 29 ואילך."],["796","12","<b>החכמה מאין תמצא</b>: איוב כח, יב."],["797","13","<b>בפסוד\"ז הנקרא שבחו של מקום</b>: ראה שו\"ע אדה\"ז הל' ברכות השחר סנ\"א, ס\"א."],["798","14","<b>הפלוגתא שבגמרא. . שמים קדמה</b>: ראה חגיגה יב, א."],["799","15","<b>נעוץ תחילתן בסופן</b>: ראה ס\"י פ\"א, מ\"ז."],["800","16","<b>סוף מעשה עלה במחשבה תחילה</b>: ע\"פ פיוט לכה דודי."]]],[4801940150,"אמיתי שלמעלה גם מיש אמיתי. ועל דרך זה גם למעלה יותר יש אמיתי מחשבה הקדומה דאדם קדמון אדם דבריאה<sup data-n=\"801\">17</sup> רישא בבריאה ורגלוהי בעשיה<sup data-n=\"802\">18</sup>, וכולל הכל כאחד (אחדות דאבי\"ע) ומלכות דא\"ק אין הכלול ביש אמיתי ומקורא דכולא, אח\"כ נתגלה בחי' עתיק אין הב' ואריך רצון פרטי לעולם אצי' יש הב' כי הרצון הוא היש ויש ביניהם פרסה מפסיק וכמאמר בין כשב\"כ לעה\"ע יש רקיע המבדיל מקו המדה דקו\"ח. ולמעלה מכל זה ישנו ג\"כ ב' מדרגות דיש ואין הנה רצון הפשוט דלהיטיב ומח' דאנא אמלוך<sup data-n=\"803\">19</sup> מתגלה מרצון הנעלם שבעצמותו ע\"י הממוצע הנזכר בעה\"מ הנק' שעשועי המלך בעצמותו<sup data-n=\"804\">20</sup>, רצון הנעלם יש אמיתי אמיתית היש, ושעשועים אין הכלול ביש אמיתי, ומל' דא\"ס אין של היש, ויש הב' הצמצום והכנה לצמצום בלשון הזהר בריש הורמנא דמלכא גליף גליפי בטה\"ע<sup data-n=\"805\">21</sup>, ויש בגליף ב' פי' א' הכנה לצמצום, ב' הצמצום, והאין האמיתי שלמעלה מיש אמיתי הוא ענג הנעלם סיבה לרצון הנעלם, וזהו המתגלה לעתיד. וזהו כי רוצה ה' בעמו (רוצה) יסוד שהיסוד מגיע אל הכתר<sup data-n=\"806\">22</sup> וכמאמר המקובלים שיש ליסוד ארחין ומהלכין עד פנימיות הכתר<sup data-n=\"807\">23</sup>, וזהו מאן דבעי לאסתכלא לקב\"ה<sup data-n=\"808\">24</sup>, ס\"א אסתלקת מיניה שמתעלה עד פנימיות הכתר.\n<b>יפאר</b> ענוים בישועה<sup data-n=\"809\">25</sup> בקי\"ס, וכמאמר ראתה שפחה על הים<sup data-n=\"810\">26</sup> כו', והמשל בזה הוא כמו מלך שרוצה להראות חיבה יתירה לעבדיו מראה להם אוצרות גנזיו, ומקבלים מזה תענוג גדול בהסתכלות דברים יקרים, אף שאינם שלהם ומתלבש התענוג בראי', וזהו יפאר ענוים בפאר דחו\"ב בראי' וענג הכנה למ\"ת.",[["801","17","<b>דאדם קדמון אדם דבריאה</b>: ראה מאמרי אדה\"ז ענינים בתחלתן ובהנסמן לשם. סה\"מ תרל\"ב ח\"א ע' ד הערה ג' בחי' אדם."],["802","18","<b>ורגלוהי בעשיה</b>: ראה ע\"ח דרוש עגו\"י ש\"א ענף ד. מאמרי אדה\"א ויקרא ח\"א ע' טו. וש\"נ."],["803","19","<b>ומח' דאנא אמלוך</b>: ראה מאמרי אדה\"ז תקס\"ח ח\"א ע' ז: וכמ\"ש בזהר בפי' וימלוך אנא אמלוך. הנסמן במאמרי אדה\"א דברים ח\"ג ע' תתצד."],["804","20","<b>שעשועי המלך בעצמותו</b>: ראה עמה\"מ שער זה. מאמרי אדה\"א שמות ח\"ב ע' תנג. קונטרסים ע' שמה ובהנסמן בהנ\"ל."],["805","21","<b>בריש. . גליף גליפי בטה\"ע</b>: ראה זהר בראשית טו, א. לקמן מאמר ד\"ה אם בחוקותי הג' הערה 61."],["806","22","<b>שהיסוד מגיע אל הכתר</b>: ראה מאמרי אדה\"ז על מארז\"ל ע' שסה."],["807","23","<b>שהיסוד מגיע. . פנימיות הכתר</b>: ראה גם לקמן ביאור מאמר ד\"ה וזכרתי הר\"ת על יד הערה 26."],["808","24","<b>מאן דבעי לאסתכלא לקב\"ה</b>: ראה זהר תרומה קלד, ב."],["809","25","<b>יפאר ענוים בישועה</b>: ראה גם לקמן מאמר ד\"ה שרש ענין קי\"ס."],["810","26","<b>ראתה שפחה על הים</b>: מכילתא בשלח טו, ב."]]],[4801940085,"<b>ה'</b> לי לא אירא<sup data-n=\"811\">1</sup> מה יעשה לי אדם<sup data-n=\"812\">2</sup> ה' לי בעוזרי<sup data-n=\"813\">3</sup> ואני אראה בשונאי. הנה ה' לי הוא גילוי המשכת אלקות בנפש כמו קרבת אלקים לי טוב<sup data-n=\"814\">4</sup>. והענין הוא הנה כתיב ועל הכסא דמות כמראה אדם<sup data-n=\"815\">5</sup> כו' מל' דאצי' כמש\"ה<sup data-n=\"816\">6</sup> באצי', ובאצי' ישנו ד' פרצופים עד המל'<sup data-n=\"817\">7</sup> כמבואר בכתבי האריז\"ל, כ\"ה במל' ד' פרצופים נה\"י חג\"ת חב\"ד וכתר מל', נה\"י בעשי' בחי' עיבור תלת גו תלת<sup data-n=\"818\">8</sup> קטנות המדות, כמו העובר בבטן אמו ראשו בין ברכיו<sup data-n=\"819\">9</sup>, חג\"ת ביצי' גדלות המדות והמוחין כלולים בהם כמו התינוק היונק משדי אמו שמתגדל מדותיו ומתגלה בהם השכל קצת מוחין למדות להנהיג את המדות, חב\"ד בבריאה מוחין בעצם כמו גדלות המוחין באדם להשכיל השכלות המציאות<sup data-n=\"820\">10</sup> או הנהגות המדות והמדות נגררים אחר השכל, כתר מל' מקור לע\"ס שבמל', ובאדם נק' כח המשכיל שממנו נמשך חו\"ב ומדות, ועד\"ז בעבודה נה\"י אמונה בכח המעשה בפועל בניצוח והודאה והסכם, חג\"ת להתפעל בלב עפ\"י התבוננות בסובב וממלא מוחין שבמדות, חב\"ד מוחין בעצם לאסתכלא ביקרי' דמלכא<sup data-n=\"821\">11</sup> והמדות כלולים במוח, מדות שבשכל, כתר רצון<sup data-n=\"822\">12</sup> דבכל נפשך<sup data-n=\"823\">13</sup>, וד' מדרי' אלו נחלקים למי\"ם<sup data-n=\"824\">14</sup> כ\"א כלול מיו\"ד, כי גם עובר במעי אמו ראשו בין ברכיו ציור אדם. וזהו ה' לי אם מאיר שם הוי' בכל המי\"ם בחי' אז לא אירא מה יעשה לי אדם, ואין לו תקוה להכשילי שאין לו מקום אחיזה באדם דקדושה, וכ\"ז פנימיות שנמשך בציור אדם כי גם הרצון קרקפתא<sup data-n=\"825\">15</sup> בציור אדם, ולכן אינו כ\"א שאינו ירא מן ההיפוך אך כשה' לי בעוזרי והם מי\"ם בחי' שבתורה מוחין ומדות אז אראה בשונאי, כי הנה ידוע הקושיא איך שייך עוזרים לה' (והל\"ל בעזרי), אך הוא תו\"מ עוזרים<sup data-n=\"826\">17</sup> ומקיפים להנשמה כן ההפרש בין יום ראשון של יו\"ט לשני.",[["811","1","<b>ה' לי לא אירא</b>: דרוש ר' הלל.\nראה לעיל מאמר ד\"ה הפך ים הא' הערה 1."],["812","2","<b>ה' לי. . אדם</b>: תהלים קיח, ו."],["813","3","<b>ה' לי בעוזרי</b>: תהלים שם, ז."],["814","4","<b>קרבת אלקים לי טוב</b>: שם עג, כח. ראה גם מאמרי אדה\"א קונטרסים ע' קנו (בלקו\"ב)."],["815","5","<b>ועל הכסא דמות כמראה אדם</b>: יחזקאל א, כו [בדילוג]."],["816","6","<b>כמש\"ה</b>: כמו שהיא."],["817","7","<b>ובאצי' ישנו ד' פרצופים עד המל'</b>: ראה גם ע\"ח שער הכללים פ\"ב. שער המלכים שי\"א, פ\"ה. שער ההקדמות דרוש ב בתיקון המלכים (קנט, סע\"ב ואילך). כנפי יונה ח\"א, פ\"ו."],["818","8","<b>תלת גו תלת</b>: ראה זהר תוספתא בשלח נ, סע\"א. ע\"ח שער הכללים פ\"ג. ביאוה\"ז בשלח מז, ג ואילך. שעה\"י קל, ב הערה 18."],["819","9","<b>העובר. . ראשו בין ברכיו</b>: נדה ל, ב."],["820","10","<b>המציאות</b>: אוצ\"ל: המצאות."],["821","11","<b>לאסתכלא ביקרי' דמלכא</b>: ראה זהר מקץ קצט, א. בראשית לח, א-ב. פקודי רמז, ב. תרומה קלד, א."],["822","12","<b>כתר רצון</b>: ראה פרדס שער עצמות וכלים ש\"ד, פ\"ח. שער הצחצחות שי\"א, פ\"ה. פ\"ו. אגה\"ק סכ\"ט. מאמרי אדה\"א הנחות תקע\"ז ע' עב. וש\"נ."],["823","13","<b>דבכל נפשך</b>: ואתחנן ו, ו."],["824","14","<b>למי\"ם</b>: אוצ\"ל: למ\"ם."],["825","15","<b>הרצון קרקפתא</b>: ראה לקו\"ת שלח מח, ב. ר\"ה נד, ב. תו\"ח בא ח\"א צ, א.\n16)איך שייך עוזרים: ראה גם בהתחלת הדרושים שנסמנו בד\"ה אם בחוקותי שבהערה הבאה."],["826","17","<b>תו\"מ עוזרים</b>: ראה גם לקמן מאמר ד\"ה אם בחוקותי הא' ובהערה 17."]]],[4801940086,"<b>יו\"ט ב' ש\"פ שנת תר\"י בפאריטש</b>\n<b>והניף</b> ידו על הנהר<sup data-n=\"827\">1</sup> בעים רוחו והכהו לשבעה נחלים<sup data-n=\"828\">2</sup>, וזה כמו בקי\"ס ברוח קדים עזה<sup data-n=\"829\">3</sup>. וי\"ל מה שלעתיד יהי' הבקיעה בנהר וביצ\"מ הי' על הים, וכמ\"ש הפך ים ליבשה<sup data-n=\"830\">4</sup> לשון עבר, בנהר יעברו לעתיד. גם י\"ל מה שהים גזר לי\"ב גזרים<sup data-n=\"831\">5</sup> ולעתיד לשבע נחלים. יובן ע\"פ מה שמבואר בכתבי האריז\"ל כתר ממוצע<sup data-n=\"832\">6</sup> בין המאציל לנאצלים, גם מבואר שיש ב' בחי' בכתר פנימיות הנק' עתיק, ואריך. גם מבואר שם בסוד התלבשות פנימיות בחיצונות<sup data-n=\"833\">7</sup> שרק ז' תחתונות דעתיק מלובש בג' ראשונות<sup data-n=\"834\">8</sup> דאריך, חסד דעתיק בגולגלתא דאריך, גבורה דע\"י במו\"ס דאריך, ת\"ת דעתיק בבינה דאריך, הנה לשון מאציל אינו קאי על עצמותו ולהיות מאציל הוא ע\"י ממוצע ויובן ממשל חיות הנפש בגוף הנה כל כחות פרטים שבאדם הם הארה מן הנפש גם כח החכ', והמחבר והממוצע מפשיטות הנפש וחיות<sup data-n=\"835\">9</sup> פרטי הוא התענוג והרצון ובמה שירצה ישכיל כל ימיו, והם שתים שהן ארבע רצון פשוט, תחלת הרצון וסוף הרצון, תענוג פשוט ותענוג מורכב, רצון מרוצת הנפש בירידה והמשכה ותענוג הגבהת הנפש. הנמשל יובן למעלה א\"ס ב\"ה פשוט בתכלית הפשיטות יחיד ואין שני לו וגם בשם א\"ס לא יתכן לקרותו<sup data-n=\"836\">10</sup> רק שנתגלה בחי' שעשועים כמו שמבואר בעמק המלך שנק' שעשועי המלך בעצמותו<sup data-n=\"837\">11</sup> ונק' אור המאיר לעצמו תענוג הפשוט וכמ\"ש שעשועים יום יום שעשועים עצם השעשועים יום יום חו\"ב<sup data-n=\"838\">12</sup> שבשעשועים, וכמ\"ש רז\"ל הוה בדח טובא<sup data-n=\"839\">13</sup>, אז משתעשע גם ביכולת חכמתו ובינתו ולכן אי בעי מיני'<sup data-n=\"840\">14</sup> כו'. והנה שעשועים אלו הם גילוי אור פשוט דלבדך וכמ\"ש בפרקי דר\"א קודם שנבה\"ע<sup data-n=\"841\">15</sup> הי' הוא ושמו בלבד שגם בלבדו יש בחי' שמו, והוא תענוג הפשוט ושעשועים פשוטים, והארה מעונג זה מתלבש ברצון הפשוט דלהיטיב ומח' דאנא",[["827","1","<b>והניף ידו על הנהר</b>: דרוש ר' הלל.\nראה לעיל מאמר ד\"ה הפך ים הא' הערה 1."],["828","2","<b>והניף ידו. . לשבעה נחלים</b>: ישעי' יא, טו."],["829","3","<b>ברוח קדים עזה</b>: בשלח יד, כא."],["830","4","<b>הפך ים ליבשה</b>: תהלים סו, ו. וראה גם בדרושים דלעיל עה\"פ."],["831","5","<b>שהים גזר לי\"ב גזרים</b>: ראה מכילתא בשלח יד, טז. שה\"א סח, ב ובהערה 22."],["832","6","<b>כתר ממוצע</b>: ראה ע\"ח (ש' דרושי אבי\"א) שמ\"ב, פ\"א. תו\"ח שמות ח\"א יא, ג הערה 509. לקמן מאמר ד\"ה לה\"ע קי\"ס תרכ\"א על יד הערה 23."],["833","7","<b>בחיצונות</b>: כנצ\"ל: בחיצוניות."],["834","8","<b>ז' תחתונות. . בג' ראשונות</b>: ראה ע\"ח שער א\"א שי\"ג, פ\"ו ופ\"ז."],["835","9","<b>וחיות</b>: כנצ\"ל: לחיות."],["836","10","<b>בשם א\"ס לא יתכן לקרותו</b>: ראה גם לעיל מאמר ד\"ה אדם כי יקריב הב' ובהערה 155."],["837","11","<b>שעשועי המלך בעצמותו</b>: ראה עמה\"מ שער זה. מאמרי אדה\"א שמות ח\"ב ע' תנג. קונטרסים ע' שמה ובהנסמן בהנ\"ל."],["838","12","<b>שעשועים יום יום. . חו\"ב</b>: משלי ח, ל. ראה גם לקמן מאמר ד\"ה הפך ים תרכ\"ד על יד הערה 30. ד\"ה לה\"ע קי\"ס תרכ\"א על יד הערה 34. ד\"ה וידבר וגו' אלה הם מועדי תר\"כ על יד הערה 83. ד\"ה וספרתם תרי\"ב על יד הערה 73. מאמרי אדה\"א שמות ח\"ב ע' תנה. תו\"ח מקץ ריח, ד."],["839","13","<b>הוה בדח טובא</b>: הלשון ראה ברכות ל, ב. ז\"ח מדהנ\"ע בראשית י, ג. בהערה הבאה."],["840","14","<b>הוה בדח טובא. . אי בעי מיני'</b>: לשון הרגיל בכתבי ר\"ה — ראה שבת עז, ב. לקמן מאמר ד\"ה הנה וכו' והצרוע תקצ\"ט על יד הערה 100. ד\"ה מנין שקושרין על יד הערה 94. ד\"ה ביאור את שבתותי תרי\"ב על יד הערה 12. פלח הרמון שה\"ש ע' לא. ע' קלא [ושם: בגמ']."],["841","15","<b>בפרקי דר\"א קודם שנבה\"ע</b>: ראה שם פ\"ג. תו\"ח וארא ח\"א נג, ב הערה 6."]]],[4801940151,"אמלוך שהוא מל' דא\"ס<sup data-n=\"842\">16</sup> שלפני הצמצום ונק' אא\"ס, מטבע הטוב שהם השעשועים עצמם רצון דלהיטיב<sup data-n=\"843\">17</sup>, ומחו\"ב שבשעשועים ונק' מלך יחיד גילוי היכולת נתגלה מח' דאנא אמלוך, רצון פשוט דלהיטיב מקור ויכולת לכח השפע ומח' דאנא אמלוך להתגלות השפע, להיטיב לזולתו משמע, אנא אמלוך אין מלך בלא עם<sup data-n=\"844\">18</sup> ונקרא תחלת הרצון ויכול להתהוות ממנו עולמות לא\"ס<sup data-n=\"845\">19</sup> וכל עולם בבחי' א\"ס והרצון הי' שיהיו ד' עולמות ולא יותר ובכל עולם ע\"ס וכמ\"ש המוציא במספר צבאם<sup data-n=\"846\">20</sup>, לזה נתהווה הצמצום להעלים אור א\"ס ואינו העדר האור ח\"ו רק העדר הגילוי<sup data-n=\"847\">21</sup>, ולאחר הצמצום נתגלה קו<sup data-n=\"848\">22</sup> וחוט אור מצומצם וכח הירידה ובתחלה נתעגל כביכול ונעשה פרצוף א\"ק<sup data-n=\"849\">23</sup> הנק' מאציל ורגלוהי מסתיים עד סוף עשי'<sup data-n=\"850\">24</sup> רצון פשוט לד' עולמות<sup data-n=\"851\">25</sup> בכלל ושעשועים פשוטים<sup data-n=\"852\">26</sup> להם, וצריך להוציא האור מהעלם לגילוי וכמ\"ש קורא הדורות<sup data-n=\"853\">27</sup> מראש וראשית הגילוי בגולגלתא דעתיק ואריך, עתיק תענוג כללי לעולם אצי' אריך רצון<sup data-n=\"854\">28</sup> כללי, ז\"ת דעתיק מתלבש בג' ראשונות דאריך וג' ראשונות נשאר בהעלם ונק' עגולית<sup data-n=\"855\">29</sup> דאריך וז\"ת דאריך מלובש בע\"ס דאצי' שהם או\"א וזו\"נ דאצי', חסד דאריך בחכ' דאצי'<sup data-n=\"856\">30</sup> כו', וז\"ת דאריך הוא סוף פרצוף כתר<sup data-n=\"857\">31</sup> דאצי'.\n<b>והנה</b> מקור עולמות בי\"ע הוא בז\"א דאצי' כי גם חו\"ב דאצי' נק' אור המאיר לעצמו כמו טבע בר שכל להשכיל השכלות עמוקות לעצמו, רק כי אמרתי",[["842","16","<b>ומח' דאנא אמלוך שהוא מל' דא\"ס</b>: ראה גם לעיל מאמר ד\"ה הפך ים הא' על יד הערה 21. ד\"ה הפך ים הב' על יד הערה 18. לקמן ד\"ה הפך ים תרכ\"ד על יד הערה 22. ד\"ה הנה כו' והצרוע תקצ\"ט על יד הערה 19. ש\"א נה, ב ובהנסמן במ\"מ לשם."],["843","17","<b>מטבע הטוב. . דלהיטיב</b>: ראה שער היחוד והאמונה פ\"ד ובמ\"מ הגהות והע\"ק לשם. מאמרי אדה\"א קונטרסים ע' ה. וש\"נ. תו\"ח בראשית ל, ב הערה 4."],["844","18","<b>אין מלך בלא עם</b>: ראה שער היחוה\"א פ\"ז ובמ\"מ הגהות והע\"ק שם. בחיי וישב לח, ל. הנסמן במאמרי אדה\"ז על פרשיות התורה ח\"ב לע' תרלא."],["845","19","<b>עולמות לא\"ס</b>: ראה גם מאמרי אדה\"א ויקרא ח\"א ע' תכג. סה\"מ באתי לגני ח\"א ע' קנט."],["846","20","<b>המוציא במספר צבאם</b>: ישעי' מ, כו."],["847","21","<b>הצמצום. . העדר הגילוי</b>: ראה הוספות ללקו\"ת ויקרא נב, ג (ובהנסמן במ\"מ בריש המאמר שם). שעה\"י קיח, ב ובלקוטי ביאורים שם קעז, ג-ד ואילך."],["848","22","<b>ולאחר הצמצום נתגלה קו</b>: ראה ע\"ח דרוש עגו\"י ש\"א, ענף ב."],["849","23","<b>קו. . נתעגל. . א\"ק</b>: ראה ע\"ח שם."],["850","24","<b>א\"ק. . ורגלוהי. . עשי'</b>: ראה ע\"ח שם ענף ד. מאמרי אדה\"א ויקרא ח\"א ע' טו. וש\"נ."],["851","25","<b>א\"ק. . רצון פשוט לד' עולמות</b>: ראה לקו\"ת תזריע כ, סע\"ד. מסעי צה, ב (רעדכ\"ר). סידור שער המילה קלט, ד (רצון קדום הנק' רצון פשוט). לקמן מאמר ד\"ה אם בחוקותי הא' על יד הערה 109."],["852","26","<b>ושעשועים פשוטים</b>: ראה מאמרי אדה\"א קונטרסים ע' תכה (עתיקא דעתיקי')."],["853","27","<b>קורא הדורות מראש</b>: ישעי' מא, ד. ראה הנסמן במאמרי אדה\"א דברים ח\"ג ע' תתיא. ע' תתפח. קונטרסים ע' תלב. לקמן מאמר ד\"ה והתהלכתי תר\"ב על יד הערה 23."],["854","28","<b>עתיק תענוג. . אריך רצון</b>: ראה גם שעה\"י קכו, א ובהנסמן במ\"מ לשם. ובלקוטי ביאורים שם. תו\"ח בשלח ח\"א רב, ד. וש\"נ."],["855","29","<b>עגולית</b>: אוצ\"ל: עיגולי."],["856","30","<b>וז\"ת דאריך. . בחכ' דאצי'</b>: ראה ע\"ח שער או\"א שי\"ד, פ\"א. הנסמן במאמרי אדה\"ז על פרשיות התורה ח\"א לע' שנד."],["857","31","<b>וז\"ת דאריך הוא סוף פרצוף כתר</b>: ראה ע\"ח שער דרושי אבי\"ע שמ\"ב, פ\"א."]]],[4801940214,"עולם חסד יבנה<sup data-n=\"858\">32</sup>, והנה גם מדות דז\"א הוא רק מקור העולמות בכח ולא בפועל, ומלכות דאצי' מקור העולמות בפועל, וכמבואר במ\"א שהמדות הם בקירוב הערך ולא נתהווה מהם יש<sup data-n=\"859\">33</sup> מוגבל, אך המוחין שהם חו\"ב דמלכות הם ג\"כ אור המאיר לעצמו, ועולם מחסד שבמלכות יבנה, ולעתיד כתיב והיה אור הלבנה כאור החמה<sup data-n=\"860\">34</sup> ואור החמה יהי' שבעתיים כאור שבעת הימים, ויש בזה ב' פירושים, א' שבעת הימים ז\"ת דאריך<sup data-n=\"861\">35</sup> מדות שבכתר והוא כמו מדות הטבעיים שלא ישונה במוח שליט על הלב<sup data-n=\"862\">36</sup>, וכמאמר ז\"ל אדה\"ר הי' מסתכל באור ז' הימים מסוף עולם עד סופו<sup data-n=\"863\">37</sup>, ולכאורה הל\"ל מראש עולם עד סופו<sup data-n=\"864\">38</sup>, אך הוא מסוף עולם אין סוף שבכתר שהם ז' תחתונות דאריך עד סוף עולם עשי' ולאחר החטא ויגרש<sup data-n=\"865\">39</sup> כו' מטעם פן ישלח ידו ולקח גם מעץ החיים ואכל וחי לעולם<sup data-n=\"866\">40</sup>, ולכאורה מאי איכפת ליה, אך כתיב וימנע מרשעים אורם<sup data-n=\"867\">41</sup> כ\"א יהי' אור זה ברשעים יהיו חזקים ונצחים, לכן נסתלק האור ליחודא עילאה דאצי', והיכן גנזו בתורה<sup data-n=\"868\">42</sup> חכ\"ע דאצי', ולעתיד תתעלה מל' לאור שבעת הימים חסד דאריך, ואור החמה יהי' שבעתיים כאור שבעת הימים ג' ראשונות דאריך והעיקר בינה דאריך<sup data-n=\"869\">*43</sup> כי התגלות עתיק בבינה<sup data-n=\"870\">43</sup> והם שבעתים ז' פעמים ז' מ\"ט שערי בינה<sup data-n=\"871\">44</sup>.\n<b>והנה</b> כתיב כימי צאתך מארץ מצרים אראנו נפלאות<sup data-n=\"872\">45</sup> ב' נפלאות<sup data-n=\"873\">46</sup> כי יש פי' ב' בשבעת הימים שהם ז\"ת דעתיק<sup data-n=\"874\">47</sup> ושבעתים כאור שבעת הימים בינה דעתיק ויתעלה עד שעשועים הפשוטים, וכאן או' רק על אור החמה שהוא ז\"א<sup data-n=\"875\">48</sup> דאצי' אבל כתוב לנו בתו' הנגלית כלל גדול עולה עמו<sup data-n=\"876\">49</sup> כו' רק שעולה דרך טפל עד שתתעלה",[["858","32","<b>כי אמרתי עולם חסד יבנה</b>: תהלים פט, ג. ראה גם לקמן מאמר ד\"ה ענין יצי\"מ וקי\"ס ובהערה 90."],["859","33","<b>שהמדות. . ולא נתהווה מהם יש</b>: ראה גם לקמן מאמר ד\"ה לה\"ע ההפרש בין שליו\"ט תר\"ב ובהערה *36."],["860","34","<b>והיה אור הלבנה כאור החמה</b>: ישעי' ל, כו."],["861","35","<b>שבעת הימים ז\"ת דאריך</b>: ראה מאמרי אדה\"ז תקס\"ז ע' שפח."],["862","36","<b>במוח שליט על הלב</b>: ראה תניא פי\"ב. מאמרי אדה\"א דברים ח\"ב ע' תצ. וש\"נ."],["863","37","<b>אדה\"ר הי' מסתכל. . סופו</b>: ראה חגיגה יב, א. ב\"ר פי\"ב, ו. פי\"א, ב."],["864","38","<b>ולכאורה הל\"ל מראש עולם עד סופו</b>: ראה רמ\"ז ר\"פ במדבר. סה\"מ תרכ\"ט ע' ס. וש\"נ."],["865","39","<b>ויגרש</b>: בראשית ג, כד."],["866","40","<b>פן ישלח ידו. . וחי עולם</b>: שם שם, כב."],["867","41","<b>וימנע מרשעים אורם</b>: איוב לח, טו."],["868","42","<b>גנזו בתורה</b>: ראה לקו\"ת במדבר יח, ד ובהנסמן במ\"מ לשם. לקמן מאמר ד\"ה ענין זכר בא לעולם ובהערה 15."],["869","*43","<b>שבעתיים. . ג' ראשונות. . בינה דאריך</b>: ראה מאמרי אדה\"ז תקס\"ז שם."],["870","43","<b>התגלות עתיק בבינה</b>: מובא בכ\"מ בשם הע\"ח — ראה תו\"ח לך פא, ב ואילך. הנסמן במאמרי אדה\"א הנחות תקע\"ז ע' ד. ביאוה\"ז להצ\"צ אחרי ע' שסד."],["871","44","<b>מ\"ט שערי בינה</b>: ראה ר\"ה כא, ב."],["872","45","<b>כימי צאתך.. נפלאות</b>: מיכה ז, טו."],["873","46","<b>נפלאות ב' נפלאות</b>: ראה גם לקמן מאמר ד\"ה והתהלכתי בתוככם תר\"ב על יד הערה 90. פלח הרמון יתרו ע' רנה. תו\"ח שמות ח\"א כא, א. וש\"נ."],["874","47","<b>בשבעת הימים שהם ז\"ת דעתיק</b>: לקו\"ת צו טו, ב. וש\"נ."],["875","48","<b>החמה שהוא ז\"א</b>: ראה פרדס שעה\"כ שכ\"ג, פ\"ח מערכת חמה. ע\"ח שער מיעוט הירח של\"ו, פ\"ב."],["876","49","<b>כלל גדול עולה עמו</b>: ראה כתובות סא, א. תו\"ח וישב רט, ד הערה 47."]]],[4801940268,"למקום המשפיע ויהי' שוים בקומתן<sup data-n=\"877\">50</sup>, ואח\"כ תתעלה גם למעלה מז\"א א\"ח עט\"ב<sup data-n=\"878\">51</sup> נקבה תסובב גבר<sup data-n=\"879\">52</sup>, להיות שגם השעשועים נק' אור, וסיבה לאור זה מבואר במדרש במי נמלך<sup data-n=\"880\">53</sup> בנשמותיהן של צדיקים, עונג הנעלם מנשמות שבגופים נעוץ תחב\"ס<sup data-n=\"881\">54</sup>, ונק' כוונה נעלמה שבעצמיות וזהו סומך הוי' לכל הנופלים<sup data-n=\"882\">55</sup> כו', ירידות המדות לברר בירורים, ובתשלום הבירור ותשלום הכוונה יתגלה עונג הכוונה למטה כמו למעלה, וזהו ענין העברת הנהר דלעתיד בינה דעתיק ויתגלה בז' קרעים ז\"ת דעתיק, הנה קי\"ס הי' לנשמות דבריאה וישנו ביחו\"ע<sup data-n=\"883\">56</sup> ונק' שבטי יה<sup data-n=\"884\">57</sup> י\"ב גבולי אלכסון<sup data-n=\"885\">58</sup> וכשהם בבריאה נק' שבטים סתם י\"ב בקר והים עומד עליהם<sup data-n=\"886\">59</sup> מל' דאצי'<sup data-n=\"887\">60</sup> ונחלק לי\"ב גזרים שביל לכל שבט, אבל לעתיד יהי' עליה לג' ראשונות דעתיק לז\"ת שבעצמיות, וכמ\"ש ונהר יוצא מעדן<sup data-n=\"888\">61</sup> וכמה עדן יש חכ' דאצי' נק' עדן<sup data-n=\"889\">62</sup> עין לא ראתה חכים ולא בחכמה ידיעא<sup data-n=\"890\">64</sup> ונהר יוצא מעדן בינה<sup data-n=\"891\">65</sup> דאצי', ויש עדן כו' יעשה למחכי לו<sup data-n=\"892\">63</sup> מאן דבעי למינדע<sup data-n=\"893\">66</sup> לי' במילי דחוכמתא רזין דאורייתא התגלות עונג הנעלם, וזהו והניף ידו על הנהר בעים רוחו גבורת<sup data-n=\"894\">67</sup> דע\"י, והוא להיות שכל עלי' הוא ע\"י גבורת<sup data-n=\"895\">68</sup>, בקי\"ס הי' ברוח קדים עזה גבורת שבמל', ולעתיד גבורת דעתיק, והכהו לשבע נחלים תחלת העלי' לז\"ת דעתיק עד שיתגלה עבר הנהר, ענג הנעלם.",[["877","50","<b>שוים בקומתן</b>: ראה ע\"ח (שער מיעוט הירח) של\"ו, פ\"א. פ\"ב. מאמרי אדה\"ז תקס\"ה ח\"ב ע' תקצג ואילך."],["878","51","<b>א\"ח עט\"ב</b>: משלי יב, יד."],["879","52","<b>נקבה תסובב גבר</b>: ירמי' לא, כא."],["880","53","<b>במי נמלך</b>: ראה ב\"ר פ\"ח, ז. רו\"ר פ\"ב, ג. לקו\"ש פ' החודש כרך טז ע' 487 בהערה"],["881","54","<b>נעוץ תחב\"ס</b>: ראה ס\"י פ\"א, מ\"ז. סידור שער הת\"ת צט, ג ואילך. סה\"מ תר\"ל ע' שכ."],["882","55","<b>סומך הוי' לכל הנופלים</b>: תהלים קמה, יד."],["883","56","<b>לנשמות דבריאה וישנו ביחו\"ע</b>: ראה גם לקו\"ת צו יז, רע\"א. וש\"נ. לקמן מאמר ד\"ה והניף הכהן אותם הב' ובהערה 32."],["884","57","<b>שבטי יה</b>: תהלים קכב, ד."],["885","58","<b>י\"ב גבולי אלכסון</b>: ראה ס\"י פ\"ה, מ\"א. ספר הבהיר סמ\"ב. ונמנו בפרדס שער פרטי השמות שכ\"א, פ\"ו-ח. שה\"א עג, א. שע\"ת צב, ג הערה 34."],["886","59","<b>י\"ב בקר והים עומד עליהם</b>: מל\"א ז, כה. מד. דהי\"ב ד, טו."],["887","60","<b>והים. . מל' דאצי'</b>: ראה זהר בהעלותך קנ, ב. הנסמן במאמרי אדה\"א שמות ח\"ב ע' תסג."],["888","61","<b>ונהר יוצא מעדן</b>: בראשית ב, י. ראה גם לקמן מאמר ד\"ה והניף הכהן אותם הב' על יד הערה 57 ואילך."],["889","62","<b>חכ'. . עדן</b>: ראה זהר אד\"ז האזינו רצ, א. יתרו צ, א. מאמרי אדה\"ז תקס\"ה ח\"א ע' קנא. תו\"ח בשלח ח\"א קמא, ב ובהערה 98. לקמן מאמר ד\"ה לה\"ע ההפרש בין שליו\"ט תר\"ב על יד הערה 102. ד\"ה את שבתותי תרי\"ב על יד הערה 35."],["890","64","<b>חכים ולא בחכמה ידיעא</b>: ת\"ז בהקדמה יז, ב."],["891","65","<b>ונהר יוצא מעדן בינה</b>: ראה זהר רע\"מ פינחס רמז, א. וברוב המקומות בזהר פי' ונהר יוצא מעדן היינו בינה [אוה\"ת וירא כ\"ד ע' 1508]."],["892","63","<b>עין לא ראתה. . יעשה למחכי לו</b>: ישעי' סד, ג [ושם: למחכה]."],["893","66","<b>יעשה. . מאן דבעי למנדע</b>: ראה זהר ח\"ש קל, ב. מאמרי אדה\"א ויקרא ח\"ב ע' תקעט. וש\"נ. תו\"ח בראשית לה, ג ובהערה 49."],["894","67","<b>גבורת</b>: אוצ\"ל: גבורה גבורות"],["895","68","<b>שכל עלי' הוא ע\"י גבורת</b>: ראה ביאוה\"ז נח ז, ב."]]],[4801940087,"<b>יו\"ט ב' של פסח תרכ\"ד שנת הסתלקותו</b>\n<b>הפך</b> ים ליבשה<sup data-n=\"896\">1</sup> בנהר יעברו ברגל<sup data-n=\"897\">2</sup>, הפך לעבר בקי\"ס, יעברו להבא. וצ\"ל ענין קי\"ס והעברת הנהר לעתיד ע\"ד האפשר, הנה קי\"ס הוא ענין שינוי מאמר יקוו המים<sup data-n=\"898\">3</sup> כו' כי בתחלה היה הארץ מוקף במים והיה הכל בהעלם, וע\"י מאמר יקוו כו' ותראה היבשה נתגלה הכל, ונכנסו המים בעמקי היבשה וכמ\"ש ולמקוה המים קרא ימים<sup data-n=\"899\">4</sup>, וכל מה שיש ביבשה<sup data-n=\"900\">5</sup> יש בים רק שמובלעים בו וכשפורשים מיד מתים<sup data-n=\"901\">6</sup>, משא\"כ בהולכי היבשה<sup data-n=\"902\">7</sup> יכולים לחיות גם כשהם תלוים באויר, נמצא היבשה הוא ענין התגלות והתחלקות כל הברואים שבה ובים מכוסים ונעלמים, ונראה בחוש ענין עלמא דאתכסיא ועלמא דאתגליא<sup data-n=\"903\">8</sup>, וכשהפך הים ליבשה נתגלה קרקע הים וניגבה ונשוה ליבשה, וכמ\"ש קפאו תהומות בלב ים<sup data-n=\"904\">9</sup> שקפאו וצפו למעלה בכדי שיהיה קל לעבור, ונמצא נתגלה כל ההעלם ולכן ראתה שפחה<sup data-n=\"905\">10</sup> כו' נשמה דעשיה<sup data-n=\"906\">11</sup> הפשוטים שבישראל מאחר שנתגלה לעין כל. וכ\"ה בעולמות הרוחנים עולם עשיה ויצי' נקרא עלמא דאתגליא לגבי עולם הבריאה שנקרא בריאה חדשה מאין ליש שמקבלת ע\"י צמצום א', והמשל בזה הוא כמו ההפרש בין מח' לדיבור<sup data-n=\"907\">12</sup> שעולם הבריאה נק' עולם המח' והשרפים או' קדוש וביצי' ועשי' חיות ואופני הקודש<sup data-n=\"908\">13</sup> אומרים ברוך<sup data-n=\"909\">14</sup> ונקרא יבשה ובשעת קי\"ס נתגלה עולם הבריאה, וכן בריאה לגבי אצי' נקרא יבשה, גם לגבי מל' דאצי' שהמל' נקרא ים<sup data-n=\"910\">15</sup>, ובמל' גופא ט' ספי' נקרא ים ומל' דמל' יבשה, ועד\"ז מל' לגבי בינה דאצי' בינה ים<sup data-n=\"911\">16</sup> ומל' יבשה<sup data-n=\"912\">17</sup> כמו מח' לגבי דיבור<sup data-n=\"913\">*18</sup> ים לגבי פנימיות המל' מח' שבדבור והבינה נקרא ים דחכ'. ועד\"ז מן המאציל לנאצלים הים",[["896","1","<b>הפך ים ליבשה</b>: דרוש ר' הלל.\nלמאמר זה ראה גם ד\"ה לה\"ע קי\"ס תרכ\"א שנדפס לאח\"ז. ראה לעיל מאמר ד\"ה הפך ים הא' הערה 1."],["897","2","<b>הפך. . בנהר יעברו ברגל</b>: תהלים סו, ו."],["898","3","<b>יקוו המים</b>: בראשית א, ט."],["899","4","<b>ולמקוה המים קרא ימים</b>: בראשית שם, י."],["900","5","<b>וכל מה שיש ביבשה</b>: חולין קכז, א. ראה גם תו\"ח שמות ח\"א יח, ג הערה 770."],["901","6","<b>וכשפורשים מיד מתים</b>: ראה חולין שם. שה\"א פד, א ובהנסמן במ\"מ לשם. תו\"ח בשלח ח\"א קסב, סע\"א ואילך. סה\"מ תרכ\"ט ע' ריג. וש\"נ."],["902","7","<b>משא\"כ בהולכי היבשה</b>: ראה הערה שלפנ\"ז."],["903","8","<b>עלמא דאתכסיא ועלמא דאתגליא</b>: ראה זהר בראשית יח, א. ויצא (ס\"ת) קנב, א. קנח, רע\"ב. וארא כט, ב. ת\"ז בהקדמה א, סע\"א ואילך."],["904","9","<b>קפאו תהומות בלב ים</b>: בשלח טו, ח."],["905","10","<b>ראתה שפחה</b>: מכילתא בשלח טו, ב."],["906","11","<b>שפחה. . נשמה דעשיה</b>: ראה גם קהלת יעקב מערכת שפחה הב'."],["907","12","<b>ההפרש בין מח' לדיבור</b>: ראה גם שע\"ת קמו, ב ובהנסמן לשם."],["908","13","<b>הבריאה. . והשרפים. . וביצי' ועשי' חיות ואופני הקודש</b>: ראה סידור שער האלול רל, א. מאמרי אדה\"א ויקרא ח\"א ע' מד. וש\"נ. שע\"ת נח, א ובהערה 3. לקמן מאמר ד\"ה ונקדשתי תקצ\"ח על יד הערה 42. ד\"ה רפאיני הא' על יד הערות 25-7."],["909","14","<b>והשרפים או' קדוש. . ברוך</b>: ישעי' ו, ג. יחזקאל ג, יב. ראה חולין צב, רע\"א ובתוד\"ה ברוך."],["910","15","<b>שהמל' נק ים</b>: ראה זהר בהעלותך קנ, ב. הנסמן במאמרי אדה\"א שמות ח\"ב ע' תסג."],["911","16","<b>בינה ים</b>: ראה ת\"ז תי\"ט (לח, ב)."],["912","17","<b>ומל' יבשה</b>: ראה זהר בראשית יח, א ובמק\"מ שם. ת\"ז תכ\"א (נד, א. סא, א). פרדס שעה\"כ שכ\"ג, פ\"י מערכת יבשה."],["913","*18","<b>ים. . יבשה כמו מח' לגבי דיבור</b>: ראה גם לקמן מאמר ד\"ה והתהלכתי תרט\"ו ובהערה 40."]]],[4801940152,"הוא בחי' שיעור בעצמו בכח<sup data-n=\"914\">18</sup> מה שעתיד להיות בפועל הכנת הצמצום בלשון המקובלים ובזהר בריש הורמנא דמלכא<sup data-n=\"915\">19</sup> גליף גליפו בטה\"ע ובשער היחוד קדמון<sup data-n=\"916\">20</sup>, והרשימו שהוא מל' דא\"ס שלאחר הצמצום<sup data-n=\"917\">21</sup> יבשה והוא מה שהוא מוכן לבא לידי גילוי, אבל הכנת הצמצום נק' עתיד לבא לידי גילוי ונק' ים והעלם, וזהו לשון בריש הורמנא, הורמנא מל' דא\"ס שלפני הצמצום, ונק' שמים וארץ שמים רצון הפשוט דלהיטיב, ומח' דאנא אמלוך<sup data-n=\"918\">22</sup> ארץ (ושמים וארץ אלו הוא כמ\"ד שמים וארץ כאחד נבראו<sup data-n=\"919\">23</sup> ), גליף גליפו הכנה לצמצום והצמצום הוא כמו מיצר הגרון המפסיק בין מח' לדבור בין מוח ללב בין ים ליבשה, וכ\"ז הוא ענין קי\"ס.\n<b>ועתה</b> י\"ל ע\"ד האפשר העברת הנהר דלעתיד, הנה ענין נהר הוא מ\"ש ונהר יוצא מעדן<sup data-n=\"920\">24</sup> להשקות את הגן ולעתיד יעברו בנהר זה שיתגלה למעלה מן הנהר, הענין הוא הנה כתיב ויטע הוי' אלקים<sup data-n=\"921\">25</sup> גן בעדן מקדם כו' ונהר יוצא מעדן להשקות את הגן ומשם יפרד והיה לארבעה ראשים, הנה הנשמה קודם בואה לגוף היא בגן עדן. וצריך להבין איך שייך גן עדן קודם ביאת הנשמה לגוף, הנה ענין העדן שמקדם הוא תענוג הפשוט הנק' שעשועי המלך<sup data-n=\"922\">26</sup> בעצמותו<sup data-n=\"923\">27</sup>, והוא ע\"י כוונה נעלמה שנק' עונג הנעלם והוא ענין במי נמלך<sup data-n=\"924\">28</sup> כו' כידוע בשם הרה\"מ ז\"ל<sup data-n=\"925\">29</sup>, ויטע הוי' אלקים הוא כמ\"ש ואהיה אצלו כו' שעשועים יום יום חו\"ב<sup data-n=\"926\">30</sup> שבעצמיות, גן בעדן מקדם תענוג פרטי שיהיה מל' דא\"ס רצון פשוט הנ\"ל, ובגן זה עדיין אינו שייך מוקדם ומאוחר (לנשמה) וכלשון ואהיה, ושמעתי מאדמו\"ר אמצעי הקושיא בזה שהל\"ל והייתי<sup data-n=\"927\">31</sup>, והתירוץ בזה שהוא\"ו דואהי' מהפך מעתיד לעבר, ולכאורה מה צריך לכתוב ואהיה בוא\"ו יותר טוב לכתוב הייתי, רק פי' שהוא כולל עבר ועתיד כאחד, וזהו ויטע כו' שדילוג הערך שבין תענוג הפשוט למל' דא\"ס יותר מבין ים ליבשה שהוא הצמצום שבין מל' דא\"ס שלפני הצמצום למל' דא\"ס שלאחר הצמצום,",[["914","18","<b>שיעור בעצמו בכח</b>: ראה מק\"מ לזהר בראשית טו, א. מאמרי אדה\"א קונטרסים ע' רא. וש\"נ."],["915","19","<b>בריש הורמנא דמלכא</b>: ראה זהר בראשית טו, א. לקמן מאמר ד\"ה אם בחוקותי הג' הערה 61."],["916","20","<b>ובשער היחוד קדמון</b>: פ\"י."],["917","21","<b>והרשימו שהוא מל' דא\"ס שלאחר הצמצום</b>: ראה לקו\"ת ויקרא בהוספות נא, סע\"ב. נג, ב ואילך. הגהות לד\"ה פתח אלי' תרנ\"ח ס\"ע נח ואילך."],["918","22","<b>ומח' דאנא אמלוך</b>: ראה מאמרי אדה\"ז תקס\"ח ח\"א ע' ז: וכמ\"ש בזהר בפי' וימלוך אנא אמלוך. הנסמן במאמרי אדה\"א דברים ח\"ג ע' תתצד. לעיל מאמר ד\"ה והניף ידו תר\"י הערה 16."],["919","23","<b>שמים וארץ כאחד נבראו</b>: ראה חגיגה יב, א."],["920","24","<b>ונהר יוצא מעדן</b>: בראשית ב, י."],["921","25","<b>ויטע הוי' אלקים</b>: שם ב, ח."],["922","26","<b>העדן. . שעשועי המלך</b>: ראה גם שה\"א סא, ב."],["923","27","<b>שעשועי המלך בעצמותו</b>: ראה עמה\"מ שער זה. מאמרי אדה\"א שמות ח\"ב ע' תנג. קונטרסים ע' שמה ובהנסמן בהנ\"ל."],["924","28","<b>במי נמלך</b>: ראה ב\"ר פ\"ח, ז. רו\"ר פ\"ב, ג. לקו\"ש פ' החודש כרך טז ע' 487 בהערה."],["925","29","<b>בשם הרה\"מ ז\"ל</b>: ראה גם לעיל מאמר ד\"ה הפך ים הא' ובהערה 12."],["926","30","<b>ואהי'. . שעשועים יום יום חו\"ב</b>: משלי ח, ל. ראה גם לעיל מאמר ד\"ה והניף ידו תר\"י ובהערה 12."],["927","31","<b>ושמעתי מאדמו\"ר אמצעי. . והייתי</b>: ראה גם פלח הרמון שה\"ש ע' 252."]]],[4801940215,"והוא כמו הנטיעה שהוא יותר בריחוק הערך מזריעה שמחטה א' נעשה הרבה כמוהו, אבל מגרעין נעשה אילן, ומשם יפרד לד' נהרות ד' בחי' חו\"ב דיום יום הנ\"ל ומדות דלהיטיב, ומל' דא\"ס שנק' מח' דאנא אמלוך, ונהר הרביעי הוא פרת<sup data-n=\"928\">32</sup> הוא דמעיקרא<sup data-n=\"929\">33</sup> עיקר הכוונה ולעתיד יתגלה עבר הנהר כוונה נעלמה ע\"י ג\"ע זה ויתגלה עונג הנעלם<sup data-n=\"930\">34</sup>.",[["928","32","<b>ונהר הרביעי הוא פרת</b>: בראשית ב, יד."],["929","33","<b>הוא דמעיקרא</b>: בכורות נה, ב."],["930","34","<b>הנעלם</b>: ראה לקמן ברשימת הכת\"י."]]],[4801940088,"<b>[תרכ\"א]</b>\n<b>להבין</b> ענין קי\"ס<sup data-n=\"931\">1</sup>, הנה מתחילה יש להבין ענין ים וארץ מה הם הוא בחי' עלמא דאתכסיא ועלמא דאתגליא<sup data-n=\"932\">2</sup> וביאור עניינם למטה ולמעלה מעלה עד רום המעלות, הנה מל' דבריאה נק' ים<sup data-n=\"933\">3</sup> להיותה מיו\"ד כלים הפנימי' דמל' דאצי'<sup data-n=\"934\">4</sup> ולכן מהווה ברואים מאין ליש והברואים המתהוים ממנה המה בבחי' ביטול במקורם כדוגמת אותיות המחשבה באדם שמובלעים ובטלים באור השכל המקיפם לכן אינם נגלי' לזולתן, ולכן נק' ים ע\"ד הברואים שבים שהם הדגים שמובלעים במים שמהם נתהוו ואם היו פורשים מהם מיד מתים<sup data-n=\"935\">5</sup> כן למעלה מלאכים ונשמות המתהווים מבחי' מל' דבריאה הם בתכלית הביטול באור אלקי המהווה אותם מאין ליש כו', משא\"כ מל' דיצי' מקבל מבחי' יו\"ד כלים האמצעים דמל' דאצי' וכן מל' דעשי' מקבלת מבחי' יו\"ד כלים החיצונים דמל' דאצי' והוא ע\"ד אותיות הדיבור ואותיות המעשה שירדו מבחי ' נפרד מן הנפש ולכן הם נגלים לזולתו ובחי' אלו נק' ארץ<sup data-n=\"936\">6</sup>",[["931","1","<b>להבין ענין קי\"ס</b>: הנחת ר\"ה מדרוש כ\"ק אדמו\"ר הצ\"צ.\nמאמר הצ\"צ הוא כנראה הנדפס באוה\"ת בשלח ע' תקסח ואילך.\nראה גם לעיל מאמר ד\"ה הפך ים תרכ\"ד שנדפס לפנ\"ז. אוה\"ת ויקרא כרך ד ע' א'ג ואילך. ע' א'יז ואילך.\nראה עוד ע\"ד המאמר לקמן ברשימת הכת\"י."],["932","2","<b>ים וארץ. . עלמא דאתכסיא ועלמא דאתגליא</b>: ראה לקמן מאמר ד\"ה ונקדשתי תקצ\"ח על יד הערה 54. ד\"ה שבת שבתון על יד הערה 39. ד\"ה בסוכות תשבו הב' על יד הערה 99. ביאור למאמר ד\"ה והתהלכתי תר\"ב על יד הערה 109. ד\"ה והתהלכתי תרכ\"ב על יד הערה 93. מאמרי אדה\"א שמות ח\"א ע' חצר. וש\"נ. תו\"ח בשלח ח\"א קלח, ג הערה 312. אוה\"ת בשלח כאן. וש\"נ. סה\"מ תרכ\"ט ע' קמט. וש\"נ. ע' רכח."],["933","3","<b>מל'. . ים</b>: ראה זהר בהעלותך קנ, ב. הנסמן במאמרי אדה\"א שמות ח\"ב ע' תסג."],["934","4","<b>מל' דבריאה. . מיו\"ד כלים. . דמל' דאצי'</b>: ראה ע\"ח שער השמות שער מ\"ד, פ\"א-ב. לקמן מאמר ד\"ה את שבתותי תרי\"ב ובהערה 26."],["935","5","<b>הברואים שבים. . מיד מתים</b>: ראה חולין קכז, א. שה\"א פד, א ובהנסמן במ\"מ לשם. תו\"ח בשלח ח\"א קסב, סע\"א ואילך. סה\"מ תרכ\"ט ע' ריג. וש\"נ."],["936","6","<b>מל'. . ארץ</b>: ראה זהר בראשית יח, א ובמק\"מ שם. ת\"ז תכ\"א (נד, א. סא, א). פרדס שעה\"כ שכ\"ג, פ\"י מערכת יבשה."]]],[4801940153,"וע\"ד הברואים שביבשה שנתהוו מן העפר ואעפ\"כ הם נפרדי' ממקורם כן למעלה הנשמות ומלאכים דיצי' ועשי' אינם כ\"כ בבחי' ביטול ונראים ליש קצת כו', וזהו בחי' עלמין סתימין דלא אתגליין ועלמין דאתגליין המבואר במאמ' פתח אליהו<sup data-n=\"937\">8</sup> כו', אך למעלה יותר הנה המל' דאצי' הוא בחי' ממוצע בין אצי' לבריאה<sup data-n=\"938\">9</sup> יצירה ועשי' לכן צ\"ל כלול משני הבחי', זהו בחי' ים ויבשה<sup data-n=\"939\">10</sup>, כי בנין המל' בבחי' אצי' מקבלת מכל הי\"ס דאצי' הן בבחי' הבנין שלה ידוע דבנין המל' מעשיראה דכולהו<sup data-n=\"940\">12</sup> ממל' שבחכ'<sup data-n=\"941\">11</sup> נמשך בחי' חכ' שבמל' וממל' דבינה שבמל'<sup data-n=\"942\">13</sup> וכן עד\"ז בכל הי\"ס כו', והן בבחי' קבלת השפע אחר שנבנית בבחי' פרצוף שלם מקבלת מכל הי\"ס כמאמר כל הנחלים הולכים אל הים<sup data-n=\"943\">14</sup> אותיות אלקים<sup data-n=\"944\">15</sup> שהוא בחי' המל' דאצי' וכל הנחלים שהוא בחי' י\"ס דאצי' הולכים ומשפיעים שפע בבחי' המל' דאצי' כו', והנה בחי' זאת נק' ים להיותה מקבלת מבחי'<sup data-n=\"945\">7</sup> הי\"ס דאצי' ומיוחדת עמהם בתכלי' הביטול כמאמר לך ה' הממלכה<sup data-n=\"946\">16</sup> כו' ונק' ים סוף<sup data-n=\"947\">17</sup> להיותה סופא דכל דרגין<sup data-n=\"948\">18</sup> דאצי', משא\"כ בחי' מל' דאצי' היורדת בג' עולמות דבי\"ע להשפיע בהם נק' יבשה ונק' דבר ה' כו' להיותה מהווה כל הנבראי' בבחי' פירוד כמאמר ומשם יפרד<sup data-n=\"949\">19</sup> כו'. [... והגם שמבואר למעלה שאפי' בחי' מל' דבריאה נק' בחי' מח' והנבראי' דבריאה הם בתכלית הביטול הנה ידוע דדיבור שבעליון נעשה מח' לתחתון<sup data-n=\"950\">20</sup> כמו דיבור הרב נעשה ממנו אותיות המח' אצל התלמיד כו' כן המח' דבריאה נחשב בחי' דיבור לגבי בחי' אצי' כו' וד\"ל. ..].\n<b>והנה</b> למעלה בבחי' אצי' עצמו יש ג\"כ שני בחי' עלמא דאתכסיא ועלמא דאתגליא והיינו בחי' ו\"ה דשם הוי' שהוא בחי' המדות דאצי' ומל' דאצילות הוא בחי' עלמא דאתגליא כי המדות דאצי' הם מקור לגילוי הנבראים מאין ליש ולכן נק' בשם יבשה משא\"כ בחי' י\"ה שהם בחי' חו\"ב דאצילות הם למעלה מהיות מקור לנבראים לכן המה בבחי' ההעלם עדיין ולכן נק' בשם עלמא דאתכסיא ולכן נק' בחי' ים [... וכמבואר במ\"א בענין הנסתרו' לה' אלקינו הוא בחי' י\"ה בחי' חו\"ב והנגלות כו'",[["937","8","<b>עלמין. . במאמ' פתח אליהו</b>: ת\"ז בהקדמה יז, א."],["938","9","<b>המל'. . ממוצע בין אצי' לבריאה</b>: ראה תו\"א יתרו קט, ב. לקו\"ת מסעי צב, ב. שה\"ש ח, ב."],["939","10","<b>המל' דאצי'. . ים ויבשה</b>: ראה גם לקו\"ת צו יד, ב. מאמרי אדה\"ז תק\"ע ע' ע' וע' עו. מאמר ד\"ה ואתה הרם את מטך תקס\"ג בתו\"ח בשלח ח\"א קלט, ב. אוה\"ת בשלח כאן ע' תקסט. המשך והחרים תרל\"א ע' מ ואילך. סה\"מ תרל\"ה ח\"א ע' רנט."],["940","12","<b>המל' מעשיראה דכולהו</b>: ראה זהר פינחס רנג, רע\"ב."],["941","11","<b>דבנין המל'. . ממל' שבחכ'</b>: ראה ע\"ח שער מיעוט הירח של\"ו, פ\"א. סידור שחרית נט, ג. תו\"א מג\"א צב, א. לקו\"ת מסעי פט, ד. מאמרי אדה\"א ויקרא ח\"ב ע' תשצה. וש\"נ. שעה\"י קמא, ב ובהערה 41. תו\"ח יתרו ח\"ב רסח, ג."],["942","13","<b>שבמל'</b>: ג: בינה שבמל'."],["943","14","<b>כל הנחלים הולכים אל הים</b>: קהלת א, ז."],["944","15","<b>אל הים אותיות אלקים</b>: רמ\"ז ר\"פ פקודי (ס\"ע רמז)."],["945","7","<b>מבחי'</b>: ג: בבחי'."],["946","16","<b>לך ה' הממלכה</b>: דהי\"א כט, יא."],["947","17","<b>ונק' ים סוף</b>: זהר רע\"מ פינחס רנו, ב."],["948","18","<b>להיותה סופא דכל דרגין</b>: ראה זהר בשלח נו, א. פקודי רכו, סע\"א."],["949","19","<b>ומשם יפרד</b>: בראשית ב, י."],["950","20","<b>דדיבור שבעליון נעשה מח' לתחתון</b>: ראה גם מאמרי אדה\"א קונטרסים ע' תקמז. וש\"נ. תו\"ח וארא ח\"א עו, א. וש\"נ."]]],[4801940216,"ו\"ה<sup data-n=\"951\">21</sup> נגלות לנו כו', אך הנה ידוע שהגם שבחי' חו\"ב הם למעלה מהיות מקור לנבראים מ\"מ בהם נמדד איכות כל הנבראים באיזה אופן יתחדשו מאין ליש וידוע דמח' עליונה אינו דומה למחשבת בני אדם שממנה מתהווה<sup data-n=\"952\">22</sup> מציאות דבר כו' וא\"כ יש שורש נעלם לכל הנבראים בבחי' מח' עליונה דבינה עילאה וזהו בחי' עלמין סתימין היינו כל העולמו' דבי\"ע הם סתומים ונעלמים במח' עליונה דבינה נק' ים והתגלותם בבחי' המדות ומל' דאצי' נק' יבשה לגבי העלם ה' כו' וד\"ל. ..]. ולמעלה למעלה הנה הכתר הוא ממוצע<sup data-n=\"953\">23</sup> בין המאציל א\"ק ובין י\"ס דאצי' כי מל' דא\"ק הוא בחי' גילוי כל האורות עליונים שבא\"ק, אך אע\"פ שהמל' הוא בחי' גילוי לגבי א\"ק מ\"מ היא נבדל בערך מבחי' י\"ס דאצי' ולכן נק' בשם עתיק לגבי אצי'<sup data-n=\"954\">24</sup> כי נעתק ומובדל בערך מבחי' הי\"ס ולכן צריך להיות ירידה גדולה להיות ממנה שרש ומקור לנאצלי' וזהו בחי' אריך שבא בבחי' שרש ומקור לי\"ס דאצי' וזהו שני בחי' דים ויבשה בכתר עצמו, היינו בחי' עתיק הוא בחי' ים להיותו בבחי' ההעלם בתכלית ובחי' אריך נק' יבשה להיותו מקור להתגלות הי\"ס דאצי' [... ומקור הגילוי בחי' גילוי יחשב לגבי עצמו' ההעלם שאינו מקור לגילוי עדיין כו'. ..]. ועוד למעלה יותר הנה ראשית הקו הנגלה בכתר דא\"ק נק' בחי' עתיק לגבי כתר דא\"ק כמבואר בע\"ח דגם בכתר דא\"ק יש כדמות עתיק לעילא מגולגלתא דילי'<sup data-n=\"955\">25</sup> כו', אך הגם שנק' עתיק לגבי הכתר דא\"ק להיות שהכתר נמשך ממנו בדרך דילוג עד שנק' אדם דבריאה לגבי ראשית הקו מ\"מ נק' בחי' יבשה להיותו בא בהם בדרך התלבשות וכידוע שכמו שהמל' דאצי' מתלבשת בג' עולמות דבי\"ע כן יש בחי' בי\"ע בכללות ההשתלשלו' א\"ק הוא אדם דבריאה<sup data-n=\"956\">26</sup> ועתיק ואריך הוא בחי' אדם דיצי' וע\"ס דאצי' הוא בחי' אדם דעשי' והקו הוא מתלבש בהם להחיותם ונק' חי העולמים<sup data-n=\"957\">27</sup> כו' ונק' ממכ\"ע<sup data-n=\"958\">28</sup> כו' [... וע\"ד חיות הנפש בגוף הגם שאין ערוך כלל מג ש ם הגוף לגבי חיות הרוחני מ\"מ הקב\"ה הוא מפליא לעשות ומקשר חיות הרוחני עם גשם הגוף עד שמתאחדים בתכלי' להיות הגוף חי חיים הרוחני' כן למע' אע\"פ שאין ערוך אפי' מכתר דא\"ק לגבי ראשית הקו כו' מ\"מ מתלבש בחי' אא\"ס שבבחי' ראשית הקו להחיותם ממש והוא ע\"י כח המפליא לעשות שהוא העצמו' שקודם הצמצום כו' הפועל חיבור זה",[["951","21","<b>הנסתרו'. . י\"ה. . והנגלות כו' ו\"ה</b>: נצבים כט, כח. ראה ת\"ז ת\"ע קכט, א. לקו\"ת פקודי ג, ב ובהנסמן במ\"מ לשם."],["952","22","<b>דמח' עליונה. . שממנה מתהווה</b>: ראה פרדס שער הצחצחות שי\"א, פ\"ג. לקו\"ת מסעי צה, א. דרושים לר\"ה נה, סע\"א ואילך. שה\"ש יז, ג ואילך. סהמ\"צ להצ\"צ ע' נח ואילך."],["953","23","<b>הכתר הוא ממוצע</b>: ראה ע\"ח ש' דרושי אבי\"א שמ\"ב, פ\"א. תו\"ח שמות ח\"א יא, ג הערה 509."],["954","24","<b>מל' דא\"ק. . עתיק לגבי אצי'</b>: ראה ע\"ח שער סדר אצי' ש\"ג, פ\"ב. לקו\"ת מסעי צה, ב. לקמן מאמר ד\"ה ענין זכר בא לעולם על יד הערה 10. ד\"ה אם בחוקותי הא' על יד הערה 108."],["955","25","<b>כדמות עתיק לעילא מגולגלתא דילי'</b>: ראה ע\"ח שער שביה\"כ ש\"ט, רפ\"ו. לקו\"ת מסעי צה, ב. המשך תער\"ב ח\"ג ע' א'שצז."],["956","26","<b>א\"ק הוא אדם דבריאה</b>: ראה מאמרי אדה\"ז על ענינים בתחילתו ובהנסמן במ\"מ לשם. אוה\"ת על ענינים ע' עז. סה\"מ תש\"ח ע' 113 בהערה. הנסמן בסה\"מ תרל\"ב ח\"א ע' ד."],["957","27","<b>והקו. . ונק' חי העולמים</b>: ראה גם תו\"ח בשלח ח\"א קסא, א. וש\"נ."],["958","28","<b>והקו. . ונק' ממכ\"ע</b>: ראה גם תו\"א ויקהל קיג, סע\"ג."]]],[4801940269,"והתלבשות זאת כו' וד\"ל. ..]. משא\"כ ההעלם דרשימו נק' ים כי הוא מאיר בבחי' מקיף וסובב על כל העולמות מריש כל דרגין דמחה\"ק דא\"ק עד תחתית עולם העשי' בהשוואה אמיתי' כי כולם אין ערוך אליו בהשוואה כו' וד\"ל. ולכן נק' ההעלם דרשימו בשם ים כו' [... או אפ\"ל דגם ההעלם דרשימו נק' יבשה להיותו בא בבחי' גילוי אחר הצמצום וההעלם כו' ונק' טהירו תתאה<sup data-n=\"959\">*29</sup> כו' משא\"כ אותיות דגליף גליפו<sup data-n=\"960\">29</sup> שהוא מה ששיער בעצמו בכח<sup data-n=\"961\">30</sup> לפני הצמצום מה שעתיד להיות בפועל בבחי' טה\"ע שהוא בחי' מל' דא\"ס<sup data-n=\"962\">*31</sup> זהו בחי' ים כו' וד\"ל. ..].\n<b>אך</b> כ\"ז הוא כשנמשך כסדר ההשתלשלו' כו' [... כי כל ה'<sup data-n=\"963\">31</sup> נעשה ע\"י מאמר יקוו המים<sup data-n=\"964\">32</sup> כו' ותראה היבשה כו' שיתפרש גם עד רום המעלו' דבחי' המים הוא בחי' שפע העליונה דבחי' מל' דא\"ס שיוכלל האור במאור שהוא ענין הצמצום ועי\"ז ותראה היבשה שהוא בחי' גילוי הרשימו שאחר הצמצום כו' וד\"ל. ..], ולכן נמשך ממדריגה למדריגה מהעלם אל הגילוי [... כי הגילוי שבעליון נחשב העלם לגבי התחתון כנ\"ל. ..] עד שנמשך גילוי הנבראים מאין ליש ממש עד שהיש הוא מסתיר על האין השופע בו ונמשך בחי' פירוד גמור כמאמר ומשם יפרד כו' אך בשעת קי\"ס האיר מבחי' עתיקא עד רום המעלות [... והיינו ג\"ר דע\"י ועד רום המעלו' הוא בבחי' שעשועי המלך בעצמותו<sup data-n=\"965\">33</sup> שהוא גילוי העצמו' לעצמו למעלה מהיות מקור להשפעה אפי' בבחי' א\"ס הנק' מל' דא\"ס כו' ובחי' זאת מאיר בחו\"ב שבעצמו' וכמאמר ואהי' שעשועי' יום יום<sup data-n=\"966\">34</sup> כו' וד\"ל. ..] ולגבי גילוי זה כל המדריגות דהעלם וגילוי שוים כי לפניו נגלו כל תעלומות<sup data-n=\"967\">35</sup> כו' ובחי' זאת נק' רוח קדים מקדמונו של<sup data-n=\"968\">36</sup> עולם<sup data-n=\"969\">37</sup> ונק' אנכי מי שאנכי<sup data-n=\"970\">38</sup> כו' ואז האיר עצמו' ההעלם דים ונעשה בבחי' גילוי כמו הגילוי דיבשה ממש וזהו שלא כסדר ההשתלשלו' אשר רק הארה בעלמא מן ההעלם בא לידי גילוי כו', והנה ע\"י גילוי הנ\"ל דעתיקא דקמי' שוים העלם וגילוי",[["959","*29","<b>דרשימו. . טהירו תתאה</b>: ראה גם לקמן מאמר ד\"ה אם בחוקותי הג' על יד הערה 62."],["960","29","<b>דגליף גליפו</b>: ראה זהר בראשית טו, א. לקמן מאמר ד\"ה אם בחוקותי הג' הערה 61."],["961","30","<b>ששיער בעצמו בכח</b>: ראה מק\"מ לזהר בראשית טו, א. מאמרי אדה\"א קונטרסים ע' רא. וש\"נ. לקמן מאמר ד\"ה הנה כו' והצרוע תקצ\"ט על יד הערה 21. ד\"ה והתהלכתי תרט\"ו על יד הערה 235. ד\"ה להבין וכו' ונתתי משכני על יד הערה 14."],["962","*31","<b>טה\"ע. . מל' דא\"ס</b>: ראה גם מאמרי אדה\"א דברים ח\"ג ע' תתפט."],["963","31","<b>ה'</b>: בג: הנ\"ל."],["964","32","<b>יקוו המים</b>: בראשית א, ט."],["965","33","<b>שעשועי המלך בעצמותו</b>: ראה עמה\"מ שער זה. מאמרי אדה\"א שמות ח\"ב ע' תנג. קונטרסים ע' שמה ובהנסמן בהנ\"ל. וראה גם לקמן מאמר ד\"ה את שבתותי תרי\"ב ובהערה 130."],["966","34","<b>בחו\"ב. . ואהי' שעשועי' יום יום</b>: משלי ח, ל. ראה גם לעיל מאמר ד\"ה והניף ידו תר\"י ובהערה 12."],["967","35","<b>לפניו נגלו כל תעלומות</b>: ע\"פ ברכת זכרונות."],["968","36","<b>רוח קדים מקדמונו של עולם</b>: בשלח יד, כא. ראה גם תו\"ח בשלח ח\"א קמג, ב. וש\"נ."],["969","37","<b>מקדמונו של עולם</b>: ב\"ר פל\"ח, ז. זהר לך פד, א."],["970","38","<b>אנכי מי שאנכי</b>: ראה תניא מהדו\"ק ספמ\"ט. לקו\"ת להאריז\"ל תולדות כז, יט בשם הזהר. אבן עזרא תולדות שם. מאמרי אדה\"ז תקס\"ב ח\"א ע' יד. פרשיות התורה ח\"א ע' רט ובהנסמן במ\"מ לשם."]]],[4801940319,"נגלה ממילא ההעלם דרשימו בבחי' האצילות כו' [.. וכן אותיות דגליף גליפו האירו בבחי' הרשימו כו'. ..] וממילא האיר בחי' ההעלם דבחי' העליונה שבמל' דאצי' הנק' ים בבחי' המל' דאצי' המתלבשת בבי\"ע שנק' יבשה וממילא נגלה הביטול בבחי' נשמות דבי\"ע כמו למע' שהוא בחי' הביטול דנשמו' הנכללי' בים העליון הנק' נוני ימא<sup data-n=\"971\">39</sup> כו', וזהו ובני ישראל הם נשמו' דבי\"ע [... שהם בני ישראל דלעילא כי ברא כרעא דאבוה<sup data-n=\"972\">41</sup> והיינו שנמשכו מנה\"י דז\"א הנמשך בבחי' מוחין למל' דאצי' ובחי' המוחין דמל' מתלבשים בזו\"נ דבי\"ע להוליד נשמו' מפנימי' הכלים שבהם כו' וד\"ל. ..]. הלכו ביבשה<sup data-n=\"973\">40</sup> בתוך הים היינו שנכללו בבחי' ביטול דים העליון שהאיר עליהם בבחי' גילוי ומחמת זה עלו ונכללו באצי' או שהאיר אצי' בבי\"ע כו' [... וזהו ההפרש בין ב' הפירושים של הזהר והאריז\"ל<sup data-n=\"974\">42</sup> כו' וד\"ל. ..].\n<b>והנה</b> בדרך כלל כל המדריגו' דים ויבשה הנ\"ל שלמעלה מן החכ\"ע דאצי' הוא ב' בחי' הוי'<sup data-n=\"975\">43</sup> שקודם הפסיק טעמא ולאחריו וב' בחי' הנ\"ל האירו בבני ישראל בשעת קי\"ס רק הוי' שקודם הפסיק טעמא האיר בהם בבחי' אמונה כמ\"ש ויאמינו בהוי'<sup data-n=\"976\">44</sup> כו' רק שהאמונה האירה בהם בבחי' גילוי עד שפעל בחי' ביטול בנפשם כו' אבל הוי' שאחר הפסיק טעמא האיר בהם בבחי' ראי' ממש ועל זה כתוב ויראו העם את הוי'<sup data-n=\"977\">45</sup> כו' וד\"ל [... ובמכי\"ק<sup data-n=\"978\">46</sup> כתוב שזה הי' ע\"י אכילת מצה שבליל א' של פסח שנמשך בהם עי\"ז בחי' אמונה בהעלם עי\"ז האיר ביום הז' בגילוי בחי' הסובב וזהו ששת ימים תאכל מצות<sup data-n=\"979\">47</sup> ועי\"ז וביום השביעי עצרת להוי' אלקיך כו' וד\"ל. ..], רק אע\"פ שהאיר הסובב בגילוי לא האיר רק בבחי' אמונה רק שהאמונה היתה בגילוי ולא כמו ע\"י אכילת מצה שנמשך האמונה רק בהעלם כו' אך בחי' הוי' שאחר הפסיק טעמא שהוא בחי' ממכ\"ע האיר בהם בבחי' ראי' ממש כנ\"ל כנלע\"ד בדרך אפשר. ..].\n<b>והנה</b> קי\"ס הי' ע\"י ג' פסוקי' דויסע ויבוא ויט<sup data-n=\"980\">48</sup> וידוע דג' פסוקי' הנ\"ל הם כנגד ג' אבות<sup data-n=\"981\">49</sup> שהם בחי' חג\"ת כו' אך עיקר קי\"ס הי' ע\"י פסוק השלישי דויט",[["971","39","<b>דנשמו'. . נוני ימא</b>: ראה גם תו\"ח בשלח ח\"א רז, א. וש\"נ. לקמן מאמר ד\"ה וספרתם הה' ע' רצה וע' שיג."],["972","41","<b>ברא כרעא דאבוה</b>: ראה ע\"ח שער פרקי הצלם שכ\"ד, פ\"א בשם רז\"ל. מאמרי אדה\"א קונטרסים ע' שלט. וש\"נ. תו\"ח ויקהל ח\"ב שצו, א הערה 118."],["973","40","<b>ובני ישראל. . הלכו ביבשה</b>: בשלח יד, כט."],["974","42","<b>ב' הפירושים של הזהר והאריז\"ל</b>: ראה גם לקמן מאמר ד\"ה ונקדשתי תקצ\"ח ובהערה 58."],["975","43","<b>ב' בחי' הוי'</b>: תשא לד, ו. זהר אד\"ר נשא קלח, רע\"א. ראה הנסמן במאמרי אדה\"א נ\"ך ע' תקעז. תו\"ח בשלח ח\"א קנז, ב הערה 361."],["976","44","<b>ויאמינו בהוי'</b>: בשלח יד, לא."],["977","45","<b>ויראו העם את הוי'</b>: התחלת הכתוב ויאמינו. ראה ת\"ז תכ\"א ס, ב. הובא באוה\"ת בשלח ע' תל. מאמרי אדה\"א הנחות תקע\"ז ע' נא."],["978","46","<b>ובמכי\"ק</b>: ובמאמר כתב יד קדשו (של הצ\"צ). התוכן — ראה אוה\"ת בשלח כאן ע' תקעד. לקמן מאמר ד\"ה והתהלכתי תרכ\"ב הערה 50."],["979","47","<b>ששת ימים תאכל מצות</b>: פ' ראה טז, ח."],["980","48","<b>קי\"ס. . דויסע ויבוא ויט</b>: בשלח יד, יט. כ. כא. זהר בשלח נא, ב. וראה זח\"ב רסט, ב. ער, א. פרדס שער פרטי השמות שכ\"א, פ\"ה. אוה\"ת כאן ע' תקעה וע' תיט. המשך והחרים תרל\"א ע' סב."],["981","49","<b>דויסע ויבוא ויט. . אבות</b>: ראה זהר בשלח שם."]]],[4801940368,"שבו עיקר קי\"ס דכתיב בי' ויולך את הים כו' והוא כנגד בחי' יעקב שנק' בריח התיכון<sup data-n=\"982\">50</sup> שהוא בחי' ת\"ת קו האמצעי הכולל שני הקוין דחו\"ג<sup data-n=\"983\">51</sup> ולכן נק' בשם אויר<sup data-n=\"984\">52</sup> הכולל אש ומים וידוע דקו האמצעי שרשו בפנימי' הכתר<sup data-n=\"985\">53</sup> הנק' אויר קדמון<sup data-n=\"986\">54</sup> שהוא למעלה מן החכ' וזהו אויר אור יו\"ד<sup data-n=\"987\">55</sup> שהוא בחי' אור שנמשך ממנו שפע בבחי' יו\"ד דחכמה ולכן על ידו דייקא הי' בחי' קי\"ס כי בחי' פנימי' הכתר הוא גילוי העצמות שלמעלה מבחי' העלם וגילוי והוא הנק' עתיקא [שנעתק ומובדל מכל מיני העלם וגילוי לכן בכחו להביא ההעלם לידי גילוי כו' ובחי' עתיקא האיר בז' של פסח ולכן אז הי' קי\"ס כו' [ובמכי\"ק<sup data-n=\"988\">*56</sup> כתוב שזהו מארז\"ל מה שביעי רשות<sup data-n=\"989\">56</sup> כו' כי רשות הוא עלמא דחירות בחי' שאין בו הגבלה וצמצום כלל כנ\"ל שהאיר בחי' עתיקא שלמעלה מבחי' צמצום דחכ' ולכן מה תצעק אלי ר\"ת אמת<sup data-n=\"990\">57</sup> כי עתיקא נק' אמת כי הוא אחד האמת שהוא לבדו הוא ואין זולתו<sup data-n=\"991\">58</sup> גם אחר שנברא העולם כמו קודם שנבה\"ע בלי שום שינוי כלל והיינו אני ראשון<sup data-n=\"992\">59</sup> קודם שנבה\"ע ואני אחרון לאחר שנבה\"ע בלי שום שינוי כלל כי מבלעדי אין אלקים שאין הצמצום מסתיר לפניו ית' ומה שכל העולמו' נראים למציאו' דבר מה הוא מצד הצמצום וההסתר וכיון שלפניו אין הצמצום מסתיר נמצא כל העולמו' הם אין ואפס המוחלט לפניו נמצא שהוא לבדו גם עכשיו כו' כבתחילה ולכן נק' אמת כי הוא לבדו אמיתית המציאות משא\"כ כל העולמות נראים למציאות מצד הצמצום אבל באמת הם אפס המוחלט. וזהו שרמז מה תצעק אלי ואמרו בזהר בעתיקא תליא<sup data-n=\"993\">60</sup> כו' פי' כי שם אין מגיע אתדל\"ת כו' ואין מועיל הצעקה כו' [... רק שנעשה קי\"ס מעצמו בזכות אבות והעיקר הוא בחי' יעקב ת\"ת ששרשו בפנימי' הכתר בחי' עתיקא כנ\"ל. ..], ולכן תפילת ערבית שתיקן יעקב<sup data-n=\"994\">61</sup> הוא ג\"כ רשות<sup data-n=\"995\">62</sup>",[["982","50","<b>יעקב שנק' בריח התיכון</b>: תרומה כו, כח. זהר שם. ראה גם מאמרי אדה\"א ויקרא ח\"א ע' פד. וש\"נ. סה\"מ תרכ\"ט ע' קיז. וש\"נ."],["983","51","<b>ת\"ת. . דחו\"ג</b>: ראה זהר רע\"מ צו כח, סע\"א. ע\"ח שער פרטי עי\"מ שכ\"ז, פ\"ב. תו\"ח בראשית ח, ג הערה 52."],["984","52","<b>ת\"ת. . אויר</b>: מאו\"א מערכת אויר קדמון אות קנג. תו\"א מקץ מג, ב."],["985","53","<b>דקו האמצעי. . הכתר</b>: מובא במאמרי אדה\"ז על פרשיות התורה ח\"ב ע' תרמה בשם הע\"ח. ראה שערי אורה לר\"י גיקטלייא שער ה (ע' סג)."],["986","54","<b>הכתר הנק' אויר קדמון</b>: ראה ת\"ז תס\"ט קד, ב. תז\"ח צו, ג. עבודת הקודש ח\"א פ\"ג. מאו\"א שם. המשך והחרים תרל\"א ע' סב. מים רבים תרל\"ו ע' קיב [ושם נדפס: אור. וצ\"ל כבגוכתי\"ק: אוי\"ר]."],["987","55","<b>אויר אור יו\"ד</b>: ראה זהר בראשית טז, ב. מאמרי אדה\"א ויקרא ח\"ב ע' תנ. וש\"נ."],["988","*56","<b>ובמכי\"ק</b>: ובמאמר כתב יד קדשו (של הצ\"צ). התוכן — ראה אוה\"ת בשלח כאן ע' תקעה. לקמן מאמר ד\"ה והתהלכתי תרכ\"ב הערה 50."],["989","56","<b>מה שביעי רשות</b>: פסחים קכ, א. מכילתא ורש\"י בא יב, טו. שו\"ע אדה\"ז הל' פסח סתע\"ה, סל\"ב. ראה ביאוה\"ז להצ\"צ כרך א ע' צה. לקו\"ש חה\"פ כרך כב ע' 33. וש\"נ."],["990","57","<b>מה תצעק אלי ר\"ת אמת</b>: בשלח יד, טו. לקו\"ת [ושער הפסוקים] להאריז\"ל שם. פע\"ח שער הסליחות שי\"ב, פ\"ח. אוה\"ת ויקרא כרך ד ע' א'ז בשם המק\"מ — ראה מק\"מ לזהר בשלח נב, ב בשם ס' ח\"י."],["991","58","<b>הוא אחד. . זולתו</b>: ראה תניא פל\"ה בהגהה."],["992","59","<b>אני ראשון</b>: ישע' מד, ו."],["993","60","<b>מה תצעק. . בעתיקא תליא</b>: זהר בשלח מח, א. נב, ב."],["994","61","<b>תפילת ערבית שתיקן יעקב</b>: ברכות כו, ב."],["995","62","<b>תפילת ערבית. . רשות</b>: ברכות כז, ב. ראה לקו\"ת סוכות פ, סע\"ג. שה\"ש כד, ב. ביאוה\"ז ח\"ש יג, סע\"ד ואילך. ולהצ\"צ כרך א ע' פה ואילך. סה\"מ תרס\"ח ע' קע. לקו\"ש ויצא כרך כה ס\"ע 155 ואילך."]]],[4801940414,"עלמא דחירות בחי' עתיקא כנ\"ל ולכן נאמר במדרש ופרצת ימה וקדמה<sup data-n=\"996\">63</sup> הנאמר ביעקב שע\"י קדמה שהוא בחי' רוח קדים נקרע הים הנק' ימה<sup data-n=\"997\">64</sup> כו' ע\"כ ממכי\"ק* ].\n<b>והנה</b> ארז\"ל זיווג שני לפי מעשיו<sup data-n=\"998\">65</sup> הנה כ\"ה בכללות נש\"י הנה מתחילה בעת יצי\"מ הי' היחוד דהקב\"ה וכנ\"י לא לפי מעשיהם כי הי' אתדל\"ע מצד עצמו כי אז היו בנ\"י בתכלית הקטנות ולא היו יכולים לעורר כלל מלמטה ולכן הי' אז בחי' יחוד קוב\"ה ושכינתי' בעת יצי\"מ וקי\"ס מצ\"ע שלא ע\"י אתדל\"ת כלל [... והגם שמבואר למעלה שע\"י אכילת מצה גרם שיהי' קי\"ס, זהו אינו אתדל\"ת כלל כי אתדל\"ת נק' התעוררות פנימי' באהוי\"ר או תשובה מעומקא דליבא אבל אכילת מצה הוא רק עובדא גשמי' שעי\"ז נמשך בהם האמונה בהעלם וזה אינו נק' אתדל\"ת כלל כו'. ..], אך בעשי\"ת בר\"ה ויו\"כ נעשה יחוד קב\"ה ושכינתי' ע\"י תשובה מעומקא דליבא וזהו זיווג שני לפי מעשיו שנעשה אז מצד התשובה שחזרו בתשובה אחר חטא העגל ועי\"ז נתקבלו ברצון וניתן להם לוחות האחרונות ביוה\"כ<sup data-n=\"999\">66</sup> שזהו יחד קוב\"ה ושכינתי' ע\"י התורה כו', וכן עתה בכל שנה הימים האלה נזכרים ונעשי' ולכן בחג הפסח נמשך שפע פנימי' בכללות נש\"י מצד עצמו שלא ע\"י אתדל\"ת כלל ובר\"ה ויוה\"כ נמשך בהם שפע פנימי' הנ\"ל ע\"י תשובה מעומקא דליבא ולפ\"ע התשובה כן נמשך השפע כו' וד\"ל.\n<b>והנה</b> כתיב יחיינו מיומים ביום השלישי יקימנו כו' הנה יומים הם ב' ימים דר\"ה<sup data-n=\"1000\">67</sup> ביום א' עליות פנימי' העולמות [... וע\"כ לומר שאז עליות פנימי' המל' מקור הפנימי' כו'. ..] וביום ב' עליות חיצוני' העולמות<sup data-n=\"1001\">68</sup> [... וע\"כ לומר שאז עליות חיצוני' המל' מקור חיצוני' העולמו' כו'. ..], והנה הגם שי\"מ ב' ימים הם בינה ומל'<sup data-n=\"1002\">69</sup> או לאה ורחל<sup data-n=\"1003\">70</sup> העיקר שהם ב' בחי' שבמל' גופא להיותה ממוצע בין אצילות לבי\"ע לזאת היא כלולה מב' הבחי' ובחי' הפנימי' שבה היא בחי' אצי' עצמו והחיצוני' שבה הוא",[["996","63","<b>במדרש ופרצת ימה וקדמה</b>: ראה אוה\"ת כאן ע' תקעה שמציין לפ' בשלח — שמו\"ר פכ\"א, ח."],["997","64","<b>הים הנק' ימה</b>: ראה גם יפה תואר ב\"ר פס\"ט, ה ד\"ה את."],["998","65","<b>זיווג שני לפי מעשיו</b>: ראה סוטה ב, א. ראה גם בהבא לקמן אוה\"ת בראשית כרך ג ע' 1086."],["999","66","<b>לוחות האחרונות ביוה\"כ</b>: ראה תענית ל, ב. רש\"י תשא לד, כט. הוספות לשו\"ע אדה\"ז חאו\"ח רסתקפ\"א (ע' תרפב)."],["1000","67","<b>יחיינו מיומים. . ב' ימים דר\"ה</b>: הושע ו, ב. ראה לקו\"ת ר\"ה סג, סע\"ב. אוה\"ת בשלח כאן ע' תקעו. ראה ע' תרסא. ר\"ה ע' א'תיג. סה\"מ תרל\"ח ס\"ע ל."],["1001","68","<b>ביום א'. . וביום ב'. . העולמות</b>: ראה פע\"ח ש' ר\"ה ספ\"ד [צויין בלקו\"ת שבהערה שלפנ\"ז, וכנראה שכצ\"ל באוה\"ת כאן שמציין: לע\"ח]. באוה\"ת כאן מוסיף: וע' ג\"כ בטו\"ב [ בטור ברקת] סי' ת\"ת [כנצ\"ל: ת\"ר] ע\"ש באוה\"ת."],["1002","69","<b>ב' ימים הם בינה ומל'</b>: דברי המגי' שהביא המק\"מ. ראה הערה הבאה."],["1003","70","<b>ב' ימים הם. . לאה ורחל</b>: מק\"מ לזהר פינחס רלא, ב. צויין אליו באוה\"ת כאן ע' תקעו. וע\"ש."]]],[4801940456,"שרש ומקור לבי\"ע ובחי' הפנימי' שבה נק' ים והחיצוני' שבה נק' ארץ ולכן שני הימים המה כיומא אריכתא<sup data-n=\"1004\">71</sup> כי הכל בחי' מל' דאצי' רק שהיא גופא כלולה מב' בחי' כו' [... ואפ\"ל שזהו כיומא אריכתא כדוגמת אריך<sup data-n=\"1005\">72</sup> שהוא בחי' הכתר הוא מחבר ומייחד המאציל עם הנאצלי' כן בחי' המל' אשר שרשה בכתר כמ\"ש מראש מקדם נסוכה<sup data-n=\"1006\">73</sup> סומ\"ע כו' היא מייחדת ומחברת אור האצי' בבי\"ע כו' וד\"ל. ..]. והנה בתפילות דר\"ה אנו אומרים ג\"פ ובכן<sup data-n=\"1007\">74</sup> ומבואר בזהר פ' בשלח ד' נ\"ב עמוד א' א\"ר ייסא אשכחנא בתקיעותא דרב כו' תלת ובכן כו' לקבל ג\"פ קדוש [... והיינו שאנו ממשיכים ג\"פ קדוש שהם כנגד חג\"ת כו' או כנגד חב\"ד חג\"ת נה\"י כו' בבחי' המל' דאצי' ולכן אנו אומרים אח\"כ ובכן צדיקים יראו וישמחו כו' שהוא בחי' צדיק וצדק יסוד ומל'<sup data-n=\"1008\">75</sup> כו' וד\"ל. ..] [וכן ממכי\"ק<sup data-n=\"1009\">76</sup> בעובדא אנו ממשיכי' ט\"ס דז\"א אל בחי' המל' ע\"י ט' תקיעות<sup data-n=\"1010\">77</sup> שעל ידם ממשיכים מט' מלכיות שבט\"ס דז\"א אל המל' כו' וכמאמ' כל הנחלי' הולכי' אל הים כו'], והנה המשכה זאת אנו ממשיכים ג\"כ ביום ב' דר\"ה בעובדא ובמילולא ע\"י תלת ובכן שבתפילה וע\"י ט' תקיעות רק שביום ב' נבנית בנין המל' בחיצוני' כו' כנ\"ל בענין ב' ימים דר\"ה שהם כנגד ב' בחי' דמל' ים וארץ והוא ענין יחיינו מיומים כו' [ויום א' דר\"ה נק' חודש סתם והוא מקור לי\"ב ראשי חדשי השנה מחמת שהוא בחי' ים וכמאמ' י\"ב בקר והים עומד עליהם מלמעלה<sup data-n=\"1011\">78</sup> כו' וד\"ל].\n<b>והנה</b> כמו שבזש\"פ מאיר בחי' עתיקא שהוא למעלה מבחי' ים וארץ עלמא דאתכסי' ועלמא דאתגליא וע\"י גילוי הנ\"ל מתגלה עצמו' ההעלם דעלמא דאתכסיא בעלמא דאתגליא כנ\"ל באריכות [ובחי' גילוי הנ\"ל נמשך ע\"י ו' ימים תאכל מצות כנ\"ל] כן ביוהכ\"פ כאשר נבנית מתחילה בחי' מל' דאצי' בפרצוף שלם בב' ימים דר\"ה בפנימי' וחיצוני' שזהו ענין יחיינו מיומים כנ\"ל עי\"ז אח\"כ ביום השלישי יקימנו ונחי' לפניו שעולה המל' בבחי' עתיקא ונגלה בחי' עתיקא במל' [... כמבואר בר\"מ סיהרא סליקת כו'. ..], רק שביוהכ\"פ נעשה עלי' זאת ע\"י התשובה מעומקא דליבא שבעשי\"ת [כנ\"ל בענין זיווג שני לפי מעשיו כו'] שקדמו ליוה\"כ ולכן בזש\"פ נאמר עד יעבור עמך הוי'<sup data-n=\"1012\">79</sup> שעולים למעלה משם הוי' כו' וכן ביוה\"כ נאמר",[["1004","71","<b>שני הימים המה כיומא אריכתא</b>: ראה ביצה ד, ב וב (רש\"י) מפרשים שם. רמב\"ם הל' יו\"ט ספ\"א. הל' אבל ספ\"י. שו\"ע אדה\"ז הל' ר\"ה סת\"ר, ס\"ג ואילך."],["1005","72","<b>כיומא אריכתא כדוגמת אריך</b>: ראה גם אוה\"ת בראשית כרך ז ע' 2322."],["1006","73","<b>מראש מקדם נסוכה</b>: תפלת לכה דודי."],["1007","74","<b>ג\"פ ובכן</b>: ראה מק\"מ כאן. פע\"ח שבהערה הבאה. ראה גם ביאוה\"ז להצ\"צ כרך א ס\"ע שצט וס\"ע תיא ואילך. נדפס גם באוה\"ת ר\"ה ס\"ע א'תמד ואילך."],["1008","75","<b>ובכן צדיקים. . צדיק וצדק יסוד ומל'</b>: ראה פע\"ח שער תפלות ר\"ה שכ\"ה, פ\"ז."],["1009","76","<b>ממכי\"ק</b>: ממאמר כתב יד קדשו (של הצ\"צ). התוכן — ראה אוה\"ת בשלח כאן ע' תקעו. לקמן מאמר ד\"ה והתהלכתי תרכ\"ב הערה 50."],["1010","77","<b>ט' תקיעות</b>: ראה ר\"ה לג, ב (במשנה). שו\"ע אדה\"ז הל' ר\"ה סתק\"צ, ס\"א."],["1011","78","<b>י\"ב בקר. . מלמעלה</b>: ע\"פ מל\"א ז, כה. מד. דהי\"ב ד, טו."],["1012","79","<b>עד יעבור עמך הוי'</b>: בשלח טו, טז. ראה גם תו\"א לך יג, ד. בשלח סה, א. לקו\"ת בשלח ב, ג. חוקת סד, ג. בלק עד, א. האזינו עא, ד. ש\"א כ, ב ובהערה 31."]]],[4801940493,"לפני הוי' תטהרו<sup data-n=\"1013\">80</sup> שעולים בעתיקא למעלה משם הוי' כו', ולכן אנו אומרים ביוהכ\"פ י\"ג מדות הרחמים שנאמר בהם ויקרא הוי' הוי'<sup data-n=\"1014\">81</sup> כו' חיבור ב' הוויו' שלפני הפסיק טעמא ואחר הפסיק טעמא כו', והם שרש תרין עלמין עלמא דאתכסיא ועלמא דאתגליא כו', ולכן כאשר מתחברים ב' הויו' הנ\"ל בשרשם נעשה ג\"כ למטה היחוד דעלמא דאתכסיא ועלמא דאתגליא והיינו שעצמו' ההעלם בא לידי גילוי כנ\"ל וד\"ל.\n<b>והנה</b> באמת יוה\"כ הוא מעין שביעי של פסח דלע\"ל [... והוא ע\"ד המבואר בסידור<sup data-n=\"1015\">82</sup> שבזש\"פ עצמו יש הפרש כי בפ' פנחס כתוב בו כל מלאכת עבודה לא תעשו<sup data-n=\"1016\">83</sup> כו' אך בפ' ראה כתוב בו לא תעשו מלאכה<sup data-n=\"1017\">84</sup> שגם מלאכת אוכל נפש לא הותר מטעם דזש\"פ דלע\"ל יהי' הגבה מאוד נעלה משביעי של פסח דעכשיו כו' וכמבואר בסידור<sup data-n=\"1018\">85</sup> דזש\"פ דלע\"ל הוא גבוה גם משבת דעכשיו דבשבת דעכשיו הגם שמלאכת אוכל נפש אסור<sup data-n=\"1019\">86</sup> מ\"מ מצוה לאכול ולשתות ולהתענג<sup data-n=\"1020\">87</sup> במזון גשמי ובו מלובש עונג הרוחני דע\"י כו' אך בזש\"פ דלע\"ל לא יתענגו במזון גשמי רק בעונג הרוחני בלתי מלובש במזון גשמי כו', והנה יוה\"כ הוא בדוגמא משביעי של פסח דלע\"ל לכן אין בו אכילה ושתי'<sup data-n=\"1021\">88</sup> כי העונג שבו הוא עונג נעלם להתענג מבחי' עצמו' ממש ועונג כזה לא יוכל להתלבש רק בבחי' עינוי הנה\"ט מתענוגי' גשמיי' דה' דברים<sup data-n=\"1022\">89</sup> ועינוי הנה\"א בבחי' מרירות מן ההיפוך כו' אך בזש\"פ דלע\"ל יתענגו מבחי' העצמו' בבחי' עונג ממש מצד שיזדככו הגופי' עד שיוכלו לקבל עונג זה בבחי' גילוי ולא יצטרך להתלבש בבחי' ההפוך שהוא העינוי כו' לכן יוה\"כ הוא מעין בלבד מבחי' זש\"פ דלע\"ל כו' וד\"ל. ..] ולכן אין בו אכילה ושתי' כו' וד\"ל.\n<b>והנה</b> בזש\"פ דלעתיד כתיב והניף ידו על הנהר<sup data-n=\"1023\">90</sup> כו' וידוע דנהר הוא בחי' בינה<sup data-n=\"1024\">91</sup> ולע\"ל יהי' ההעברה בנהר הנ\"ל וממילא יתעלו למעלה מבחי' הנהר דבינה והיינו במל' דא\"ס כמו שהיא נכללת בבחי' העצמו' שזהו ענין הי' הוא ושמו בלבד<sup data-n=\"1025\">92</sup> כו', כן ביוה\"כ בתחילה מתעלי' המל' לבחי' הבינה דאצי' ואח\"כ מתעלי' למעלה מן הבינה בבחי' שמו בלבד כנ\"ל וזהו העלי' השני' שבנעילה כמבואר בסידור<sup data-n=\"1026\">93</sup> כו'. והנה מבואר למעלה שעיקר קי\"ס הוא ע\"י פסוק השלישי דויט משה כו' לכן בו מבואר ענין קי\"ס והיינו מטעם דפסוק השלישי הוא כנגד יעקב מדת הת\"ת שעולה עד פנימי' הכתר הנק' עתיקא כו' וכח הבקיעה של הים להפכו ליבשה והיינו להביא עצמו' ההעלם לגילוי בעתיקא תליא כנ\"ל כן הוא בעשי\"ת הנה ב' ימים דר\"ה הם כנגד אברהם ויצחק חו\"ג כנגד ב' פסוקי' דויסע ויבא וכנגדם הם ב' ובכן כו' [... ובכן יתקדש הוא כנגד אברהם הממשיך ביטול מצד הקירוב כל שמתקרב יותר הוא יותר כלא חשיב, כמבואר באגה\"ק במאמר קטנתי<sup data-n=\"1027\">94</sup>, ובחי' ביטול זה נק' קדושה כו', ובכן תן פחדך כו' הוא כנגד יצחק שממשיך פחד ויראה להיות וינועו ויעמדו מרחוק<sup data-n=\"1028\">95</sup> כן נלע\"ד בדרך אפשר. ..], ויוה\"כ הוא כנגד פסוק השלישי דויט שהוא בחי' יעקב שהוא מדת הת\"ת שעולה עד פנימי' הכתר כנ\"ל, ולכן נגלה בו בחי' עתיקא כידוע דביוה\"כ נגלה בחי' אנכי השני שהוא בחי' עתיק כמבואר בסידור<sup data-n=\"1029\">96</sup> [ולכן נמשך בו סליחות עוונות כמאמר אנכי אנכי הוא מוחה פשעיך<sup data-n=\"1030\">97</sup> כו'], ולכן ממילא נמשך עצמו' ההעלם לבוא לידי גילוי והוא ענין ויבקעו המים כמו בקי\"ס וזהו ובכן השלישי דובכן תן כבוד כו' וד\"ל.",[["1013","80","<b>לפני הוי' תטהרו</b>: אחרי טז, ל. ראה גם לקו\"ת אחרי כו, סע\"ג. כז, ד. נצבים נא, סע\"א, ואילך. ר\"ה נו, א."],["1014","81","<b>ויקרא הוי' הוי'</b>: תשא לד, ו."],["1015","82","<b>המבואר בסידור</b>: שער חה\"מ רצב, ג ואילך."],["1016","83","<b>כל מלאכת עבודה לא תעשו</b>: פינחס כח, כה."],["1017","84","<b>לא תעשו מלאכה</b>: פ' ראה טז, ח [ושם: לא תעשה. וכ\"ה בסידור]."],["1018","85","<b>וכמבואר בסידור</b>: שם רצב, סע\"ג ואילך."],["1019","86","<b>דבשבת. . שמלאכת אוכל נפש אסור</b>: יתרו כ, י (רש\"י תשא לא, טו). ראה שבת עג, א."],["1020","87","<b>מצוה לאכול ולשתות ולהתענג</b>: ראה שו\"ע אדה\"ז ריש הל' שבת."],["1021","88","<b>יוה\"כ. . אין בו אכילה ושתי'</b>: יומא רפ\"ח."],["1022","89","<b>עינוי. . דה' דברים</b>: יומא שם. ראה גם מאמרי אדה\"א דברים ח\"ד ע' א'קפד. וש\"נ."],["1023","90","<b>והניף ידו על הנהר</b>: ישעי' יא, טו."],["1024","91","<b>דנהר. . בינה</b>: זהר (אדרא דמשכנא) משפטים קכג, ב."],["1025","92","<b>הי' הוא ושמו בלבד</b>: ראה פדר\"א פ\"ג. תו\"ח וארא ח\"א נג, ב הערה 6."],["1026","93","<b>כמבואר בסידור</b>: שער יוהכ\"פ רנ, א ואילך."],["1027","94","<b>באגה\"ק במאמר קטנתי</b>: אגה\"ק ס\"ב."],["1028","95","<b>וינועו ויעמדו מרחוק</b>: יתרו כ, טו."],["1029","96","<b>כמבואר בסידור</b>: ראה שם שער יוהכ\"פ רנא, א."],["1030","97","<b>אנכי אנכי הוא מוחה פשעיך</b>: ישעי' מג, כה."]]],[4801940525,"אך הגם שעיקר גילוי עתיקא הוא ביוה\"כ מ\"מ מתעורר גילוי הנ\"ל בימי ר\"ה רק ההתעוררות הוא בהעלם בלבד וביוהכ\"פ בא לידי גילוי ממש להיות סולח ומוחל ומכפר כו' וזהו כי עמך הסליחה<sup data-n=\"1031\">98</sup> שהיא מופקדת אצלך עדיין מר\"ה כו' [... ובזה יובן מה שאנו אומרים כל השלשה ובכן בר\"ה וגם ביוה\"כ כו' כי גם ובכן השלישי מתעורר בהעלם בר\"ה כו' וכן ביוה\"כ כאשר בא לידי גילוי ישנו לכח ההעלם בבחי' הגילוי וכל יום כלול מכל הג' ימים כו' וד\"ל. ..]. [ובמכי\"ק<sup data-n=\"1032\">*99</sup> כתוב שבר\"ה מאיר שופר סתם ובחי' שופר הוא בחי' בינה<sup data-n=\"1033\">99</sup> והוא בחי' ונהר יוצא מעדן<sup data-n=\"1034\">100</sup> להשקות את הגן והנה גן אפ\"ל שהוא ג\"ן סדרים דאורייתא<sup data-n=\"1035\">101</sup> בחי' תו' ומצות שהם בחי' עה\"ח שבתוך הגן<sup data-n=\"1036\">102</sup> והנה הפגמי' שנעשה בבחי' עה\"ח ע\"י העדר העשי' דמ\"ע ומל\"ת הנהר דבינה שנק' בשם יובל<sup data-n=\"1037\">103</sup> הוא משקה וממלא אותם כו', אך לע\"ל יאיר מבחי' שופר גדול שלמעלה משופר סתם [... וזהו בינה דע\"י<sup data-n=\"1038\">104</sup> ועד רום המעלות הוא בבחי' שעשועי המלך בעצמותו המאיר בבחי' בינה שבעצמו' ונק' עונג הנעלם הבא במורגש בכתבי אדמו\"ר נבג\"מ<sup data-n=\"1039\">105</sup>, ואז יתקן הפגמי' שלא יוכל להתקן ע\"י הנהר",[["1031","98","<b>כי עמך הסליחה</b>: תהלים קל, ד."],["1032","*99","<b>ובמכי\"ק</b>: ובמאמר כתב יד קדשו (של הצ\"צ). התוכן — ראה אוה\"ת בשלח כאן ע' תקעז. לקמן מאמר ד\"ה והתהלכתי תרכ\"ב הערה 50."],["1033","99","<b>שופר הוא בחי' בינה</b>: ראה זהר יתרו פא, ב ובמק\"מ ואוה\"ח שם."],["1034","100","<b>ונהר יוצא מעדן</b>: בראשית ב, י."],["1035","101","<b>ג\"ן סדרים דאורייתא</b>: ראה זהר מדהנ\"ע וירא קד, ב. מאמרי אדה\"א דברים ח\"ד ע' א'רג. וש\"נ. ראה גם לקמן מאמר ד\"ה בסוכות תשבו תרכ\"ב על יד הערה 19. ד\"ה רפאיני הא' על יד הערה 40."],["1036","102","<b>עה\"ח שבתוך הגן</b>: בראשית ב, ט."],["1037","103","<b>הנהר. . יובל</b>: ראה זהר אחרי נח, א."],["1038","104","<b>שופר גדול. . בינה דע\"י</b>: ראה אוה\"ת ר\"ה ע' א'תט."],["1039","105","<b>עונג הנעלם. . אדמו\"ר נבג\"מ</b>: כ\"ק אדמו\"ר האמצעי — ראה תו\"ח נח מז, ג. וישלח קפד, ג. מקץ ריז, סע\"א ואילך. ויחי רמא, ב."]]],[4801940552,"דבינה וכידוע בענין מאמר הזהר ע\"פ אם עוונות<sup data-n=\"1040\">106</sup> תשמר י\"ה מי יעמוד כו'. ..], ומעין ממנו מאיר עכשיו ביוהכ\"פ, והנה כמו דלע\"ל ע\"י גילוי שופר גדול שלמעלה מן הנהר דבינה יהי' והכהו לשבעה נחלים<sup data-n=\"1041\">107</sup> [... והיינו שיהי' עליות המדות דז\"א בבחי' המדות דע\"י ע\"י שיעברו הנהר שהוא בחי' בינה ואפשר יעברו גם בינה דא\"א ולכן יתעלו במדות דע\"י עצמם, ואפ\"ל שיעברו גם הנהר דבינה דע\"י ויאיר בכל ז' המדות מכתר וחכ' דע\"י שזהו ענין אראנו נפלאות כמ\"ש בסידור<sup data-n=\"1042\">108</sup> והנה בחי' זאת יאיר גם בנש\"י ששרשם מז' מדות דז\"א<sup data-n=\"1043\">109</sup> כו' נמצא שע\"י הכאת הנהר לשבעה נחלי' יתגלו הבחי' הנ\"ל בנש\"י כו' וד\"ל. ..], כן עכשיו ביוהכ\"פ שמאיר מעין שופר גדול דלע\"ל נמשך והכהו לשבעה נחלים כו' והם ז' ימי הסוכות שמאיר בחי' ע\"י בז' מדות דז\"א או הם ז' מינים שבלולב<sup data-n=\"1044\">110</sup> כו' וד\"ל<sup data-n=\"1045\">111</sup> [... ובאמת שניהם אמת כידוע דע\"י הסובב מאירי' חסדי' דע\"י בבחי' מקיף כו' בכל ז' המדות וע\"י הלולב מאירים חסדים הנ\"ל בבחי' פנימי' וידוע דתחילת התעוררות חסדים הנ\"ל הוא ביוהכ\"פ בה' תפילות שהם כנגד ה\"ח דע\"י כמ\"ש בסידור<sup data-n=\"1046\">112</sup> כו' וד\"ל. ..].\nסליק<sup data-n=\"1047\">113</sup> סליק סליק",[["1040","106","<b>אם עוונות</b>: תהלים קל, ג [בדילוג]. ראה זהר בלק קפה, ב. וראה גם לקו\"ת שלח מ, א. סידור שחרית סד, ד. אוה\"ת קרח ע' תשא. משלי ע' תרמא. סה\"מ תרכ\"ו ע' קמה. ע' רנט."],["1041","107","<b>והכהו לשבעה נחלים</b>: ישעי' יא, טו."],["1042","108","<b>אראנו נפלאות כמ\"ש בסידור</b>: מיכה ז, טו. ראה שם שער חה\"מ רצג, א."],["1043","109","<b>בנש\"י ששרשם מז' מדות דז\"א</b>: ראה גם שער האמונה יח, א. כג, א. סח, ב. לקמן מאמר ד\"ה וספרתם תקצ\"ח ובהערה 45."],["1044","110","<b>ז' מינים שבלולב</b>: כ\"ה גם באוה\"ת כאן ע' תקעז."],["1045","111","<b>כו' וד\"ל</b>: כנראה שכאן הוא סיום החצאי ריבוע המתחיל לעיל [ובמכי\"ק."],["1046","112","<b>בה' תפילות. . ה\"ח דע\"י כמ\"ש בסידור</b>: שער יוה\"כ רנ, סע\"ד."],["1047","113","<b>סליק</b>: ראה מכתב י\"ג ניסן תש\"ח נדפס באג\"ק כ\"ק אדמו\"ר ח\"ב ס\"ע שכט ואילך."]]],[4801940089,"<b>שרש</b> ענין קי\"ס<sup data-n=\"1048\">1</sup> כתיב כי רוצה ה' בעמו<sup data-n=\"1049\">2</sup> יפאר ענווים בישועה, ויובן ע\"פ משל ממלך ב\"ו שעיקר הנהגתו במדת המלוכה הוא בבחי' אימה שעי\"ז מתבטלי' אליו ונכללי' כולם ברצון א' שהוא רצון המלך, זהו עיקר קיומם וחיותם כמאמר אלמלא מוראה<sup data-n=\"1050\">3</sup> כו', אך כשרוצה המלך בהתקשרות עמו אליו בבחי' פנימי' היינו מדת האהבה שיהי' אהבתם זא\"ז בבחי' פנימי' אז נגלה אליהם בכל חמודות אוצרותיו הנעלמים לצורך עצמו להשתעשע בהם בעת הצורך [שהם מלבד אותם הצריך להנהגת המדינה כו'], כענין בהראותו את עושר כבוד<sup data-n=\"1051\">4</sup> כו' [וענין הגילוי הוא",[["1048","1","<b>שרש ענין קי\"ס</b>: דרוש ר\"ה.\nראה גם לקמן ברשימת הכת\"י כאן."],["1049","2","<b>כי רוצה ה' בעמו</b>: תהלים קמט, ד."],["1050","3","<b>אלמלא מוראה</b>: ע\"פ אבות פ\"ג, מ\"ב."],["1051","4","<b>בהראותו את עושר כבוד</b>: אסתר א, ד."]]],[4801940154,"בב' אופני' או שנוסע בכל מדינתו בתפארת יקר ומתראה אליהם או שמקבץ אותם למקומו כו'], ואז הכל מסתכלים ביקר תפארתו ומתענגים בבחי' תענוג בלתי מורגש כלל כי אין תועלת מזה לנפשם רק ההסתכלות הוא בעצם הפאר וכן התענוג הוא מצד עצם דבר המפואר אע\"פ שאינו שייך אלי' כלל כי טבעי' זאת יש בנפש להתענג בהסתכלות מדבר מהודר אע\"פ שאין הדבר שייך אלי' כלל, והנה ע\"י שמסתכלים ברוממות המלך העצמי' אזי המה מתבטלים ממציאותם לגמרי מצד שהוגבהו במקום גבוה שלמעלה ממקורם ושרשם לגמרי כי שרשם הוא בבחי' חיצוני' מדת המלוכה שהוא התנשאות שלו על עם לא ברוממות עצמו' המלך שנבדל בערך מהם. והנה ביטול פנימי הזה הוא גורם אהבת העם אליו לאחר שנסתלק ונתעלם מהם (כי בעת גילוייו אליהם המה בבחי' ביטול גדול הגבה מאוד נעלה ממדת האהבה כו'). והנמשל יובן למשכיל למעלה שיש ב' מיני יחודים הא' בחי' יחוד יסוד ומל' שבזה נכללים כל היחודים עליונים דתפלה ותומ\"צ ושבת ויו\"ט, והב' בחי' יחוד תפארת ומל' כו' שאינו רק ממוצע בכל עלי' ממדריגה למדריגה כו'.\n<b>וביאור</b> הדברים הנה בחי' יחוד יסוד ומל' הוא בחי' התקשרות אא\"ס בנש\"י וכן התקשרות נש\"י באא\"ס בבחי' פנימי' והרגשה ממש כי יסוד הוא בחי' התקשרות<sup data-n=\"1052\">5</sup> המשפיע להשפיע למקבל בפו\"מ שהוא ענין ביטול והנחת עצמותו בשביל הירידה וההשפעה שהוא ענין בליטת יסוד דדכורא ושרשו בפנימי' הרצון דמשפיע שהוא רוצה וחפץ בעצם המקבל שזה גורם ענין ההשפעה בפו\"מ דייקא, וכ\"ה מלמטה למעלה התקשרות המקבל שהמה נש\"י במשפיע בכדי לקבל ההשפעה בפנימי' הכלים שלהם או בחיצוני' כמשי\"ת שזה בא ע\"י ביטול והנחת כל עצמותם שלא להיות רק רצון א' בהתקשרות לה' לבדו, והוא ענין יסוד דנוק' שהוא שקוע שבא מצד פנימי' הרצון שלהם שרוצים בעצמי' המשפיע ע\"כ המה חפצים לקבל השפעת אא\"ס בקרבם ותוך תוכם, ויש בזה ג' מדריגות הא' כשבא בחי' התקשרות זאת במקבל מצד ההתבוננות בשבחו של מקום איך דממך הכל<sup data-n=\"1053\">6</sup> ואין לך דבר המתהוה בעולם וגם חיות שלהם שיהי' חוץ ממנו והוא ענין פסד\"ז שהוא בחי' ביטול חיצוני ע\"י ההתבוננו' בהשתלשלו' שעי\"ז נגלה אא\"ס מלמעלה למטה ג\"כ בבחי' חיצוני' בלבד. והב'<sup data-n=\"1054\">7</sup> בחי' הביטול דק\"ש ושמ\"ע שזהו מצד הרגשה פנימי' ביותר בבחי' ביטול ההשתלשלו' למקורם ושרשם והיינו כשמתבונן בהעמקת הדעת איך דכלא קמי' כלא<sup data-n=\"1055\">8</sup> כו' שזהו בחי' למסור נפשו באח\"ד<sup data-n=\"1056\">9</sup> בחי' ביטול דח' דלית באל\"ף ואח\"כ בכריעה והשתחוואה דש\"ע<sup data-n=\"1057\">10</sup> הוא בחי' הביטול בעומק יותר, וכ\"ה המשכת",[["1052","5","<b>יסוד. . התקשרות</b>: ראה אגה\"ק סט\"ו. תו\"ח וישב רט, ב ובהערה 25."],["1053","6","<b>דממך הכל</b>: דהי\"א כט, יד."],["1054","7","<b>והב'</b>: תוקן ע\"פ ב. ובכת\"י זה: והנה."],["1055","8","<b>דכלא קמי' כלא</b>: ראה זהר בהקדמה יא, ב. ראשית חכמה שער היראה פ\"א (ז, רע\"א). מאמרי אדה\"א דברים ח\"ב ע' תרנג."],["1056","9","<b>למסור נפשו באח\"ד</b>: ראה זהר רע\"מ משפטים קיט, א. צו לג, א. מאמרי אדה\"א דברים ח\"ב ע' תו. וש\"נ. שמות ח\"א ע' רעח ואילך. הנחות תקע\"ז ע' שא."],["1057","10","<b>והשתחוואה דשמ\"ע</b>: ראה גם תניא פל\"ט ושם: ”בתפלת שמ\"ע שהיא באצילות. . שכל השתחוואה היא בבחי' אצילות [וכמ\"ש בפרע\"ח בקבל' שבת]\". ובמ\"מ הגהות והע\"ק שם ”בקבלת שבת (תוספת שבת פ\"ה )\" היינו בפרע\"ח הוצאת תקמ\"ב ששם ישנו שער ”תוספת שבת\", ולפנינו הוא בשער השבת שי\"ח, פ\"ה. שע\"ת כה, ב ובהערה 9."]]],[4801940217,"אא\"ס מלמעלה למטה בפנימי' ביותר כו' כמשי\"ת, והג' בחי' יחוד פנימי' דש\"ע באמרו ברוך אתה הוי' רופא חולי כו' או מברך השני' כו' והעיקר בלימוד התורה שזהו יחוד גמור מהות הנשמה במהו\"ע א\"ס כו', וכ\"ז הוא נכלל בבחי' יחוד יסוד ומל' שבא מצד פנימית הרצון כו' שעיקרו הוא בחי' גילוי אא\"ס בנש\"י המקבלי' בכלים שלהם בדרך אור בכלי וזהו ענין כי רוצה ה' בעמו כו'. אך ענין יפאר ענוים כו' היינו בחי' יחוד ת\"ת ומל'.\n<b>וביאור</b> הענין הוא ע\"ד ההתבוננות בכל רזין וסודות עמוקים שאינם שייכים להתפעלות אהבה כלל [כי התפעלות אהבה אינה רק כשמתבונן איך שהוא חייך או איך דכלא קמי' כו' שעי\"ז נעשה ביטול פנימי יותר כו' כנ\"ל], כמו העסק בפרצופים עליונים דעתיק ואריך וא\"ק עד רום המעלות שבס' הזוהר ומתענג בזה בתענוג גדול אך לא בבחי' תועלת לנפשו [כי אינו מסתעף מזה שום בחי' בכן] רק ענין התענוג בזה הוא כמו שמסתכל אדם בדבר מפואר שיש לזולתו שאין שום תועלת לנפשו מדבר המפואר ואעפ\"כ יכול להתענג תענוג גדול כ\"כ עד שתכלה נפשו בזה שהתענוג בזה אין בו הרגשת עצמו כלל והוא ענין גילוי התענוג שלא בדרך אוב\"כ כי אין בו כלי לזה כלל רק בבחי' ראי' והסתכלו' בלבד כו'. והנה עד\"ז הי' כל בחי' התענוג דתלמידי רשב\"י והתפעלות שלהם כשהיו שומעים איזה דבר ורז נפלא להיות כי היו מסתכלים בעצם העומק שהוא ענין כח א\"ס העצמי הנעלם בזה והוא ענין מאמר ר' חזקי' באד\"ר<sup data-n=\"1058\">*11</sup> חמי הוי<sup data-n=\"1059\">11</sup> כו'. והנה זהו ענין יחוד ת\"ת ומל' כי ההתפארות אינו שייך כלל רק לגבי המרוחק ביותר שאינו שייך אליו כלל [כי לא יתפאר אדם בפני בניו רק בפני איש זר דווקא], וכך הוא למעלה הוא בחי' גילוי אא\"ס ממקום גבוה ונעלה כו' והיינו איך שהוא מרומם לבדו בעצמותו שלמעלה ממקור נש\"י כמאמר לית מח' תפיסא<sup data-n=\"1060\">12</sup> והיינו אפי' מח' העצמי' שישראל עלה<sup data-n=\"1061\">13</sup> כו' וכענין ישראל קדישין<sup data-n=\"1062\">14</sup> כו' ובכולהו אין קדוש כהוי'<sup data-n=\"1063\">15</sup> וכמאמר קדושתי למעלה מקדושתכם<sup data-n=\"1064\">16</sup> וזהו גילוי אא\"ס בבחי' ת\"ת להשפיע במל' מקור נש\"י, ואז כשמסתכלת הנשמה בכל פרט מפרטי ההשתלשלות היא רואה עצם עומק אמיתת הא\"ס הנעלם בו וכמאמר מאמיתת המצאו<sup data-n=\"1065\">17</sup> נמצאו כל הנמצאים כמשי\"ת. וזהו ענין יפאר ענוים שהוא ענין גילוי ע\"ס הגנוזות בבחי' יחוד<sup data-n=\"1066\">18</sup> ממש שגילוים הוא בבחי' הת\"ת בלבד, ובנש\"י מתקבלת השפעה זאת בבחי' הסתכלות בלבד כי אינם שייכי' לזה כלל בדרך כלי לקבל השפעת האור כי הגילוי הוא ממקום נעלה ממקורם ושרשם כו' ואעפ\"כ מתענגי' בתענוג גדול אך לא במורגש",[["1058","*11","<b>באד\"ר</b>: ניתוסף ע\"פ ב."],["1059","11","<b>חמי הוי</b>: ראה זהר אד\"ר נשא קלב, ב."],["1060","12","<b>לית מח' תפיסא</b>: ת\"ז בהקדמה יז, א."],["1061","13","<b>שישראל עלה</b>: ראה ב\"ר פ\"א, ד. שע\"ת קטו, ב. תו\"ח שמות ח\"א לב, ב ובהערה 248."],["1062","14","<b>ישראל קדישין</b>: זהר תזריע מד, א."],["1063","15","<b>אין קדוש כהוי'</b>: שמו\"א ב, ב."],["1064","16","<b>קדושתי למעלה מקדושתכם</b>: ויק\"ר פכ\"ד, ט."],["1065","17","<b>מאמיתת המצאו</b>: ראה רמב\"ם ריש הל' יסוה\"ת."],["1066","18","<b>יחוד</b>: אולי כתוב: יחיד."]]],[4801940270,"כלל, והוא ענין שמכריזים מאן בעי לאסתכלא<sup data-n=\"1067\">19</sup> ביקרא דמלכא כי יקר הוא ענין עילוי והפלאת כח הא\"ס ולכן סט\"א אסתלק<sup data-n=\"1068\">20</sup> כו' כי אין שם אפי' שרש דשרש להשפעת ויניקת החיצוני' כי מאחר שאין בזה הרגש כלל לכן לא יחפוץ כסיל בתבונ\"ה<sup data-n=\"1069\">21</sup> כו' וד\"ל.\n<b>וביאור</b> כל הנ\"ל הנה ידוע שיש ה' בחי' מיש האמיתי לאין, ומאין ליש נפרד, ובחי' הה' הוא בחי' אין האמיתי שלמעלה מיש האמיתי. ויובן ע\"ד דוגמא כח התנועה שהוא מקור לכל גילוי התנועה לאין שיעור אע\"פ שאינו ממהות תנועה כלל כי רק מזיו ואור שלו מתהוה בחי' תנועה בפרט ואעפ\"כ להיות שהוא מוגבל רק להניע כו' לכן נק' יש האמיתי וגם להיות שהוא אמיתית היש דתנועה ובלעדו אין קיום כלל לבחי' תנועה בגילוי, והנה כשמתעורר כח התנועה להניע בפרט והתעוררות זאת היא כלולה עדיין בעצם כח המניע זהו מיש לאין והוא ענין השפעה בהעלם ואח\"כ גילוי התנועה להתלבש בדבר נבדל זהו מאין ליש שלזה מוכרח הוא שתתצמצם השפעה נעלמת הנ\"ל בדבר זר לגמרי שהוא ענין גשם העור והיד שהוא כדמות פרסא להעלים לגמרי, ועי\"ז נבדל התנועה לחוץ מעצמותו כדוגמת אור מחודש כמשי\"ת. והנמשל יובן למשכיל למעלה שע\"ס דאצי' המה מקור האמיתי להיות מהם בי\"ע וכמאמר אנת הוא דאפיקת כו' לאחזאה<sup data-n=\"1070\">22</sup> כו' והוא ענין יש האמיתי כי בחי' חכמה דאצי' למעלה אינו מהות חכ' רק מקור האמיתי להתהוות ממנו חכמה בבי\"ע וכן חסד כו' וההתעוררות שלהם לבי\"ע כענין כד סליק ברעותי'<sup data-n=\"1071\">23</sup> למברי עלמא הוא ענין שרש ההשפעה בהעלם לבי\"ע שכבר נמדדה להיות באופן זה לא באופן אחר רק ההשפעה בהעלם עדיין ומתאחדת עדיין בעצמי' מקורה [שהמקור אינו מוגבל ויכול להיות ממנו כמה אופנים שונים] וזהו בחי' המל' כמ\"ש בהעלם בבחי' אצי' הנק' כבוד נברא<sup data-n=\"1072\">24</sup>, וזהו מיש לאין והוא בחי' יחו\"ע שילוב אדני בהוי', אך בחי' יחו\"ת הוא בחי' גילוי המל' בבי\"ע והיינו כשכבר נתהוה בחי' יש דבי\"ע, והשפעה אלקי' מלובש בהם בהעלם שהוא ענין כח הפועל בנפעל<sup data-n=\"1073\">26</sup> שילוב הוי' באדני<sup data-n=\"1074\">25</sup>. והנה כדי שיתהוה מבחי' ההשפעה בהעלם [שהוא בחי' מיש לאין] גילוי ההשפעה בבחי' יש גמור שהוא כדוגמת אור חדש לגמרי צ\"ל ע\"י בחי' פרסא מפסיק שהוא דבר זר לגמרי והוא ענין צירופי אותיות הדיבור דע\"מ המעלימי' לגמרי בחי' ההשפעה כמ\"ש בהעלם להביאה לידי גילוי חדש שהוא ענין כח הפועל מאין ליש הנ\"ל, ושרש אותיות הדיבור הוא מבחי' החכמה<sup data-n=\"1075\">27</sup> שהוא בחי' אין האמיתי להיות כי",[["1067","19","<b>מאן בעי לאסתכלא</b>: ראה זהר תרומה קלד, ב."],["1068","20","<b>סט\"א אסתלק</b>: ראה זהר שם."],["1069","21","<b>לא יחפוץ כסיל בתבונ\"ה</b>: משלי יח, ב."],["1070","22","<b>אנת הוא דאפיקת כו' לאחזאה</b>: ת\"ז בהקדמה יז, א-ב."],["1071","23","<b>כד סליק ברעותי'</b>: ראה זהר לך פו, סע\"ב."],["1072","24","<b>המל'. . כבוד נברא</b>: ראה מאמרי אדה\"א דרושי חתונה ח\"א ע' ב ואילך."],["1073","26","<b>כח הפועל בנפעל</b>: בלקו\"ת שלח מז, א: בספרים. ראה הנסמן במ\"מ לשם. ספר הישר (לר\"ת ) סוף ש\"ג."],["1074","25","<b>שילוב אדני בהוי'. . הוי' באדני</b>: ראה מבו\"ש ש\"ג ח\"ב ספ\"ה. לקו\"ת ש\"ש סה, ד ובהנסמן במ\"מ לשם סד, ב. תו\"ח וארא ח\"א נ, א הערה 32. וראה גם לקמן מאמר ד\"ה לה\"ע ההפרש בין שליו\"ט תר\"ב על יד הערות 54-7."],["1075","27","<b>ושרש אותיות הדיבור. . החכמה</b>: ראה אגה\"ק ס\"ה. מאמרי אדה\"א דברים ח\"ב ע' שפ הערה ד\"ה מצירופי. קונטרסים ס\"ע תקמז ואילך."]]],[4801940320,"החכמה לעוצם ביטולה הוא בחי' כלי לבחי' גילוי אא\"ס<sup data-n=\"1076\">28</sup> הפשוט בתכלית שאינו מקור עדיין לבחי' התהוות נבראים והוא נבדל בערך מבחי' ע\"ס דאצי' שהמה מקורי' להתהוות נבראים [ולכן נק' בשם יש אמיתי] כו'.\n<b>והנה</b> כל עסקינו<sup data-n=\"1077\">29</sup> בתומ\"צ ותפילה הוא רק להוסיף אור ממקורא דכולא למטה בתחתונים הנבראים מאין ליש והוא ענין יחודים עליונים כו', ויש בזה ג' אופנים הא' בהתבוננות בשבחו של מקום והיינו בכללות כל הנבראים איך שהמה מתהווים וחיים וקיימים מבורא הכל המחי' ומהווה ומקיים אותם בכל עת ובכל רגע כמאמר המחדש<sup data-n=\"1078\">30</sup> כו', וזהו ענין פסוד\"ז כמו הללו את הוי' מן השמי' שאין השמים מהות בפ\"ע כלל רק כל חיותם וקיומם הוא מבחי' שם הוי' השוכן בתוכם ובזה נמשך חיות חדש בנפשו להרגיש ביטול הטפל לגבי העיקר כו', אך כל תוס' חיות הנ\"ל הוא רק מבחי' כח הפועל הנ\"ל שהוא בחי' שילוב הוי' באדני שנמשך בתוס' אור כו', והב' הוא ענין ביטול פנימי דק\"ש וש\"ע והיינו מצד בחי' כח מה שבנפש שרואה בעצם האין המחי' וראי' זו נמשכת בכל כוחות הנפש עד שמתבטל ממציאותו מכל וכל כדמיון הבא לפני המלך כו' מצד שמרגיש ביטול ההשתלשלו' למקורם לגמרי שהמה כלא ממש והוא ענין ביטול דחו\"ד באלף דאחד וכן בכריעות כו' [וכ\"ז הוא בא לפ\"ע היגיעה בהתבוננות באיכות התהוות היש מאין לפ\"ע זה הוא בחי' הראי' בבחי' אין המהוה כו', יעוין בשער היחוד פ' דלית כו']. והנה ביטול פנימי זה הוא מצד גילוי בחי' אין הכלול ביש אמיתי כנ\"ל. והג' הוא בחי' היחוד דש\"ע באמרו ברוך אתה הוי' רופא חולי' כו' כנ\"ל, שהוא ענין המשכת מהו\"ע אלקות בנפש ובעולם והעיקר בתורה בדברו ד\"ת שהדיבור שלו הוא כלי לדבר ה' המדבר בו כענין אני המשנה המדברת<sup data-n=\"1079\">31</sup> כו' [וזהו כל הקורא ושונה הקב\"ה קורא ושונה<sup data-n=\"1080\">32</sup> כו'], שהוא ענין המשכת מהו\"ע אא\"ס בנפש בבחי' מהות [כמו נשמות הגבוהים רשב\"י כו'] וזה הכח ניתן במ\"ת אנכי הוי' אלקיך<sup data-n=\"1081\">33</sup> בפרט בכל נפש מישראל וזה בא מצד שנגלה בנפש שרשה כמו שעלתה במח' דס\"ר נש\"י מתקשראן באורייתא<sup data-n=\"1082\">34</sup> אותיות החקוקי' כו', והוא בחי' גילוי מיש ליש שלא ע\"י אין הממוצע כו' וד\"ל. וזהו כי רוצה ה' בעמו וכן הי' במ\"ת שהי' בבחי' דביקות והתקשרות כמאמר על כל דיבור פרחה נשמתן<sup data-n=\"1083\">35</sup> והחזירן בטל תורה<sup data-n=\"1084\">36</sup> שהוא ענין",[["1076","28","<b>החכמה. . כלי לבחי' גילוי אא\"ס</b>: ראה תניא פי\"ח (ובמ\"מ הגהות והע\"ק שם). פל\"ה בהג\"ה (ובמ\"מ הגהות והע\"ק שם). לקו\"ת במדבר יד, ב [ושם מציין: ”בע\"ח שער מ\"ז פ\"ג\" ולפנינו הוא פ\"ב ”ושער ב' במה\"ב פ\"א פ\"ג\" ולפנינו הוא בשער סדר אצי' ש\"ג]. תו\"ח שמות ח\"א ז, ד הערה 333."],["1077","29","<b>עסקינו</b>: תוקן ע\"פ ב. ובבוך זה: עסקים."],["1078","30","<b>כמאמר המחדש</b>: ברכת יוצר."],["1079","31","<b>אני המשנה המדברת</b>: ראה מגיד משרים פ' ויחי. בא. תשא. שע\"ת פ, ג ובהערה 26. תו\"ח תצוה ח\"ב שסב, ד. וש\"נ."],["1080","32","<b>כל הקורא. . ושונה</b>: ראה תדא\"ר רפי\"ח. מאמרי אדה\"א דברים ח\"ב ע' שפז. וש\"נ. תו\"ח וארא ח\"א נח, ג. וש\"נ."],["1081","33","<b>אנכי הוי' אלקיך</b>: יתרו כ, ב."],["1082","34","<b>נש\"י מתקשראן באורייתא</b>: ראה זהר אחרי עג, א."],["1083","35","<b>על כל דיבור פרחה נשמתן</b>: ראה שבת פח, ב. מאמרי אדה\"א ויקרא ח\"א ע' ג. וש\"נ. נ\"ך ע' שפא. וש\"נ. תו\"ח בראשית יז, ב."],["1084","36","<b>והחזירן בטל תורה</b>: שבת פח, ב ע\"פ תניא ספל\"ו."]]],[4801940369,"חיות רו\"ש מצד מהו\"ע, ולכן הי' לכ\"א מחיצה בפ\"ע<sup data-n=\"1085\">37</sup> כי גם בשרשם כמו שעלו במח' יש חילוקי מדריגות בעומק אחר עומק. אך שבקי\"ס הי' הכנה לזה<sup data-n=\"1086\">38</sup> כי ים דומה לרקיע<sup data-n=\"1087\">39</sup> שהוא ענין פרסא המבדיל בין ברואים שבים לברואים שביבשה והוא ענין אותיות הדיבור דע\"מ המבדילים בין בחי' ההעלם של כל הנבראים כמו שנכללים בבחי' האצילות שהוא בחי' אין הכלול ביש אמיתי ובין בחי' הגילוי שלהם בבי\"ע, ושרש פרסא הנ\"ל הוא מבחי' חכ' דאצילות שבה שורה אא\"ס הפשוט בתכלית הפשיטות שהוא מרומם ומובדל מבחי' ע\"ס דאצילות שהמה מקורי' לנבראי' כנ\"ל.\n<b>והנה</b> ע\"י בקיעת הפרסא מלבד שהי' בזה ענין גילוי ההעלם שלמעלה מהפרסא שעי\"ז נמשך גילוי מ\"ת, עוד הי' בזה ענין נוסף שכח הנעלם בפרסא עצמה נתגלה שזהו בחי' אין האמיתי דלמדת\"ב אפי' מחשבה העצמי' כנ\"ל, וזהו ענין הראי' שלהם שהיו צופים ומביטים בכל פרט מהשתלשלות בכח הנעלם שבו שהוא אמיתת כח הא\"ס בעצמו כמאמר מאמיתת המצאו כנ\"ל, ולכן לא הי' שם חילוקי מדריגות כלל להיות כי הראי' הי' במקום גבוה שלמעלה משרשם לגמרי ששם כולם שווים. וזהו ענין ראתה שפחה על הים<sup data-n=\"1088\">40</sup> שהוא ענין הראי' הסתכלות בלבד ביקרא דמלכא כנ\"ל וד\"ל. וזהו יפאר ענווים כו' שהוא ענין גילוי ע\"ס הקבועי' בעצמו' בבחי' הת\"ת שהוא בחי' גילוי אין אמיתי שנעשה בבחי' יש אמיתי להתגלות אליהם בבחי' מקור וזהו\"ע יפאר<sup data-n=\"1089\">41</sup>, וזהו ג\"כ ענין השתחוו לה' בהדרת קודש<sup data-n=\"1090\">42</sup>, כי קודש מילא בגרמי' הוא ענין החכ' שהוא בחי' אין האמיתי להיות כי בה שורה אא\"ס הפשוט כו' כנ\"ל, וכאשר נגלה בבחי' הת\"ת [שהוא ענין יש אמיתי] נק' הדרו של קדש שזהו גורם ענין ההשתחואה כו' וד\"ל. אך זהו לפי שעה בבחי' הכנה בכדי שיתגלה אח\"כ אא\"ס במ\"ת בבחי' יש במורגש בבחי' התקשרות המשפיע במקבל ואעפ\"כ לא יהי' נפרד כלל ח\"ו כנ\"ל.\n<b>והנה</b> כדוגמא זו צ\"ל בכל עלי' ממדריגה למדריגה וכן לימוה\"מ שיתגלה גילוי חדש בחי' סתים דתורה [כי בעת מ\"ת לא נתגלה רק בחי' גליא דתורה] יהי' ג\"כ העברה בים בבחי' למדריגה יותר גבוה והוא ענין והחרים ה' את לשון ים מצרים<sup data-n=\"1091\">43</sup> כו', וכן לעוה\"ב יתגלה גילוי יותר עליון שהוא ענין שמחה של מצוה<sup data-n=\"1092\">44</sup> היינו השמחה מצד עצם המצוה לא מצד הכוונה שבה רק מצד רצון העליון שבה בלבד והוא ענין השמחה במהו\"ע כענין וישמחו בך<sup data-n=\"1093\">45</sup>, יצטרך להיות עוד העברה שני' רק שתהי' בנהר ולא בים [וההפרש בכל הנ\"ל ית' לקמן] כו' וד\"ל.",[["1085","37","<b>לכ\"א מחיצה בפ\"ע</b>: להעיר מאבן עזרא יתרו יט, יז."],["1086","38","<b>שבקי\"ס הי' הכנה לזה</b>: ראה גם לעיל מאמר ד\"ה הפך ים הא' ובהערה 2."],["1087","39","<b>ים דומה לרקיע</b>: סוטה יז, א."],["1088","40","<b>ראתה שפחה על הים</b>: מכילתא בשלח טו, ב."],["1089","41","<b>וזהו\"ע יפאר</b>: ניתוסף ע\"פ ב."],["1090","42","<b>השתחוו לה' בהדרת קדש</b>: תהלים כט, ב."],["1091","43","<b>והחרים ה' את לשון ים מצרים</b>: ישעי' יא, טו."],["1092","44","<b>שמחה של מצוה</b>: ראה גם לקמן מאמר ד\"ה אם בחוקותי הא' ובהערה 18."],["1093","45","<b>וישמחו בך</b>: נוסח תפלת העמידה ליו\"ט."]]],[4801940090,"<b>והנה</b> להבין בתוס' ביאור<sup data-n=\"1094\">1</sup> שרשי הדברים דה' בחי' יש ואין אין ויש ואין האמיתי כו', וגם להבין איך תוכלל הנשמה במהו\"ע בבחי' יחוד דיש האמיתי ולא תתבטל ממציאותה כלל ושאר פרטי הדברים כו'. הנה יש להקדים שיש ג' בחי' בהשתלשלו', הא' השתלשלו' מיש ליש והוא ענין מאמר דבראשית<sup data-n=\"1095\">2</sup> ומאמר יהי אור<sup data-n=\"1096\">3</sup> כו', והב' השתלשלות מיש לאין שהוא מאמר יהי רקיע<sup data-n=\"1097\">4</sup> כו', והג' השתלשלו' מאין ליש דבי\"ע שהוא ענין מאמר יקוו המים<sup data-n=\"1098\">5</sup> כו' ותראה היבשה כו'. וביאור הדברים מבשרי אחזה<sup data-n=\"1099\">6</sup> שעצם הנפש הוא פשוט, ואעפ\"כ הוא נתפס בעצמותו בבחי' עשר כחות שכל ומדות, והנה עשר כחות הנ\"ל המה מתאחדי' בנפש עצמו עד שמהות הנפש עצמו תתפס בהם [וראי' לזה שאינם מוגבלים כמו הנפש עצמו כו' להיות אנו רואים שכל מיני השפעות שמחמת מדת האהבה במחדו\"מ לא יגיעו לעצם נקודת האהבה שהוא כח האוהב, וכן בחכ' כל מיני התפשטות שכל והסבר לא יגיעו לעצם עומק נקודת השכל שהוא ענין כח המשכיל השכלה זאת בפרט כו'], ולכן נק' עשר כחות אלו בשם עצם הנפש בלק\"א ח\"א פ\"ג<sup data-n=\"1100\">7</sup>. והנה לבושין דמחדו\"מ<sup data-n=\"1101\">8</sup> האור וחיות שנמשך בהן מהבל הלב בב' מיני קול קלא פנימאה כו' וקלא דמשתמע<sup data-n=\"1102\">9</sup> כו' הוא רק אור וזיו בלבד להיות שעצמות הנפש נתעלמה שם בהבל הלב שבחזה ורק התפשטותה מאיר כו' ולכן נק' הבל הלב שבחזה בשם אתא קלילא דלית בה משש\"א<sup data-n=\"1103\">10</sup> היינו התעלמות המהות ולכן נק' מחדו\"מ בשם לבושי הנפש ולא בשם עצם הנפש. והנה כח המעשה אע\"פ שהוא לבוש האחרון שבנפש הנה יש שרש למציאותו בבחי' כחות העצמי' בכל כח וכח בפרט [ולמעלה מהם בעצמו' הנפש והוא המעתיק לעצמות הנפש ממקום למקום להיות נתפס בעשר כחות והוא המשתלשל אח\"כ בכל כח בפרט עד שבא לבחי' סמ\"ע<sup data-n=\"1104\">11</sup> בגילוי, ולכן אדם הוא בחי' מוח ולב ומעשה כי נחשב מכלל ציור אדם שהוא ענין תפיסת עצמי' הנפש בבחי' עשר כחות להיות מקור להשפעה כו' וד\"ל].\n<b>וביאור</b> הענין הנה כשמצוה לזולתו לעשות נק' ציווי הזה בשם עשי' שבדיבור [וכענין עקימת שפתיו הוי מעשה<sup data-n=\"1105\">12</sup> כו'] וכשעושה בעצמו ע\"פ מחשבה שבמוחו שמוכרח להיות תחילה מח' איך לעשות נק' עשי' שבמח'. וכ\"ז הוא ענין התכללות כח המעשה בלבושי הנפש. אך באמת שרש כח המעשה הוא בתחילה בבחי' מדות שבלב ג\"כ היינו כשנתפעל בבחי' תשוקה וחמדה לדבר נבדל כמו לבנין",[["1094","1","<b>והנה להבין בתוס' ביאור</b>: דרוש ר\"ה.\nביאור (רק חלק) למאמר ד\"ה שרש ענין קי\"ס שנדפס לפנ\"ז."],["1095","2","<b>מאמר דבראשית</b>: בראשית א, א. ר\"ה לב, א."],["1096","3","<b>יהי אור</b>: בראשית א, ג."],["1097","4","<b>יהי רקיע</b>: שם א, ו."],["1098","5","<b>יקוו המים</b>: בראשית א, ט."],["1099","6","<b>מבשרי אחזה</b>: ע\"פ איוב יט, כו."],["1100","7","<b>בלק\"א ח\"א פ\"ג</b>: ראה גם לקמן מאמר ד\"ה ענין יצי\"מ וקי\"ס על יד הערה 16."],["1101","8","<b>לבושין דמחדו\"מ</b>: ראה תניא פ\"ד."],["1102","9","<b>קלא פנימאה כו' וקלא דמשתמע</b>: ראה זהר בראשית נ, ב. וראה גם מאמרי אדה\"א קונטרסים ע' שח. וש\"נ."],["1103","10","<b>אתא קלילא דלית בה משש\"א</b>: ראה פיוט אקדמות לשבועות."],["1104","11","<b>סמ\"ע</b>: סוף מעשה."],["1105","12","<b>עקימת שפתיו הוי מעשה</b>: ראה ב\"מ צ, סע\"ב. לקו\"ת שמ\"ע פד, ג. תו\"ח שמות ח\"א ה, א הערה 235."]]],[4801940155,"מפואר וכה\"ג [כי בלתי איזה דבר נבדל לא תפול מציאות ההתפעלות כלל כו']. ועוד יש לשרש כח המעשה בשכל שבמוח, כי כל התפעלות וחמדה מוכרח להיות ע\"פ שכל בתחילה היינו הרגשת דבר הנבדל במוחו ע\"י שהרגיש הפאר ויוקר וחשיבות הדבר במוחו שעי\"ז נתפעל בלבו. והנה בהתפעלות יש ב' בחי' הא' בחי' פנימי' המדות שמתאחדי' עם השכל כמו שאנו רואים בחוש שתיכף כשירגיש איזה דבר טוב בשכלו שיולד כח המושך בלבו בלתי הרגש עדיין כלל, אך אח\"כ נמשך בחי' התפעלות מורגשת בלב הנק' תשוקה שבלב והוא ענין חיצוני' המדות. והנה מה שנמשך בלב בפנימיותו לאיזה דבר נחמד הוא ענין התכללות כח המעשה עם המדות שניהם כאחד בבחי' השכל שבמוח.. . <sup data-n=\"1106\">13</sup>",[["1106","13","<b>שבמוח. . . </b>: ע\"כ נמצא. וראה גם ברשימת הכת\"י כאן."]]],[4801940091,"<b>להבין</b> ההפרש בין קי\"ס<sup data-n=\"1107\">1</sup> שבזש\"פ לליל א' של פסח ובין שאר כל הניסים, הנה נס הוא ענין הרמה<sup data-n=\"1108\">2</sup> וכמו התפילה שמתפלל על החולה שאומרי' יר\"מ<sup data-n=\"1109\">3</sup> שאין הכוונה שינוי רצון ח\"ו רק הכוונה שהשינוי הוא בצירופי אותיות להיות שהחולה פגם ע\"י חטא ועון והמשיך עליו צירופי אותיות של דין משם אלקים<sup data-n=\"1110\">4</sup> עד שגרם חסרון הכלי שלו כמו ניקב הריאה ר\"ל ומצד זה ממילא נסתלק האור והחיות שלו אך ע\"י מס\"נ ורעותא דליבא<sup data-n=\"1111\">5</sup> של המתפלל נכללת נפשו במקור החיים בבחי' העלאות מ\"נ ומעורר משם צירופי אותיות חדשים של חסד שגורמים המשכת החיות להשלים הריאה וכדומה ועי\"ז ממילא נמשך אור וחיות חדש לנפש החולה, כי דרכו של איש<sup data-n=\"1112\">6</sup> לחזור אחר אשה לכן ע\"י השלמת הכלי גורמים המשכת חיות חדש כו', וכ\"ז אינו פועל שום שינוי ח\"ו ברצה\"ע כי הרצון הוא מובדל מגדר התחלקות חו\"ג לכן אין שינוי ההתלבשות מצירופי אותיות של גבורה לצירופי אותיות של חסדים פועל שום שינוי ח\"ו בעצם וזהו\"ע הנס שהוא ל' הרמה שזהו\"ע הרמת צירופי אותיות של דין למקורא דכולא<sup data-n=\"1113\">7</sup> ונמתקים שם ועי\"ז נעשו צ\"א של חסד לרפאות הכלי<sup data-n=\"1114\">8</sup> ולהמשיך בו אור וחיות חדש כו'. וכן ענין רחב\"ד שא' מי שאמר לשמן<sup data-n=\"1115\">9</sup>",[["1107","1","<b>להבין ההפרש בין קי\"ס</b>: דרוש ר\"ה."],["1108","2","<b>נס הוא ענין הרמה</b>: רש\"י יתרו כ, יז. ראה אוה\"ת בשלח ע' תרסה. שה\"ש ח\"א ע' כט."],["1109","3","<b>שאומרי' יר\"מ</b>: ראה גם סידור שער החנוכה רעג, ב ואילך. מאמרי אדה\"ז תקס\"ח ח\"א ע' מט. תו\"ח תצוה ח\"ב שעה, ג ואילך."],["1110","4","<b>דין משם אלקים</b>: ראה ירושלמי ברכות פ\"ט, ה\"ה. רש\"י בראשית א, א. הנסמן במאמרי אדה\"ז על פרשיות התורה ח\"א לע' שלז."],["1111","5","<b>ורעותא דליבא</b>: זהר וירא ק, א."],["1112","6","<b>דרכו של איש</b>: קדושין ב, ב. ראה גם שער היחוד קל, ב."],["1113","7","<b>למקורא דכולא</b>: זהר בראשית לג, א."],["1114","8","<b>צ\"א. . הכלי</b>: ג: צירופי אותיות. . (תוקן) החולה."],["1115","9","<b>מי שאמר לשמן</b>: ראה תענית כה, א (כגי' הע\"י). מאמרי אדה\"ז על פרשיות התורה ח\"א ע' קעח. ע' ערב ובהנסמן במ\"מ לשם. תו\"ח שמות ח\"א כ, א. וש\"נ."]]],[4801940156,"וידליק יאמר לחומץ וידליק שזהו יותר נעלה מבחי' התפילה כנ\"ל להיות שהי' בבחי' צדיק מושל ביראת אלקים<sup data-n=\"1116\">10</sup> לזאת גזר על שם אלקים שישתנה צירופי אותיות המלובשים בשמן שגורמי' טבע המשכתו אחר האור ולהדליקו כמו טבע השמן וזהו ג\"כ ע\"י המשכת צירופי אותיות חדשים ממקור החיות הנק' מי (כמשי\"ת) בחומר של החומץ שישתנה טבעו שהוא ג\"כ ענין הנס ל' הרמה כו', וכן ענין רפב\"י שאמר לגנאי<sup data-n=\"1117\">11</sup> חלוק לי מימיך שהמשיך צירופי אותיות דיבשה בים ועי\"ז נעשה מים יבשה שזהו אופן יותר נעלה מרחב\"ד הנ\"ל שלא הוצרך לצוות לכח הפועל אלקי כענין מי שאמר רק בעצמו גזר והמשיך צירופי אותיות חדשים בטבע הנבראים להפוך מים ליבשה, והמשכה זאת היתה ג\"כ מבחי' מקור החיות של הנבראים לשנות צירופי אותיות הנ\"ל שזהו ג\"כ ענין הנס כנ\"ל (ושורש הדברים ע\"פ המבואר מא' הזוהר דאיילתא שיש ג' בחי' נשמות<sup data-n=\"1118\">12</sup> וכל הבחי' המה מבחי' אצי', הא' בחי' נשמות דאצי' שבאים בבחי' תולדה מאין ליש והמה לא יכלו לפעול ענין המשכה חדשה הנ\"ל רק ע\"י מס\"נ ברעותא דליבא כו', והב' בחי' נשמות שנמשכי' מבחי' פנימיות הכלים דאצי' הנק' אחים ורעים שהמה בחי' הדכר שזהו צדיק מושל ביראת אלקים שהוא בחי' הנוק' לכן יוכלו לגזור על בחי' המל' בחי' כח הפועל אלקי לשנות הטבע והיינו המשכת צירופי אותיות חדשים ממקור החיות שנק' מי, אבל יש עוד בחי' ג' הנק' תאומים ששרשם בבחי' חו\"ב שהמה אחים ממש לז\"א שהם בבחי' הביטול למקורא דכולא עד שהדיבור שבהם הם בחי' דברי אלקים חיים ממש לכן הוא בעצמו הוא הגוזר כו' וד\"ל).\n<b>אך</b> להבין ענין מדריג' מקור החיים המהפך צירופי אותיות מהו, יובן מבשרי אחזה<sup data-n=\"1119\">13</sup> שצירופי אותיות הדיבור נמדדו כבר במדה ושיעור בה' מוצאות הפה עד שלא יוכלו להשתנות לצירופי אותיות אחרים, ושורש המדידה שלהם הוא מבחי' מדת האהבה שבלב ולכן כשיצטרך להפוך הצירופי' לא יוכל להיות כ\"א כשיתהפך המדות שבלב, אך גם התהפכות המדות שבלב לא יוכל להיות מצ\"ע כי גם המה נמדדו כבר מבחי' השכל רק להיות שכל עיקר המדידה שלהם הוא בבחי' מדות שבשכל הנק' שכל מטה כלפי חסד כו' אך בעצם השכל וההשגה שהוא בחי' ג\"ר דחו\"ב אין שם מדה עדיין כלל רק המה בבחי' התרחבות גדול בלתי הגבלה בכלים עדיין (כי עיקר בחי' התגלות הכלים הוא בבחי' המדות דווקא ולכן נמצא בהם שני הפכי' דחו\"ג גם בשרשם בבחי' השכל הנק' מדות שבשכל כו') ונק' מוחין דגדלות כו', ולכן אנו רואים שמסברא א' יוכל להתהפך מחוב לזכות כמ\"ש במ\"א בענין הסברא דיצר לב האדם<sup data-n=\"1120\">14</sup> כו' כי מתחילה נסתעף מזה סברא לחוב למחות את האדם",[["1116","10","<b>צדיק מושל ביראת אלקים</b>: שמו\"ב כג, ג [ושם יראת — ראה מוע\"ק טז, ב ובר\"ח שם. מאמרי אדה\"א שמות ח\"א ע' קע. וש\"נ. ח\"ב ע' שלב. שע\"ת קיג, ג. שעה\"י קמד, ב]. ראה גם בהנ\"ל."],["1117","11","<b>רפב\"י שאמר לגנאי</b>: חולין ז, א."],["1118","12","<b>מא' הזוהר דאיילתא שיש ג' בחי' נשמות</b>: ראה זהר פינחס רמט, א. ביאוה\"ז שם קיד, ד — קטו, ב. ולהצ\"צ שם כרך א ע' תקמו ואילך."],["1119","13","<b>מבשרי אחזה</b>: ע\"פ איוב יט, כו."],["1120","14","<b>דיצר לב האדם</b>: נח ח, כא. ראה גם לקמן ביאור מאמר ד\"ה והניף הכהן אותם ובהערה 54."]]],[4801940218,"ואח\"כ ע\"י התהפכות הרצון לחסד ע\"י הקרבן נתהפך הסברא זאת עצמה לזכות להיות כי יצר לבו רע בטבעו לכן אין להאשימו על כך וא\"כ לא אוסיף כו', וזהו בחי' מים קודם שנגלדו בבחי' רקיע דניידי לכאן ולכאן ולכן מבחי' עצם השכל וההשגה יכול להיות מדידה אחרת לגמרי בשכל עצמו ועי\"ז ממילא יתהפכו המדות שבלב וממילא יסתעפו צירופי אותיות חדשים בדבור לדבר באופן אחר, ועד\"ד<sup data-n=\"1121\">15</sup> זאת הוא ג\"כ במעשה הבנין שכאשר ירצה לשנות הציור לא יוכל להיות מבחי' המדות שבלב ולא מבחי' המדות שבשכל רק כשיתרומם הציור שכבר הוגבל לבחי' עצם השכל שהוא בבחי' התרחבות גדול ואינו מוגבל בכלי כנ\"ל ושם אין מדידת הציור תופס מקום כלל אז יוכל להשתנות הציור באופן אחר עד שיתגלה במדות שבלב ומשם למעשה בפו\"מ כו' וד\"ל.\n<b>וככה</b> יובן למשכיל למעלה בענין מקור חיות הנבראים שנמשך מבחי' צירופי אותיות מדת מלכותו<sup data-n=\"1122\">16</sup> ית' שנק' בשם דבר הוי' או כח הפועל אלקי (כענין אף ידי יסדה ארץ<sup data-n=\"1123\">17</sup> כו') ששורש מקור האמיתי שלהם הוא מבחי' מדת חסדו של הקב\"ה כמ\"ש כי אמרתי עולם חסד יבנה<sup data-n=\"1124\">18</sup> ששם נמדדו בהעלם כל פרטי חיות הנבראי' שנמשכו אח\"כ בגילוי ע\"י דבר הוי' וכח הפועל, ושורש היותר ראשון של המדידה הוא בבחי' המדות דחו\"ב (שכ\"ז נק' בחי' מוחין דקטנות בחי' מוחי' השייכי' להשתל' כו'), אך מבחי' ג\"ר דחו\"ב הבלתי מוגבלים בכלים כלל וזהו בחי' חכים ולא בחכ' ידיעא מבין<sup data-n=\"1125\">19</sup> כו' משם יכול להיות התהפכות המדות מגבו' לחסד עד שיתגלה השינוי בצירופי אותיות שנבראו בהם שו\"א בפו\"מ (וביאור הדברים בדרך קצרה הנה ידוע דבמקום גדולתו שם אתה מוצא ענוותנותו<sup data-n=\"1126\">20</sup> כי גדול הוי' בבחי' א\"ס רק מצד שעלה ברצונו להיות עולמות מוגבלים במקום ומספר לזאת השפיל וצמצם א\"ע להתלבש בבחי' החסד שהוא ענין הגילוי לזולתו דווקא ולכן אנו רואים טבע מדת החסד שנמשך מצד השפלות דוקא שאינו צריך לעצמו כלום כמו אברהם שאמר אנכי עפר ואפר<sup data-n=\"1127\">21</sup> לכן עביד טיבו יתירא<sup data-n=\"1128\">22</sup> עם כל ברייתא כו'). וזהו במקום גדולתו שהוא מדת החסד שם בפנימיותם אתה מוצא ענוותנותו שהוא ענין השפלת וירידת מעצמותו בד\"כ ומזה נמשך אח\"כ בפרט בדבר הוי' מקור המחי' כל העולמות בפו\"מ שהוא מדת מלכותו ית', נמצא שמדידה אמיתית של כל פרטי הנבראים כמו עיגולי השמים וכדומה הוא בבחי' מדת החסד כנ\"ל, אך מדידת אופן ההשפלה להתלבש במדת החסד (שהי' יכול להיות בריבוי אופנים מצד עצם כח הא\"ס) בא ע\"פ קו",[["1121","15","<b>ועד\"ד</b>: ועל דרך דוגמא."],["1122","16","<b>מקור חיות. . מדת מלכותו</b>: ראה לקמן מאמר ד\"ה להבין ההפרש בין שליו\"ט תר\"ב ובהערה *36."],["1123","17","<b>אף ידי יסדה ארץ</b>: ישעי' מח, יג."],["1124","18","<b>כי אמרתי עולם חסד יבנה</b>: תהלים פט, ג. ראה גם לקמן מאמר ד\"ה ענין יצי\"מ וקי\"ס על יד הערה 90. וש\"נ."],["1125","19","<b>חכים. . מבין</b>: ראה ת\"ז בהקדמה יז, ב."],["1126","20","<b>דבמקום גדולתו. . ענוותנותו</b>: ראה מגילה לא, א. סה\"מ תרנ\"א ע' עא. ה'ש\"ת ע' 40 בהערה. תו\"ח יתרו רנט, ב הערה 122."],["1127","21","<b>אנכי עפר ואפר</b>: וירא יח, כז [ושם: ואנכי]."],["1128","22","<b>עביד טיבו יתירא</b>: ראה זהר ואתחנן רסב, ב. סידור שער התפילין יב, א. אמ\"ב שם קלז, א."]]],[4801940271,"המדה דחכ' וזהו כי אמרתי מתחלה ואח\"כ עולם חסד יבנה), שזהו בחי' הארה בעלמא מעצם חכמתו ית' שהוא בבחי' א\"ס חכי' ולא בחכ' ידיעא כו' ולכן כל פרטי העשי' הנ\"ל בג' אופנים כנ\"ל צ\"ל ההרמה למקור החיים עצם חכמתו ובינתו ית' ומשם יוכל להיות המשכה חדשה עד שיתגלה שינוי צירופי אותיות בפו\"מ בדבר הוי' המחי' את כל הנבראים כו' וד\"ל). וזהו מי שאמר לשמן וידליק כו' פי' מי הוא בחי' ג\"ר דבינה שלמעלה משורש המדות ולכן הוא בבחי' קיימא לשאלה<sup data-n=\"1129\">23</sup> ולא לאתבא כי התשובה לא יוכל להיות רק בדבר שבא במדה ושיעור בבחי' התלבשות בכלים כו' ולכן גזר ואמר שמבחי' זו יומשך מוחין דגדלות תוך ז\"א שהוא בחי' מקור האמיתי של השתל' כידוע בענין כי ששת ימים עשה<sup data-n=\"1130\">24</sup> כו', ועי\"ז יהי' שינוי צירופי אותיות בדבר הוי' הנק' כח הפועל אלקי המלובש בנפעל כנ\"ל וד\"ל.\n<b>וזהו</b> שרש כל הנסים הנעשים בשינוי הטבע, וכן עד\"ז הניסים שבירדן<sup data-n=\"1131\">25</sup> כו', אבל קי\"ס לא הי' באופן זה להמשיך בחי' מוחין דגדלות דמקור ההשתל' הנק' ז\"א כי הי' צ\"ל אז בבחי' הקטנות הן בבחי' פנימיותו כי פנימי' המדות הוא שרש מקור נש\"י (כמ\"ש במ\"א בענין כי כל אוכל חמץ<sup data-n=\"1132\">26</sup> כו' מיום הראשון עד יום השביעי כו'), ולהיות דאז הי' נש\"י בתכלית הקטנות ולכן הוצרך להיות להם צמצום השפע בבחי' הקטנות לפי אופן מדרגתם עד\"מ רב המשפיע שכל לתינוק קטן שמוכרח להמציא צירופי אותיות המגבילים השכל לפי\"ע התינוק, וזהו בים נדמה להם כבחור<sup data-n=\"1133\">27</sup> בבחי' הקטנות והן בבחי' חיצוניותו שהוא שרש ומקור ההשתל' הי' בבחי' הקטנות כי הקטנות הוא בבחי' גבורות ודינין לטבוע את מצרים בים סוף וזהו כבחור איש מלחמה להעביר קליפת מצרים וכמ\"ש ה' איש מלחמה<sup data-n=\"1134\">28</sup>, משא\"כ כשהי' המשכת מוחין דגדלות בבחי' המדות לא הי' יכול להיות התעוררות הגבו' להעביר קליפת מצרים כי מוחין דגדלות הוא מקור הרחמי' והחסדי' כידוע שכל מי שהוא חכם גדול ביותר יותר יוכל לסבול שונאו ואדרבה ישפיע לו טוב וחסד כו', ולהיות שז\"א שהוא בחי' מקור ההשתל' הי' צ\"ל בבחי' הקטנות ואעפ\"כ הוצרכו לשינוי הטבע להפוך מים ליבשה כמשי\"ת לזאת הי' מוכרח להיות הנס שהוא ענין הגבהת והרמת כח הפועל אלקי למדריגה גבוה מאוד שלמעל' ממקור החיים שנק' מי, והוא בבחי' עתיקא ולכן נא' מה תצעק אלי<sup data-n=\"1135\">29</sup> בעתיקא תליא מלתא, ואתם תחרישון לא תתערו מלה<sup data-n=\"1136\">30</sup>, כי צריך לעורר ממקום הגבוה מאוד נעלה אפי' ממקור היותר ראשון דאותיות הדיבור כמשי\"ת שלזה אין מועיל רק צעקת הלב בלחש שהוא גילוי נקודת פנימיות הלב שלמעלה ממקור השכל וזהו ע\"י התשובה",[["1129","23","<b>מי. . קיימא לשאלה</b>: זהר בהקדמה א, ב."],["1130","24","<b>כי ששת ימים עשה</b>: ראה גם לקמן מאמר ד\"ה אשה כי תזריע תרכ\"ג ובהערה 19."],["1131","25","<b>הניסים שבירדן</b>: ראה יהושע ג, יג ואילך."],["1132","26","<b>פנימי' המדות. . כי כל אוכל חמץ</b>: ראה שער האמונה כג, א."],["1133","27","<b>בים נדמה להם כבחור</b>: ראה מכילתא בשלח טו, ג. יתרו כ, ב [הובא ברש\"י שם]. שה\"א עה, ב ובהערה 20."],["1134","28","<b>ה' איש מלחמה</b>: בשלח טו, ג."],["1135","29","<b>מה תצעק אלי</b>: בשלח יד, טו. זהר בשלח מח, א. נב, ב."],["1136","30","<b>ואתם תחרישון לא תתערון מלה</b>: בשלח יד, יד. ראה זהר בשלח מז, ב. תו\"ח בשלח ח\"א קנז, ב. וש\"נ."]]],[4801940321,"מעומקא דליבא ועי\"ז מעוררים מבחי' עתיקא שלמעלה אפי' ממקור ההשתל' ולזאת יוכל להיות השינוי שלא בהדרגה והיינו שבמקור ההשתל' הנק' ז\"א לא הי' המשכה רק בהעלם ולא בגילוי כלל רק בי\"ס שהוא בחי' המל' סודכ\"ד כח הפועל אלקי בנפעל דווקא נתגלית הארת עתיקא לשנות סדרי ההשתל' לעשות מים ליבשה ובמקור ההשתל' שהוא בחי' ז\"א אין שום שינוי כלל כנ\"ל. וזהו עוצם גודל הנס הנפלא שלא יוכל להיות זאת רק מבחי' הארת עתיקא שלמעלה אפי' מבחי' חו\"ב בעצם הנ\"ל בכל הניסים רק בקי\"ס האיר מבחי' עתיקא ולכן יוכל להיות דילוג כזה. וזהו ג\"כ ענין מאמר הזוהר<sup data-n=\"1137\">31</sup> איילתא אזלת לטורי חשוכא שהו\"ע הגבהת בחי' חג\"ת דמל' מקור הנבראים דבי\"ע במקורם האמיתי מדות דעתיקא ומתמן ארחת מזונא שהו\"ע ריח של המזון בלבד להיות שההארה לא הי' עדיין בבחי' מל' רק בבחי' מקיף בלבד רק במ\"ת נתגלה בבחי' פנימי' הנק' מזון כו' וד\"ל.\n<b>וביאור</b> הדברים הנה כתיב הרם את מטך<sup data-n=\"1138\">32</sup> ונטה את ידך על הים ובקעהו, כי הנה מטה משה הוא יסוד אבא<sup data-n=\"1139\">33</sup>, ושורש זה הגילוי הוא מבחי' מקור השכל הנק' מזלא שלמעלה משכל פרטי לכן בכוחו לגלות שכל הפרטי בבחי' גילוי דברק המבריק<sup data-n=\"1140\">34</sup> הנ\"ל ולכן נק' מטה משה שהוא ענף מן האילן שהוא בחי' מזלא הנ\"ל, אך בבחי' יסו\"א הנ\"ל יש שני בחי' הא' כשמקבל מבחי' מקור השכל הנק' מזל\"א שזהו מקור נעלם הבא לידי גילוי ונק' בחי' אלף חכ' אלף בינה<sup data-n=\"1141\">35</sup> להיות שעתיד לבוא לידי השכלה והשגה (שזהו\"ע שתי מזלות מזל ונוצר בי' אחיד אבא ומזל ונקה<sup data-n=\"1142\">36</sup> בי' אחיד אימא כו') ואז הוא מתלבש בבחי' השגה והבנה ונמשך למדות ודבור, וזהו בחי' וחכם בבינה<sup data-n=\"1143\">37</sup> שהוא בחי' יסו\"א המתלבש בבינה, ובחי' הב' כאשר יתרומם לקבל מבחי' העלם עצם הח\"ס שלמעלה מבחי' המזלות שהוא כאשר מתגלה לפרקים העלם עצמות השכל שבלתי בא לידי גילוי ונק' פלא שכל הנעלם מכל רעיון<sup data-n=\"1144\">38</sup> ואז לא יוכל להתלבש בבחי' השגה והבנה ומכ\"ש במדות ודבור (וכמו שתיק רב<sup data-n=\"1145\">39</sup> כו'), וזהו הרם את מטך והוא ענין הרמת יסו\"א לקבל מעצם<sup data-n=\"1146\">40</sup> ח\"ס הנק' פלא, אך סיבת זה הגילוי שלא כמדת ההשתל' כי (כי ע\"פ סדר השתל' עצם ההעלם לא יכול לבוא לידי",[["1137","31","<b>מאמר הזוהר</b>: ראה זהר פינחס רמט, סע\"א ואילך."],["1138","32","<b>הרם את מטך</b>: בשלח יד, טז."],["1139","33","<b>מטה משה הוא יסוד אבא</b>: ראה ע\"ח שער הארות המוחין זו\"ן של\"ב, פ\"ב. מאו\"א מערכת מטה סס\"ד."],["1140","34","<b>דברק המבריק</b>: ראה גם בענין ברק המבריק לקמן מאמר ד\"ה והניף הכהן אותם הב' ובהערה 54."],["1141","35","<b>אלף חכ' אלף בינה</b>: ע\"פ איוב לג, ג. שבת קד, א. ראה מאמרי אדה\"א דברים ח\"א ע' רכד ואילך."],["1142","36","<b>שתי מזלות מזל ונוצר. . ונקה</b>: ראה גם לקמן ביאור מאמר ד\"ה והניף הכהן אותם ע' שמג ואילך. וש\"נ."],["1143","37","<b>וחכם בבינה</b>: ס\"י פ\"א, מ\"ד."],["1144","38","<b>שכל הנעלם מכל רעיון</b>: ראה פיוט אל מסתתר. מאמרי אדה\"ז על פרשיות התורה ח\"ב ע' עתר ובהנסמן במ\"מ לשם. מאמרי אדה\"א בראשית ע' ח. וש\"נ."],["1145","39","<b>שתיק רב</b>: ביצה ו, א. ראה גם מאמרי אדה\"א קונטרסים ע' קיג. לעיל מאמר ד\"ה הפך ים הב' על יד הערה 13."],["1146","40","<b>מעצם</b>: א: מבחי' עצם."]]],[4801940370,"גילוי)<sup data-n=\"1147\">41</sup> תלוי בבחי' גילוי עצם התענוג ורצון, כי בבחי' התענוג ורצון יש שני בחי' הא' איזה תענוג ורצון מורכב באיזה דבר פרטי כמו חסד וגבו' ונק' מדות שברצון ותענוג, וזהו בחי' טורי נהורא שבתענוג ויתגלה עד שנעשו מקור להשפעה בחו\"ב ומדות ומעשה וזהו כמו ההרים שאור השמש מאיר עליהם שנראים בבחי' יש. והב' כאשר מתגלה עצם התענוג ורצה\"פ (בלתי מורכב בדבר) הכללי<sup data-n=\"1148\">43</sup> שאז כל פרטי עונג המורכב המה נכללי' בו בתכלית הביטול ונק' טורי חשוכא<sup data-n=\"1149\">42</sup> כמשל ההרים שאין אור השמש מאיר עליהם שאינם נראים ואינו ידוע כלל אם יש בחי' הרים אם לאו, ועד\"ז ג\"כ כאשר מתגלה עצם התענוג הפשוט שהוא ענין גילוי רוממות עצמות הנפש אז אין לו חפץ בשום תענוג פרטי ואינו מלובש בהם כלל להיותם נכללים כולם בבחי' תעה\"פ ואז יוכל להיות התגלות ג\"כ עצם כח המשכיל מהעלמו העצמי לבוא לידי גילוי (וכענין ר' אבוה שמצא תוספתא חדתא שהוא ענין גילוי העלם ח\"ס הנק' שכל הנעלם מכל רעיון וצהבו פניו<sup data-n=\"1150\">44</sup> מצד התגלות עוה\"פ<sup data-n=\"1151\">45</sup> שזה הי' בתחלה מקור גילוי העלם השכל רק נתגלה אחר גילוי השכל ונתלבש בבחי' הארת פנים בגשמיות (כענין חכמת אדם תאיר פניו<sup data-n=\"1152\">46</sup> כו'). ועד\"ז יובן למעלה ז\"א הוא בחי' מקור ההשתל' ע\"פ קו המדה דחו\"ב שהו\"ע הארת יסו\"א באימא כנ\"ל בענין כי אמרתי כו' וקו המדה זה מקבל מבחי' מזלא שמקבלים ממדות דע\"י כו', שהוא גילוי כח היכולת דא\"ס להיות ממנו השתל' וזהו\"ע ז\"א בעתיקא אחיד<sup data-n=\"1153\">47</sup> כו' (ונק' ע\"ס הגנוזות<sup data-n=\"1154\">48</sup> במאצילן) וזהו בחי' טורי נהורא יש אמיתי, אך קודם שנתעורר היכולת בא\"ס לבוא לידי גילוי שזהו כמ\"ש לבדו שכח ויכולת הזה נק' בשם טורי חשוכא שאינו עדיין בבחי' יש אמיתי מקורא דכולא רק בבחי' אין אמיתי כו' וד\"ל.\n<b>וזהו</b> הרם את מטך בחי' הרמת יסוד אבא לקבל מבחי' טורי חשוכא הנ\"ל ואז ונטה את ידך שהוא בחי' נטיית היו\"ד<sup data-n=\"1155\">49</sup> גילוי הברקת השכל על הים דווקא שהוא",[["1147","41","<b>כי (כי. . גילוי)</b>: תוקן ע\"פ א. ובבוך זה: כי. . גילוי."],["1148","43","<b>(בלתי. . בדבר) הכללי</b>: תוקן ע\"פ א. ובבוך זה: בלתי. . בדבר הכלל."],["1149","42","<b>טורי נהורא. . טורי חשוכא</b>: זהר פינחס כאן רמט, ב. ראה גם בענין טורי נהורא וחשוכא ביאוה\"ז קרח צג, ג. פינחס קטז, א ואילך. קיז, ד. מאמרי אדה\"ז על פרשיות התורה ח\"א ס\"ע שכח. תקס\"ט ע' טז ובהנסמן במ\"מ לשם. מאמרי אדה\"א שמות ח\"א ע' פח. וש\"נ. דברים ח\"ג ע' תתקצה. וש\"נ. שע\"ת קלט, ג ובהנסמן במ\"מ לשם. שעה\"י קכז, ב ובהנסמן במ\"מ לשם. תו\"ח לך צ, ד. וירא קיב, ב. שמות ח\"א טז, א. וש\"נ. אוה\"ת ר\"ה ע' א'שצ. עמוס ע' תסט. שופטים כרך ג' ע' א'קסא. תהלים ע' רכה. לקמן מאמר ד\"ה אם בחוקותי הג' על יד הערה 120."],["1150","44","<b>ר' אבוה. . וצהבו פניו</b>: ראה ירושלמי שבת פ\"ח, ה\"א. מאמרי אדה\"א קונטרסים ע' שדמ. וש\"נ. ש\"א יב, ב. תו\"ח יתרו ח\"ב רסז, ג. סה\"מ תרכ\"ז ע' פז. וש\"נ."],["1151","45","<b>עוה\"פ</b>: עונג הפשוט."],["1152","46","<b>חכמת אדם תאיר פניו</b>: קהלת ח, א."],["1153","47","<b>ז\"א בעתיקא אחיד</b>: ראה זהר אד\"ז האזינו רצב, א. סה\"מ תרנ\"ו ע' תכז ובהערה לשם. תרל\"ב ח\"א ס\"ע יג ואילך. וש\"נ. תו\"ח בא ח\"א קל, ב ובהערה 796. ד\"ה זה היום תשמ\"א [קונט' ר\"ה תשמ\"ח — נדפס בסה\"מ מלוקט ח\"ב ס\"ע קח ואילך אות יא]."],["1154","48","<b>ע\"ס הגנוזות</b>: ראה פרדס שער סדר האצי' ש\"ה, פ\"ד. שער הצחצחות שי\"א. וראה שם פ\"ג. הנסמן במאמרי אדה\"א דברים ח\"א ע' שמו־ שעה\"י — לקו\"ב — קפט, ג-ד הערה 2."],["1155","49","<b>ידך. . היו\"ד</b>: ראה גם תו\"א ויחי מה, ד. מאמרי אדה\"א הנחות תקע\"ז ס\"ע יב. וש\"נ. תו\"ח בשלח ח\"א קמח, א. וש\"נ."]]],[4801940415,"בדילוג המדריגה שאינו מאיר בבינה ומדות רק בבחי' המל' סופא דכ\"ד הנק' ים<sup data-n=\"1156\">50</sup> ועי\"ז ובקעהו שנעשה מים יבשה, וזהו וחילופיהן בגולם<sup data-n=\"1157\">51</sup> שהוא חילוף צירופי אותיות לעשות מים ליבשה זה בגולם שהוא הגולמי של היו\"ד שאין בו עדיין שום צורה דאו\"ר<sup data-n=\"1158\">52</sup> כלל שזהו בחי' נקודא דחכ' בבחי' עצם תמציתה שלא תוכל להתלבש בבחי' או\"ר דבינה כלל שמשם נתחלפו צירופי אותיות דים ליבשה שזהו מבחי' טורי חשוכא שמשם הי' הנס הנפלא דקי\"ס בדילוג ההמשכה כו' וד\"ל. אך ענין הגילוי שהי' בליל א' דפסח ביצ\"מ והי' ג\"כ מבחי' עתיקא כנ\"ל שהאיר מבחי' יסו\"א שלמעלה מהתלבשותו בבחי' בינה אך הגילוי הזה נמשך בבחי' פנימיות בבחי' המדות דאצי' מקור נש\"י כנ\"ל, ונק' מזון ממש וזהו ענין אכילת מצה דליל א' שהוא ענין בחי' המשכת חסדי' דעתיקא בבחי' יסוד אבא ומשם לז\"א, וזהו מצות יאכל את שבעת הימים<sup data-n=\"1159\">53</sup> כו'. ויובן הדברים ע\"פ המבואר במ\"א בענין אין התינוק יודע לקרות אבא<sup data-n=\"1160\">54</sup> שזהו\"ע קטנות ההכרה במהו\"ע אא\"ס ממש הנק' לבדו שנעשה למזון ממש בנפשם שהו\"ע חיזוק כח האמונה להסתעף מזה כל היום ענין סו\"מ וע\"ט בתכלי' והיינו שנמשך ע\"י יסוד אבא שלא ע\"י בחי' אימא לכן נאסר אכילת חמץ<sup data-n=\"1161\">55</sup>.",[["1156","50","<b>המל'. . ים</b>: ראה זהר בהעלותך קנ, ב. הנסמן במאמרי אדה\"א שמות ח\"ב ע' תסג."],["1157","51","<b>וחילופיהן בגולם</b>: אבות פ\"ה, מ\"ז."],["1158","52","<b>דאו\"ר</b>: דאורך ורוחב."],["1159","53","<b>מצות יאכל את שבעת הימים</b>: בא יג, ז."],["1160","54","<b>אין התינוק יודע לקרות אבא</b>: ראה ברכות מ, סע\"א. לקמן מאמר ד\"ה וספרתם הה' על יד הערה 270. ד\"ה בשברי לכם הא' על יד הערה 37. לעיל ד\"ה להבין כו' פסח ומצה על יד הערה 116 ואילך. מאמרי אדה\"א דברים ח\"א ע' רמה. וש\"נ. תו\"ח בא ח\"א צה, ב. וש\"נ."],["1161","55","<b>חמץ</b>: בהכתבי יד נרשם: חסר קצת תשלום המאמר."]]],[4801940092,"<b>תורת אדמו\"ר כת\"י החסיד המפורסם ר' הלל מפאריטש</b>\n<b>ענין</b> יצי\"מ וקי\"ס<sup data-n=\"1162\">1</sup> ואיך הוא בכל יום כמארז\"ל בכל יום חייב אדם לראות א\"ע כאילו [הוא] יצא ממצרים<sup data-n=\"1163\">2</sup>. גם להבין ענין ונשב בגיא<sup data-n=\"1164\">3</sup> מול בית פעור וסמיך לי' ועתה ישראל<sup data-n=\"1165\">4</sup> שמע אל החוקים כו', מה ענין זל\"ז. גם להבין ענין הירושלמי ר'",[["1162","1","<b>ענין יצי\"מ וקי\"ס</b>: כנראה דרוש ר' הלל.\nלמאמר זה ראה מאמר ד\"ה ונשב בגיא נדפס במאמרי אדה\"ז תקס\"ב ח\"א ע' פח. אתהלך לאזניא ע' רנח. אוה\"ת ואתחנן ע' קמד. מאמרי אדה\"א דברים ח\"א ע' קנ.\nולפסקאות והנה ע\"ד הפרסא — והנה להבין ראה גם מאמרי אדה\"ז תקס\"ה ח\"א ע' ה ואילך. נביאים ע' רכג. ענינים ע' סב — סג.\nראה עוד ע\"ד המאמר לקמן ברשימת הכת\"י."],["1163","2","<b>בכל יום. . יצא ממצרים</b>: ראה פסחים קטז, ב (במשנה). תניא פמ\"ז. הגדה עם לקוטי טעמים (קה\"ת תשמ\"ו ואילך) ע' תריח בשולי הגליון."],["1164","3","<b>ונשב בגיא</b>: ואתחנן ג, כט."],["1165","4","<b>ועתה ישראל</b>: שם ד, א."]]],[4801940157,"חייא רבא<sup data-n=\"1166\">6</sup> אמר מיומא לא אכוונית<sup data-n=\"1167\">5</sup> כו'<sup data-n=\"1168\">7</sup> יומא חד בעית לכווני כו' מאן עייל לבי מלכא בראשא<sup data-n=\"1169\">8</sup> אלקפטא<sup data-n=\"1170\">9</sup> או ר\"ג<sup data-n=\"1171\">10</sup>. ולכאורה הוא פלא איך אפשר שר\"ח לא כוון מעולם בתפילתו וכאשר רצה לכוון למה נפל דוקא זאת המח' במחשבתו.\n<b>ולהבין</b> כל הנ\"ל ילה\"ק ענין שאו מרום עיניכם<sup data-n=\"1172\">11</sup> וראו מי ברא אלה, כי הנה ענין ברא הוא ענין בריאה מאין ליש<sup data-n=\"1173\">12</sup> דווקא, כי יש ב' בחי' בהשתלשלות הא' השתלשלות עו\"ע<sup data-n=\"1174\">13</sup> והב' בחי' בריאה מאין ליש דוקא. והנה ענין השתלשלות עו\"ע יובן מבשרי אחזה<sup data-n=\"1175\">14</sup> שיש בחי'<sup data-n=\"1176\">15</sup> עצם הנפש גם יש בחי' עשר כחות<sup data-n=\"1177\">16</sup> שכל ומדות שנק' ג\"כ בשם עצם הנפש בלק\"א<sup data-n=\"1178\">17</sup> אע\"פ שהם בחי' גילויים מבחי' עצם הנפש מ\"מ להיותם מיוחדים בעצמות הנפש לזאת נק' ג\"כ בשם עצם, ויש בחי' ג' לבושים מחדו\"מ<sup data-n=\"1179\">18</sup> וכולם משתלשלים זמ\"ז כדמיון השלשלת שראש התחתונה נעוץ בסוף העליונה וסוף העליונה נעוץ בראש התחתונה כן בהשתלשלות<sup data-n=\"1180\">19</sup> זאת הרוחני' מחיצוניו' שבעליון נעשה פנימי' לתחתון<sup data-n=\"1181\">20</sup> וממילא פנימי' התחתון שהוא הביטול שלו לא יגיע רק לבחי' אחרונה שבעליון שהוא בחי' הארה שלו בלבד לא למהו\"ע העליון לכן כחות הנפש המה נמשכים רק מבחי' [אור ו]זיו של אור עצמות הנפש שהוא בחי' אחרונה שבו, וכן עד\"ז משכל למדות, וכן עד\"ז ממדות למח' וממח' לדיבור ולכן יש להן התקשרות זב\"ז ע\"י המשכת חיצוני' העליון בתחתון וע\"י ביטול התחתון בעליון כדמיון השלשלת בגשמי' כנ\"ל כמו המח' עם הדיבור א\"א לדבר בלתי המח'<sup data-n=\"1182\">21</sup> המלובש בו זולת כח המעשה שנבדל מבחי' הדיבור שיכול לעשות מצד המח' שלו שלא ע\"י אמצעות הדיבור.\n<b>והנמשל</b> מובן למעלה בבחי' ע\"ס דאצי' שנמשכים ממקורם עצמות המאציל (שהוא בחי' הכתר כו') כדוגמת עשר כחות הנפש המשתלשלים",[["1166","6","<b>רבא</b>: כ\"ה גם במאמרי אדה\"א שבהערה 1. שע\"ת פ, ג. אג: רבה — כ\"ה בהדרושים שבהערה 1. מאמרי אדה\"א שמות ח\"ב ע' שכח. במדבר ח\"ב ע' תריב. ובירושלמי שם: רובא."],["1167","5","<b>הירושלמי. . מיומא לא אכוונית</b>: ראה ירושלמי ברכות פ\"ב, סה\"ד. לקמן על יד הערה 147 בשם המדרש רבה."],["1168","7","<b>כו' </b>: אג: בתפלה."],["1169","8","<b>בראשא</b>: שם: ברישא."],["1170","9","<b>אלקפטא</b>: א: ליתא. ג: כבפנים. באוה\"ת שבהערה 1 ע' קנה: ארקפסא. ראה מערכת הערוך בירושלמי שם."],["1171","10","<b>ר\"ג</b>: ג: ריש גלותא."],["1172","11","<b>שאו מרום עיניכם</b>: ישעי' מ, כו."],["1173","12","<b>ברא. . ענין </b>[אג: ליתא]<b> מאין ליש</b>: ראה רמב\"ן בראשית א, א."],["1174","13","<b>עו\"ע</b>: בלקו\"ת ברכה צה, ב: הנזכר בספרים. שה\"ש א, ב: כמ\"ש בספרים. ראה גם רמב\"ם הל' יסוה\"ת פ\"ב, ה\"ו."],["1175","14","<b>מבשרי אחזה</b>: ע\"פ איוב יט, כו."],["1176","15","<b>בחי'</b>: אג: ב' בחי'."],["1177","16","<b>עשר כחות</b>: ראה תניא פ\"ג."],["1178","17","<b>שכל ומדות. . עצם הנפש בלק\"א</b>: ח\"א פ\"ג. וראה לעיל מאמר ביאור קי\"ס על יד הערה 7."],["1179","18","<b>ג' לבושים מחדו\"מ</b>: ראה תניא פ\"ד. וראה לעיל שם על יד הערה 8."],["1180","19","<b>השלשלת. . בהשתלשלות</b>: ראה תו\"א בשלח סד, ב. תו\"ח שמות ח\"א כד, ב הערה 36."],["1181","20","<b>מחיצוניו' שבעליון. . לתחתון</b>: ראה ע\"ח שער א\"א שי\"ד, פ\"ט. לקו\"ת שלח מא, ד ובהנסמן במ\"מ לשם. מאמרי אדה\"ז תקס\"ח ח\"א ע' תלז ואילך."],["1182","21","<b>א\"א לדבר בלתי המח'</b>: ראה אגה\"ק סו\"ס יט. תו\"ח תרומה ח\"ב שי, א ובהערה 324."]]],[4801940219,"מעצמות הנפש והם מיוחדים במקורם בתכלית כדוגמת כחות הנפש הנ\"ל, ואח\"כ מבחי' ע\"ס נמשך ג' לבושים המל', לבוש הפנימי' דמל' הוא כדוגמת אותיו' המחשבה נמשך ממנו נשמות דבריאה, לבוש האמצעי הוא כדוגמת הדיבור נמשך ממנו נשמות דיצירה, לבוש החיצון הוא כדוגמת כח המעשה נמשך ממנו נשמות דעשי', וע\"ז נאמר לבושין תקינת לון<sup data-n=\"1183\">22</sup> דמינייהו פרחין נשמתין לב\"נ, וזהו בראתיו יצרתיו אף עשיתיו<sup data-n=\"1184\">23</sup> אף הפסיק הענין<sup data-n=\"1185\">24</sup> כי היצירה עם הבריאה יש להם התחברות בגילוי כדוגמת המח' עם הדיבור אבל העשי' עם היצי' הגם שנמשך ממנו (כי אינו דומה המשל עם הנמשל [כי] במשל כח המעשה יכול למשוך בלא הדיבור משא\"כ למעלה עולם העשי' נמשך מעולם היצירה כו') מ\"מ נעלם אור היצי' לגמרי בבחי' עולם העשי' עד שאופן ההרגשה דנשמות ומלאכים דעשי' הוא מרחוק בבחי' הודאה בלבד, וזהו בהבראם בה' בראם<sup data-n=\"1186\">25</sup> כדוגמת ג' קווי הה'<sup data-n=\"1187\">26</sup> ששני הקווין באורך ורוחב מחוברים זב\"ז ורגל הקצר הוא נפסק מן הה' כו' וד\"ל. אך הנה אנו רואים בהשתלשלות עו\"ע שטבע העלול להיות בטל בעילתו כמו הדיבור בטל לגבי המח' ואע\"פ שמהות הדיבור אינו נמשך לגמרי מן המח' כי מהות הדיבור נמשך מהבל הלב [רק] צירופי האותיות נמשך מן המח' ומכ\"ש למעלה שממל' דבריאה נמשך נשמות דבריאה ואח\"כ נעשה כתר ליצירה היינו מקור מהות עולם היצירה וכן עד\"ז מיצירה לעשי' וא\"כ בוודאי כל עולם נכלל ובטל בתכלית בעולם העליון ממנו ומכ\"ש שכל ג' עולמות המה בטלים בתכלית באין האלקי המהווה אותם וא\"כ מאין יכול להיות גילוי הבריאה ליש בפ\"ע שזהו בחי' חדוש הבריאה כו'.\n<b>אך</b> הנה יובן בהקדם ענין יהי רקיע<sup data-n=\"1188\">27</sup> בתוך המים ויהי מבדיל בין מים למים היינו בין מ\"ע למ\"ת שמ\"ע המה מעל השמים, כי שמים<sup data-n=\"1189\">28</sup> הוא תענוג אלקי הנמשך לנשמות בגה\"ע דבריאה ומ\"ע הוא המשכת השפע באצי' עצמו כמאמר ונהר יוצא מעדן דחכ\"ע<sup data-n=\"1190\">29</sup> ריש כל דרגין להשקות את הגן בחי' מל'<sup data-n=\"1191\">30</sup> דאצי' סופא דכל דרגין<sup data-n=\"1192\">31</sup>",[["1183","22","<b>לבושין תקינת לון</b>: ת\"ז בהקדמה יז, א."],["1184","23","<b>בראתיו יצרתיו אף עשיתיו</b>: ישעי' מג, ז. ראה גם לקמן מאמר ד\"ה את שבתותי תרי\"ב ובהערה 25."],["1185","24","<b>אף הפסיק הענין</b>: ראה גם לעיל מאמר ד\"ה להבין שרש ענין פסח ומצה על יד הערה 15. תו\"ח בשלח ח\"א קמד, ג. וש\"נ."],["1186","25","<b>בהבראם בה' בראם</b>: ראה מנחות כט, ב. ב\"ר פי\"ב, ב."],["1187","26","<b>ג' קווי הה'</b>: ראה גם לעיל מאמר ד\"ה להבין שרש ענין פסח ומצה על יד הערה 13. תו\"א מג\"א צה, סע\"ב."],["1188","27","<b>יהי רקיע</b>: בראשית א, ו. ראה גם לקמן מאמר ד\"ה רפאיני הא' על יד הערה 19. סה\"מ תרכ\"ז ע' שמג. וש\"נ."],["1189","28","<b>שמים</b>: אג: מ\"ת."],["1190","29","<b>ונהר יוצא מעדן דחכ\"ע</b>: בראשית ב, י. ראה גם לקמן מאמר ד\"ה בסוכות תשבו הב' על יד הערה 101. ד\"ה את שבתותי תרי\"ב על יד הערה 34. תו\"ח בשלח ח\"א קמא, א ובהערה 98."],["1191","30","<b>הגן בחי' מל'</b>: ראה לקמן מאמר ד\"ה את שבתותי שם על יד הערה 38. ד\"ה והתהלכתי תרט\"ו על יד הערה 158. ד\"ה רפאיני הא' על יד הערה 41. ביאוה\"ז וירא יב, ב. מאמרי אדה\"ז תקס\"ה ח\"א ע' רנה (נו\"ש). פרדס שער עה\"כ שכ\"ג, פ\"ג מערכת גן."],["1192","31","<b>סופא דכל דרגין</b>: ראה זהר בשלח נו, א. פקודי רכו, סע\"א."]]],[4801940272,"כו', וכדי שיומשך מבחי' מ\"ע שהוא בחי' תענוג אלקי ממש שאין בו שום הרגש יש כלל להיות ממנו תענוג לנברא שיש בו קצת הרגש שמורה על הפירוד קצת כמאמר ומשם יפרד<sup data-n=\"1193\">32</sup>, צ\"ל ע\"י רקיע<sup data-n=\"1194\">33</sup> המפסיק בין אצי' לבריאה<sup data-n=\"1195\">34</sup> וענין הרקיע [הוא] כמ\"ש ועל ראשי החיות רקיע<sup data-n=\"1196\">35</sup> כעין הקרח הנורא שכמו הקרח הוא מה שנגלדו המים עצמם<sup data-n=\"1197\">36</sup> ומהם עצמם נעשה כח המעלים עליהם לגמרי אך אח\"כ יכול להיות נימס למים כמקדם, וכן יש משל רוחני יותר כמו המשל דמשלי שלמה שנמשך מחכמת שלמה עצמו ואעפ\"כ הוא מעלים החכ' לגמרי עד שנראה שהוא משל זר<sup data-n=\"1198\">37</sup> ואינו ענין לחכ' כלל ובאמת הי' במשלים אלו רזין דאורייתא אבל לא נגלו ענינם כלל לאוזן השומע כו' ואעפ\"כ מי שהוא חכם יכול להבין מן החכ' אפס קצהו מן המכוון הגנוז בו, כך יובן למעלה שענין הפרסא הוא כח הא\"ס המלובש בע\"ס דאצי' עצמן להעלים שפע הע\"ס<sup data-n=\"1199\">38</sup> שלא יהיו נגלה בחי' האין השופע רק בחי' היש המעלים ומסתיר על האין השופע [בו] כו'. וזהו כי שמש ומגן<sup data-n=\"1200\">39</sup> הוי' אלקים שכמו המסך המסתיר על אור השמש שאור הנגלה דרך המסך הוא אור חדש לגמרי רק שהוא מעין אור הראשון כך אור שם הוי' דע\"ס דאצי' נמשך מזה גילוי האור בנבראים בבחי' התחדשות גמורה מאין ליש כמו בחי' השגה, וכמו בנשמות<sup data-n=\"1201\">40</sup> דבריאה שנמשך מבחי' חו\"ב דאצי'* אעפ\"י שהוא בחי'<sup data-n=\"1202\">*41</sup> בריאה מחודשה מ\"מ הוא מעין האור האלקי דבחי' חו\"ב הנ\"ל כמשי\"ת. וזהו בחי' הב' בהשתלשלות יש מאין מה שנראה הבריאה בבחי' גילוי ליש שזהו מצד הרקיע המפסיק בין אצי' לבריאה [וכן עד\"ז בין בחי' בריאה ליצירה יש מסך<sup data-n=\"1203\">41</sup> מפסיק שמחמת זה נראה בחי' היצירה למהות בפ\"ע], וכן עד\"ז מיצי' לעשי'<sup data-n=\"1204\">42</sup> כו' וד\"ל.\n<b>והנה</b> ע\"ד הפרסא למעלה הוא בחי' חצר הכבד באדם שמפסיק בין איברי הנש[י]מה לאיברי המזון, שחיות שבאברי הנש[י]מה הוא רוחני מאוד וא\"א לו לסבול כלל דבר גשמי כמו מאכל וכדומה להתלבש בו אבל חיות שבאיברי המזון מתלבש בגשמיות המאכל להבדיל בו בין הטוב שבו לפסולת שבו, ומאין יתהווה הגשמת החיות בעצם החיות הרוחני וע\"כ לאמר שזהו מצד חצר הכבד",[["1193","32","<b>ומשם יפרד</b>: בראשית ב, י. ראה גם לעיל מאמר ד\"ה לה\"ע קי\"ס תרכ\"א על יד הערה 19."],["1194","33","<b>רקיע</b>: בהדרושים שבהערה 1: רקיע. . פרסא."],["1195","34","<b>רקיע המפסיק בין אצי' לבריאה</b>: ראה ע\"ח שער דרושי נקודות ש\"ח, פ\"ב. לקוטי הש\"ס להאריז\"ל חולין ס, ב ד\"ה לכי ומעטי (כ, ב). הנסמן במאמרי אדה\"א דברים ח\"ג ע' תתפא."],["1196","35","<b>ועל ראשי החיות רקיע</b>: יחזקאל א, כב [ושם: ודמות על ראשי החי' — ראה הנסמן במאמרי אדה\"א דברים ח\"ג ע' תתקלח. תו\"ח בא ח\"א צז, ד]."],["1197","36","<b>עצמם</b>: אג: ליתא."],["1198","37","<b>זר</b>: שם: ליתא."],["1199","38","<b>הע\"ס</b>: שם: דא\"ס."],["1200","39","<b>כי שמש ומגן</b>: תהלים פד, יב. ראה שהיחוה\"א רפ\"ד. מאמרי אדה\"א דברים ח\"ב ע' ת. וש\"נ. נ\"ך ע' שצה. וש\"נ."],["1201","40","<b>וכמו בנשמות אג</b>: ותענוג נשמות."],["1202","*41","<b>דאצי'. . בחי'</b>: שם: ליתא. . ליתא."],["1203","41","<b>בריאה ליצירה יש מסך</b>: ראה ע\"ח שער דרושי אבי\"ע שמ\"ב, פי\"ג. פי\"ד. תו\"א לך יב, סע\"ג."],["1204","42","<b>מיצ' לעשי'</b>: ראה ע\"ח שבהערה שלפנ\"ז."]]],[4801940322,"הפועל ירידת החיות והגשמתו כו'* וד\"ל. והנה כמו שאנו רואים שיש* עוד פעולה אחת בחצר הכבד והיינו שהוא מקור לכח ההבדלה<sup data-n=\"1205\">*43</sup> שבקרביים ובני מעיים בין טוב שבמאכל לפסולת שבמאכל כי המאכל [מתחילתו] הוא סולת נקי' אך כשבא לאיצטומכה אז נתברר [ונבדל] הטוב שבו ונעשה דם ונשלח לכבד וממנו נשלח ללב ומוח שלמעלה מחצר הכבד והם מקבלים חיות מזה, נמצא שהחיות שמקבלים איברי הנש[י]מה הוא ג\"כ ממה שנתברר מתחת חצר הכבד, כך למעלה יש כחות רוחני' דמלאכים הנק' קרביים ובני מעיים כמאמר דהע\"ה וכל קרבי את שם קדשו<sup data-n=\"1206\">43</sup> שמבדילים הפסולת המעורב בשפע האלקי מצד שבה\"כ מן הרוחני' שבו והרוחני' עולה למעלה מן הפרסא להוסיף אורות<sup data-n=\"1207\">44</sup> להיות תענוג אלקי לנשמות בגעה\"ע דבריאה ועוד למעלה מן הפרסא להוסיף אורות באצי' כו', והפסולת נדחה למטה להיות ממנו תענוגי עוה\"ז כו', וכח זה הבירור הוא מחמת הרקיע המבדיל שנותן כח בבחי' המלאכים הנ\"ל לברר ולהבדיל כו', נמצא שמה שלמעלה מן הפרסא מקבל תוס' אור וחיות ממה שנתברר מלמטה מן הפרסא כו' וד\"ל.\n<b>והנה</b> כדוגמת הרקיע למעלה שפועל ב' בחי' הא' השתלשלות יש מאין והב' להבדיל בבחי' השפע הנמשך בבחי' יש גופ[א] שיהי' נמשך הטוב לסט' דקדושה ופסולת השפע לחיצוני', וכ\"ז הוא מלמעלמ\"ט כן יש ב' בחי' אלו מלמטלמ\"ע בנה\"א ע\"ד העבודה. כי הנה ענין כח ההבדלה בנפש להבדיל בין טו\"ר הוא מ\"ש ראה נתתי לפניך<sup data-n=\"1208\">45</sup> את החיים ואת הטוב ואת המות ואת הרע ובחרת בחיים<sup data-n=\"1209\">46</sup> והיינו ע\"י שיתבונן בזה איך שכל חיות הגשם אינו חיות האמיתי רק הוא בחי' מות כי הוא בחי' פסולת דחיות הרוחני' האלקי' והעיקר הוא חיות הרוחני' האלקי' שהוא חיות האמיתי' באמת עד שאין ערוך לחיות הגשמי' לגבי' וכמאמר ר\"ע אם לעוברי רצונו כך<sup data-n=\"1210\">47</sup> לעושי רצונו עאכ\"ו, פי' אעפ\"י שראה תענוג עוה\"ז בכרך גדול בריבוי גדול מאוד עד שתופס מקום בבחי' [יש] התבונן מזה גופא שאם הפסולת יכול לתפוס מקום כ\"כ זה גופא מורה על גודל שפע הפנימי' האלקית שהיא לאין שיעור, וכן כאו\"א מישראל אעפ\"י שאין לו השגה כר\"ע יאמין באמונה שלמה איך שכל גודל וריבוי השפע הגשמי שרואה אינו רק פסולת שפע הרוחני' ואין ערוך לו לגבי שפע הרוחני וכמו שאמרו באחר מוטב דלידייני'<sup data-n=\"1211\">48</sup>",[["1205","*43","<b>והגשמתו כו'. . שיש. . לכח ההבדלה</b>: אג: והגשמת החיות כנ\"ל. . למטה. . לבחי' הבדלה."],["1206","43","<b>וכל קרבי את שם קדשו</b>: תהלים קג, א. ראה גם שע\"ת סט, א ובהנסמן במ\"מ לשם."],["1207","44","<b>מן הפרסא להוסיף אורות</b>: אג: ליתא. וכנראה נסרך משורה שלאח\"ז."],["1208","45","<b>ראה נתתי לפניך</b>: נצבים ל, טו [בדילוג]."],["1209","46","<b>ובחרת בחיים</b>: שם ל, יט."],["1210","47","<b>אם לעוברי רצונו כך</b>: ראה מכות בסופה. לקו\"ת בהעלותך לג, ד. שלח מז, א. לקמן מאמר ד\"ה במדרש איתא והצרוע תקצ\"ו על יד הערה 62."],["1211","48","<b>מוטב דלידייני'</b>: חגיגה טו, ב. ראה גם לקמן מאמר ד\"ה רפאיני הא' על יד הערה 24. מאמרי אדה\"ז תקס\"ה ח\"ב ע' תערב ובהנסמן במ\"מ לשם. תקס\"ז ע' שכ. מאמרי אדה\"א שמות ח\"ב ע' שטז. דברים ח\"א ע' נט."]]],[4801940371,"ולית[י] לעלמא דאת[י] כי אין ערוך לכל יסורי גיהנם אעפ\"י שהם גדולים הרבה מכל תענוגי עוה\"ז מ\"מ כדאי לקבלם בכדי לקבל אח\"כ אפי' שפע תענוגי אלקי שבגעה\"ת ומכ\"ש מה שלמעלה הימנו כו', וכאשר יתבונן בכל הנ\"ל אז ממילא יבחור בחיים האמיתיים ולא ירצה בחיים הגשמי', ונמצא שעושה הבדלה בעצמו להעביר ממנו הפסולת שהוא יניקת הרע ממנו ואז ממילא הטוב שבו הוא נקי ומבורר והיינו שאין לו רק רצון ולב אחד לאביו שבשמים כו' וד\"ל. וזהו ענין ונשב בגיא מול בית פעור כי גיא הוא בחי' נקודת השפלות שהוא מקור לכל בחי' גילוי אלקות והוא המנגד לקליפת בית פעור שהוא הגסות מקור כל רצון בתענוגי עוה\"ז, ולכן אז יהי' אח\"כ ועתה ישראל שמע אל החוקים כו' שהוא כל פרטי הבחי' דגילוי אלקות בנפש ע\"י תפילה ותומ\"צ.\n<b>והנה</b> להבין ענין קליפת פעור יובן בהקדם ענין הרע המבואר בפסוק שהוא גרוע יותר ממות<sup data-n=\"1212\">49</sup> כי ענין המות הוא עצם תענוגי עוה\"ז בלבד שהוא מותרות ופסולת ואינו תופס מקום כלל כמו צואה המונחת בבה\"כ אבל כשמדבק א\"ע לזה התענוג ורוצה בו בפנימיות (ולא מצד ההכרח בלבד) אז הוא עושה זה התענוג ליש ודבר והוא כדוגמת חזיר האוכל פסולת ומקבל חיות ממנו, וזהו יכרסמנה חזיר מיער<sup data-n=\"1213\">50</sup> (והיינו שהוא פוגם בנה\"א שנק' גופין<sup data-n=\"1214\">51</sup> כו') וזהו ג\"כ ענין קליפת פעור שה[י'] מתריזין<sup data-n=\"1215\">52</sup> [א\"ע] כו' והיינו אעפ\"י שידעו שהוא פסולת מ\"מ רצו לדבק א\"ע [בזה נמצא שעשו מהפסולת יש ודבר אז נעשה הפסולת בחי' רע שהוא גרוע ממות כו' וכן כל אחד ואחד כאשר רוצה לדבק א\"ע] בתענוגי עוה\"ז ח\"ו ורוצה לחיות כחי העכו\"ם<sup data-n=\"1216\">53</sup> ח\"ו אז הוא בבחי' רע גרוע ממות. ולזה העצה הוא ונשב בגיא, שהוא בחי' הביטול ושפלות הקרוי גיא כמו לע\"ל דכתיב ונגלה כבוד הוי'<sup data-n=\"1217\">54</sup>, אז כל גיא, שהוא בחי' ביטול ושפלות, ינשא<sup data-n=\"1218\">55</sup>, מצד אא\"ס שישכון בזה, וכל הר וגבעה, שהוא בחי' יש ישפלו, כי<sup data-n=\"1219\">56</sup> לא ישכון בזה אור הוי' כו' וד\"ל. והנה כ\"ז הוא בחי' הא' שיבחור בחי' האלקות אך מ\"מ רצונו לחיות<sup data-n=\"1220\">57</sup> בבחי' אור בכלי להיות שדביקותו והתקשרותו הוא לחיי האלקי' בקדושה שהוא למטה<sup data-n=\"1221\">58</sup> מן הפרסא שגם האור האלקי נק' יש מאין לגבי עצמות<sup data-n=\"1222\">59</sup> אור האלקי דאצי' שלמעלה מן הפרסא הנק' מ\"ע כנ\"ל בענין ונהר יוצא מעדן כו', אך ענין שאו מרום עיניכם וראו מי ברא [אלה] כו' היינו ענין התבוננות בשרש ומקור הפרסא העושה בחי' יש שזהו מבחי' מי שהוא בחי' שאינו מושג הנק' סוכ\"ע (כי מי נקרא דבר שאינו",[["1212","49","<b>הרע. . גרוע יותר ממות</b>: ראה גם בהדרושים שבריש המאמר."],["1213","50","<b>יכרסמנה חזיר מיער</b>: תהלים פ, יד."],["1214","51","<b>שנק' גופין</b>: אג: הנק' גפן."],["1215","52","<b>פעור שה[י'] מתריזין</b>: סנהדרין סד, א. וראה שם ס, ב."],["1216","53","<b>כחי העכו\"ם</b>: אג: בחיי הגוים."],["1217","54","<b>ונגלה כבוד הוי'</b>: ישעי' מ, ה."],["1218","55","<b>כל גיא. . ינשא</b>: ישעי' שם, ד."],["1219","56","<b>ישפלו כי</b>: אג: בפ\"ע כו'."],["1220","57","<b>לחיות</b>: שם: להיות."],["1221","58","<b>למטה</b>: שם: למעלה. ואולי נסרך משורה שלאח\"ז."],["1222","59","<b>עצמות</b>: שם: ליתא."]]],[4801940416,"מושג כמו שא' פרעה מי הוי'<sup data-n=\"1223\">60</sup> [אשר אשמע כו'] שהוא למעלה מהשגתו כו') וכמאמר מבטן מי יצא הקרח<sup data-n=\"1224\">61</sup> שבחי' הקרח שהוא בחי' הרקיע כמ\"ש לע\"ל רקיע כענין הקרח הנורא כו' שרשו מבטן מי שהוא [מבחי' מ\"י שהוא בחי'] סוכ\"ע שהוא [בחי'] אור שאינו נתפס בכלים דאצי' רק [הוא] בבחי' מקיף עליהם כו' (כי הכלים מגלים האור כמו אותיות ההסבר<sup data-n=\"1225\">62</sup> המגלים השכל לכל שומע ולא יוכל להתהוות מזה בחי' יש מאין רק [בחי'] ביטול עילה<sup data-n=\"1226\">63</sup> בעילתו כו' משא\"כ רקיע הוא כעין דוגמת המשל המסתיר על השכל לגמרי ששרשו ממקור השכל שלמעלה מגילוי אור השכל כן הרקיע שרשו ממקור האור הנק' בחי'<sup data-n=\"1227\">64</sup> מקיף, ולכן בכוחו להסתיר לגמרי שיהי' נראה הבריאה בבחי' יש כנ\"ל וד\"ל). וזהו ג\"כ שמלאכים אומרים קדוש<sup data-n=\"1228\">65</sup> וכן אומרים אי' מקום כבודו<sup data-n=\"1229\">66</sup> שזהו גילוי אוה\"מ<sup data-n=\"1230\">67</sup> עליהם דווקא מבחי' הרקיע מצד ששרשו ממקיפים כו', והנה כאשר מתבונן בזה הוא מרגיש איך שאין הרקיע מסתיר כלל לגבי מקורו הסוכ\"ע וממילא כולא קמי' כלא חשיב<sup data-n=\"1231\">68</sup> ואז ממילא הוא יוצא מגדר הכלים לגמרי להיות כלה שארי ולבבי<sup data-n=\"1232\">69</sup> להיות נכלל במהו\"ע אלקות ואינו רוצה אפי' חיים הרוחני' דגעה\"ע שנק' שמים<sup data-n=\"1233\">70</sup> כו', וכמא' מי לי בשמים<sup data-n=\"1234\">71</sup> כו'. וזהו ענין יציאת מצרים כי מצרים הוא מצר י\"ם<sup data-n=\"1235\">72</sup> שהוא ענין ההגבלה הנמשך בעולמות מצד<sup data-n=\"1236\">73</sup> י\"ם העליון שהוא כח<sup data-n=\"1237\">74</sup> המעלים ומסתיר על אלקות הנק' פרסא כנ\"ל ויציאת מצרים הוא כאשר יוצא מן ההסתר הזה [ו]לא לחפוץ בשום חיים המלובש בכלים רק ליכלל במהו\"ע כו' וד\"ל. הנה זהו כמו בחי' הב' ברקיע מלמעלמ\"ט לעשות יש מאין<sup data-n=\"1238\">75</sup> כן בחי' זאת בנה\"א לעשות מיש לאין כו' (וזהו גדולים מעשה צדיקים<sup data-n=\"1239\">76</sup> ממעשה שמים וארץ כו' וד\"ל). והנה זהו בחי' כללות גילוי אלקות בנפש אשר המקור לזה הוא נקודת השפלות שהוא בחי' ונשב בגיא כנ\"ל.",[["1223","60","<b>מי הוי'</b>: שמות ה, ב."],["1224","61","<b>מבטן מי יצא הקרח</b>: איוב לח, כט."],["1225","62","<b>ההסבר</b>: שם: הדבור."],["1226","63","<b>עילה</b>: שם: עלול."],["1227","64","<b>בחי'</b>: שם: כתר."],["1228","65","<b>שמלאכים אומרים קדוש</b>: ישעי' ו, ג."],["1229","66","<b>אי' מקום כבודו</b>: נוסח קדושת כתר. ראה זהר רע\"מ קדושים פב, א. תצא רפא, א."],["1230","67","<b>אוה\"מ</b>: אור המאיר."],["1231","68","<b>כולא קמי' כלא חשיב</b>: ראה זהר בהקדמה יא, ב. ראשית חכמה שער היראה פ\"א (ז, רע\"א). מאמרי אדה\"א דברים ח\"ב ע' תרנג."],["1232","69","<b>כלה שארי ולבבי</b>: תהלים עג, כו."],["1233","70","<b>דגעה\"ע שנק' שמים</b>: ראה גם לקמן מאמר ד\"ה וזכרתי הר\"ת על יד הערה 77. ביאור וזכרתי על יד הערה 31. תו\"ח תצוה ח\"ב שנו, ב ובהערה 24. סה\"מ תרכ\"ט ע' עב. ע' רו. סה\"מ תרל\"ח ע' מו. תרס\"ה ע' קמד. בהערה הבאה."],["1234","71","<b>מי לי בשמים</b>: תהלים עג, כה. ראה ספר המצות להצ\"צ קלח, א. תו\"ח תצוה ח\"ב שנו, ב. וש\"נ. לקמן מאמר ד\"ה לה\"ע ההפרש בין שליו\"ט תר\"ב ובהערה 83."],["1235","72","<b>מצרים הוא מצר י\"ם</b>: פע\"ח שער חה\"מ שכ\"א, פ\"ז. ראה גם סה\"מ תרכ\"ז ע' שסז. וש\"נ."],["1236","73","<b>מצד</b>: אג: מיצר."],["1237","74","<b>כח</b>: שם: מיצר."],["1238","75","<b>יש מאין</b>: שם: מיש לאין."],["1239","76","<b>גדולים מעשה צדיקים</b>: ראה כתובות ה, א. מאמרי אדה\"א ויקרא ח\"ב ע' תתי. וש\"נ. תו\"ח בראשית כה, ג. ובהערה 29."]]],[4801940457,"ועתה יש להקדים ענין ג' בחי' פרטות בענין העבודה והמשכת אלקות שהוא בחי' ק\"ש ותפלה ות\"ת ומה ההפרש בין זה לזה, מתחילה יש להבין ענין ההפרש בין ק\"ש לתפילה, כי לכאורה התפילה יותר גבוה מק\"ש ולכן תפילה צ\"ל בעמידה<sup data-n=\"1240\">77</sup> ובעי כוונה<sup data-n=\"1241\">78</sup> משא\"כ ק\"ש נק' צלותא דמיושב<sup data-n=\"1242\">79</sup> ולא בעי כוונה<sup data-n=\"1243\">80</sup> רק בפסוק ראשון<sup data-n=\"1244\">81</sup> וזה מורה שבתפילה מאיר יותר בחי' ביטול מבק\"ש אך אעפ\"כ חיובה מדאורייתא<sup data-n=\"1245\">82</sup> ואפי' מי שתורתו אומנתו<sup data-n=\"1246\">83</sup>, והתפילה חיובה רק מדרבנן<sup data-n=\"1247\">84</sup> ומי שתורתו אומנתו פטור<sup data-n=\"1248\">85</sup> לגמרי כו'. והנה יש להקדים ענין כי אל דעות הוי'<sup data-n=\"1249\">86</sup> שיש בחי' ד\"ע וד\"ת בחי' ד\"ת הוא בחי' הדעת שבנבראים שמרגישים א\"ע בחי' יש והאלקות לבחי' אין והיינו ל' העלם שאינו מושג וזהו מלמטלמ\"ע, אך מלמעלמ\"ט בחי' הדעת בבחי' אלקות למעלה הוא בחי' היש להיותו מקור האמיתי לכל בריאה יש מאין ולמטה הוא בחי' האין והיינו שהוא",[["1240","77","<b>תפילה צ\"ל בעמידה</b>: ראה גם ש\"א מא, ב ובהערה 32."],["1241","78","<b>תפילה. . ובעי כוונה</b>: ראה שו\"ע אדה\"ז הל' תפלה סצ\"ח. לקו\"ש אמור כרך כב ע' 117 ובהנסמן שם."],["1242","79","<b>ק\"ש נק' צלותא דמיושב</b>: ראה זהר במדבר קכ, ב. פינחס רכו, סע\"א. פע\"ח שער הק\"ש ש\"ח, פ\"ד. לקו\"ת שה\"ש מז, א."],["1243","80","<b>ק\"ש. . ולא בעי כוונה</b>: ראה ברכות יג, ב. שו\"ע אדה\"ז הל' ק\"ש ס\"ס, ס\"ה."],["1244","81","<b>ק\"ש. . כוונה רק בפסוק ראשון</b>: ראה הערה שלפנ\"ז."],["1245","82","<b>מבק\"ש. . חיובה מדאורייתא</b>: ראה שו\"ע אדה\"ז ריש הל' ק\"ש."],["1246","83","<b>ואפי' מי שתורתו אומנתו</b>: שבת יא, א. שה\"א עח, ב הערה 32."],["1247","84","<b>והתפילה. . מדרבנן</b>: ראה שו\"ע אדה\"ז הל' תפלה סק\"ו, ס\"ב. מאמרי אדה\"א בראשית ע' תקנב. וש\"נ. תו\"ח בא ח\"א קכ, ג. וש\"נ."],["1248","85","<b>ומי שתורתו אומנתו פטור</b>: ראה הערה 83."],["1249","86","<b>כי אל דעות הוי'</b>: שמו\"א ב, ג. ראה מאמרי אדה\"א ויקרא ח\"א ע' רסב. וש\"נ. תו\"ח בראשית יח, ג ובהערה 11. לעיל מאמר ד\"ה הפך ים תר\"א על יד הערה 7. לקמן ד\"ה סוד הוי' ליריאיו תר\"כ על יד הערה 7."]]],[4801940494,"כלא חשיב כו', וזהו ההפרש בין ק\"ש לתפילה כי הנה בק\"ש אע\"פ שהיא בחי' מס\"נ מ\"מ להיות מס\"נ נמשך מצד ההתבוננות שפועל הנפש בעצמו רצון למס\"נ ע\"י יגיעתו אינו אלא בחי' ד\"ת כו', וענין ההתבוננות הוא בתיבת שמ\"ע שם ע' והיינו שכל השפעות הן בסט' דקדושה הוא במספר ע' כמו בחי' ע' נפש לבית יעקב<sup data-n=\"1250\">88</sup> והן בסט' דקליפה הם ג\"כ במספר ע' כמ\"ש יצב גבולות עמים למספר בנ\"י<sup data-n=\"1251\">89</sup>, והיינו מחמת שנמשך בבחי' ז\"מ<sup data-n=\"1252\">87</sup> עליונות כמ\"ש כי אמרתי עולם חסד יבנה<sup data-n=\"1253\">90</sup> ששרש מקור העולמות הוא מבחי' החסד, אך גם בחי' החסד אינו בבחי' מקור עדיין להשתלשלות העולמות עד שמתלבש בבחי' אותיות דמל'<sup data-n=\"1254\">*91</sup> דאצי' כמאמר אימתי גדול<sup data-n=\"1255\">91</sup> כשהוא בעיר אלקינו כו', וזהו בחי' ז' מדות מחסד עד המל' שנק' ז' ימי הבנין להיותם מקור בנין העולמות כו', וזהו שמע שם ע' והיינו שכל בחי' התפשטות העולמות אינו רק הארה בעלמא ממקורם שהוא בחי' המדות",[["1250","88","<b>ע' נפש לבית יעקב</b>: ויגש מו, כז."],["1251","89","<b>יצב גבולות עמים למספר בנ\"י</b>: האזינו לב, ח."],["1252","87","<b>שמ\"ע שם ע'. . ז\"מ</b>: זהר רע\"מ פינחס רלו, ב. ראה גם מאמרי אדה\"א ויקרא ח\"ב ע' תשמא. וש\"נ. תו\"ח ויצא קע, ב ובהערה 27. שע\"ת קד, ד. קכב, ג. סה\"מ תרל\"ח ס\"ע רכא ואילך. וש\"נ."],["1253","90","<b>כי אמרתי עולם חסד יבנה</b>: תהלים פט, ג. ראה ע\"ח שער המלכים שי\"א, פ\"ו. פלח הרמון ח\"ש עד, ב ואילך. לעיל מאמר ד\"ה אדם כי יקריב הב' על יד הערה 68. ד\"ה והניף ידו תר\"י על יד הערה 32. ד\"ה להבין ההפרש בין קי\"ס על יד הערה 18. לקמן ד\"ה מנין שקושרין לשון של זהורית על יד הערה 40. ד\"ה לה\"ע ההפרש בין שליו\"ט תר\"ב על יד הערה 34. ד\"ה וספרתם הה' על יד הערה 19. ד\"ה את שבתותי תרי\"ב על יד הערה 22."],["1254","*91","<b>החסד אינו בבחי' מקור. . אותיות דמל'</b>: ראה גם לקמן מאמר ד\"ה לה\"ע ההפרש בין שליו\"ט תר\"ב ובהערה *36."],["1255","91","<b>אימתי גדול</b>: ראה זהר פקודי רלה, א. ויקרא ה, א. מאמרי אדה\"א נ\"ך ע' פ. וש\"נ. סה\"מ תרכ\"ז ס\"ע ר. וש\"נ. פלח הרמון שם."]]],[4801940526,"דאצי' (כי שם בחי' הוא<sup data-n=\"1256\">*93</sup> הארה<sup data-n=\"1257\">92</sup> כו'), ונמצא שאין ערוך לכל ההשתלשלות לגבי מקורם האלקי וכמא' לך הוי' הגדולה<sup data-n=\"1258\">93</sup> כי גדולה בה'<sup data-n=\"1259\">94</sup> הוא התפשטות העולמות ובטילים למקורם שהוא בחי' המדות דאצי' הנק' הוי' כו' וד\"ל.\n<b>והנה</b> זאת הוא התבוננות דנה\"ט אך אח\"כ בא לבחי' התבוננות יותר פנימי' מצד נשמתו האלקי' שנק' ישראל שעלה במח' ומחמת זה מרגיש בבחי' הוי' אלקינו והיינו איך שהוא מחדש בכל עת ורגע מאין ליש בכל העולמות הנבראים בכל עת ורגע כו' (וזהו ענין יחוד או\"א בל' הקבלה שנגלה מצד הנשמה דווקא כו'), ואזי נעשה אצלו מס\"נ באחד<sup data-n=\"1260\">95</sup>. והנה גם היא ד\"ת מצד שבא מצד ההתבוננות הוא לפ\"ע הכלי הנפש כו', וכן<sup data-n=\"1261\">96</sup> אפי' אהבה דבכל מאדך נק' מאד שלך<sup data-n=\"1262\">97</sup> כו'), וזהו ענין הק\"ש, אך ענין התפילה הוא הארת ד\"ע והיינו שמאיר בנפש הציור איך שהיא קמי' כו' ולכן ענין ההשתחוואות הוא בתפי' דוקא כי",[["1256","*93","<b>בחי' הוא</b>: אוצ\"ל: הוא בחי'."],["1257","92","<b>שם. . הארה</b>: ראה גם תו\"ח וארא ח\"א סט, ב ובהערות 1. 13."],["1258","93","<b>לך הוי' הגדולה</b>: דהי\"א כט, יא."],["1259","94","<b>גדולה בה'</b>: ראה גם מאמרי אדה\"א ויקרא ח\"א ס\"ע רכד ואילך. וש\"נ. במדבר ח\"ב ע' שס וע' תקעה ואילך."],["1260","95","<b>מס\"נ באחד</b>: ראה זהר רע\"מ משפטים קיט, א. צו לג, א. מאמרי אדה\"א דברים ח\"ב ע' תו. וש\"נ. שמות ח\"א ע' רעח ואילך. הנחות תקע\"ז ע' שא."],["1261","96","<b>וכן</b>: אוצ\"ל: (וכן."],["1262","97","<b>דבכל מאדך נק' מאד שלך</b>: ראה מאמרי אדה\"א קונטרסים — לקו\"ב — ס\"ע קיט ואילך. וש\"נ. דרושי חתונה ח\"א ע' יג. תו\"ח וארא ח\"א עט, ג. בשלח קמב, ד. סה\"מ תרכ\"ט ע' קצח בשולי היריעה."]]],[4801940553,"ההשתחוואה הוא בבואו לפני המלך דווקא בקרוב שאז הוא בטל ממציאותו עד שאינו מרגיש הביטול גופא משא\"כ בק\"ש הוא רק ביטול היש לאין בלבד כו' וד\"ל.\n<b>והנה</b> זהו היתרון בתפלה מבק\"ש, ועתה יש להבין היתרון שבק\"ש עד שחיובה מדאורייתא, והיינו מפני שעיקר פנימיות הרצון האלקי' היא בבחי' ביטול היש מצד מעה\"ת<sup data-n=\"1263\">98</sup> דווקא שיעשו בעצמם היפוך החשך לאור ובחי' זאת הוא המעלה מ\"ן דוקא לעורר בחי' אלקות מבחי' הרוממות שיהי' נמשך למטה וכמשל צפור המדברת<sup data-n=\"1264\">99</sup> דווקא שפועל הפנת המלך אליו מן הרוממות שלו ואעפ\"י שהשרים ועבדו דיבורים<sup data-n=\"1265\">100</sup> יותר נאה לא יפעלו השפלת הרוממות להיות נפנה לקוראו והיינו מצד שהוא דבר מחודש שבע\"ח ידבר כו', כן למעלה הביטול דנר\"ן אעפ\"י שהוא בחי' חי המדבר היא עיקר ההעלאה וממילא יהי' ההמשכה דש\"ע שהיא בחי' אדם המדבר (שהוא ענין הביטול שבעצם הנשמה הנק' חי' יחידה כו' וד\"ל).\n<b>ועתה</b> יש להבין מ\"מ מי שתורתו אומנתו פטור מן התפילה ואעפ\"כ מפסיק לק\"ש והענין הוא",[["1263","98","<b>מעה\"ת</b>: מעשה התחתונים."],["1264","99","<b>צפור המדברת</b>: מובא בלקו\"ת במדבר כ, א: וכמ\"ש בלק\"א בשם המגיד נ\"ע. ראה גם מאמרי אדה\"ז על פרשיות התורה ח\"א ע' רפח. תו\"ח וישלח קצ, א ובהערה 5. שה\"א עט, א. סה\"מ תרכ\"ז ע' נא וע' רצג־ תרכ\"ט ע' ג־ תרל\"ג ח\"ב ע' תקיד־ תרל\"ב ח\"א ע' קסט ובהנסמן בהנ\"ל. — באוה\"ת בשלח ע' שצא: ”שנמצא מבטא לעוף הזרזיר והפעפוגאי\" ולהעיר ממאמרי אדה\"ז תקס\"ב ח\"ב ע' תלה: ”העוף (הנק' פייגל) לדבר\"."],["1265","100","<b>ועבדו דיבורים</b>: אולי צ\"ל: ועבדיו דיבורם."]]],[4801940571,"שמעלת התורה גדלה מתפילה כי הנה ענין לימוד התורה הוא ג\"כ ע\"י ביטול במציאות עד שאינו מהות בפ\"ע רק דבר ה' מדבר בפיו וכמאמר ודברי אשר שמתי בפיך<sup data-n=\"1266\">101</sup> אך הביטול הוא במדריגה יותר גבוה כי הנה ידוע שהתורה קדמה לעולם אלפים שנה<sup data-n=\"1267\">102</sup> אאלפך חכמה אאלפך בינה<sup data-n=\"1268\">103</sup> משא\"כ שרש ומקור העולמות הוא מבחי' החסד כנ\"ל. וההפרש בין חכמה לחסד הוא ע\"ד דוגמא באדם למטה שהמדות חו\"ג אינם שייכים רק לזולתו הנפרד כשיש מי לפעול עליו השפעת החסד כו', משא\"כ החכמה יתכן יותר בשעה שהוא לעצמו<sup data-n=\"1269\">104</sup> שאז הוא יכול להשכיל השכלות עמוקות דווקא. כן למעלה בחי' חו\"ב נק' אור המאיר מא\"ס אך האור הוא לעצמו נבדל מהיות מקור להשתלשלות משא\"כ המדות דחו\"ב הם מקור לעולם הנפרד, ועם זה יובן ההפרש בין תפלה לתורה כי הנה התפילה נק' חיי שעה<sup data-n=\"1270\">105</sup> שהיא המשכה מבחי' המדות דאצי' שהם למעלה מהזמן בבחי' הזמן דמל'<sup data-n=\"1271\">106</sup> הנק' שעה<sup data-n=\"1272\">107</sup> (כידוע דעבר הוה",[["1266","101","<b>ודברי אשר שמתי בפיך</b>: ישעי' נט, כא."],["1267","102","<b>שהתורה. . אלפים שנה</b>: ראה שבת פח, ב וברש\"י שם. מדרש תהלים צ, ד. הנסמן במאמרי אדה\"א דברים ח\"א ע' כ."],["1268","103","<b>אאלפך חכמה אאלפך בינה</b>: ע\"פ איוב לג, ג. שבת קד, א."],["1269","104","<b>שהמדות. . לזולתו. . החכמה. . לעצמו</b>: ראה גם אוצרות חיים בתחלתו. הובא בלקו\"ת מסעי צג, רע\"א. אוה\"ת שה\"ש כרך ב ע' תקנ וע' תקנה. סה\"מ תרכ\"ו ע' רכג. תרכ\"ח ע' ד ואילך. תרכ\"ט ע' ט. תר\"ל ע' רסז. תרל\"ג ח\"ב ע' תקמא. תרל\"ד ס\"ע נד ואילך. לקמן מאמר ד\"ה לה\"ע ההפרש בין שליו\"ט תר\"ב על יד הערה 29."],["1270","105","<b>התפילה נק' חיי שעה</b>: שבת י, א. ראה סידור שער הק\"ש עה, א ואילך."],["1271","106","<b>הזמן דמל'</b>: ראה שער היחוד והאמונה פ\"ז. הנסמן במאמרי אדה\"א דברים ח\"א ע' קלה. תו\"ח בשלח ח\"א רלד, א. וש\"נ. לקמן מאמר ד\"ה מנין שקושרין לשון של זהורית ובהערה 175."],["1272","107","<b>דמל' הנק' שעה</b>: פע\"ח שער תפילות ר\"ה שכ\"ה, פ\"ג [ירושלים תש\"מ תקעא, א]."]]],[4801940586,"ועתיד התחלקותם זמ\"ז הוא בבחי' המל' מלך מלך ימלוך<sup data-n=\"1273\">108</sup> כו' משא\"כ בשם הוי' דז\"א<sup data-n=\"1274\">109</sup> הי' הוה ויהי' כא'<sup data-n=\"1275\">110</sup> כו'), ונמצא שגם בתפילה מאיר הביטול כמ\"ש<sup data-n=\"1276\">111</sup> קמי' אך אינו מאיר רק הביטול כמ\"ש בבחי' המדות דאצי' משא\"כ בתו' נק' חיי עולם<sup data-n=\"1277\">112</sup> שהוא בחי' ההמשכה מבחי' חו\"ב שקדמה לעולם לבחי' עולם שהוא בחי' ז\"א, ועוד זאת שהגילוי הזה נמשך גם למטה מהפרסא כמו למעלה בלי שינוי כלל (משא\"כ בתפילה כמבואר במאמר דיפה שיחתן<sup data-n=\"1278\">113</sup> כו'), ונמצא מאיר בנשמה הביטול כמ\"ש קמי' בבחי' החו\"ב שלמעלה מבחי' המדות ולכן מי שתורתו אומנתו שהוא מלשון אומן<sup data-n=\"1279\">114</sup> להמשיך המוחין דחו\"ב בז\"א וכן למטה בנפשו הוא פטור מהתפילה כי בכלל מאתיים מנה<sup data-n=\"1280\">115</sup> וכו' וד\"ל.\n<b>אך</b> אעפ\"כ הוא מפסיק לק\"ש הענין יובן בהקדים את החיים ואת הטוב<sup data-n=\"1281\">116</sup> כמו שבחי' רע גרוע ממות כן לעו\"ז בסט' דקדושה בחי' טוב הוא למעלה מחיים כמ\"ש כי טוב חסדיך מחיים<sup data-n=\"1282\">117</sup> שהוא רב חסד שהוא למעלה מחיים דחכמה כו', וכמ\"ש והבדילה הפרכת<sup data-n=\"1283\">118</sup> בין הקדש דחכמה ובין קה\"ק",[["1273","108","<b>מלך מלך ימלוך</b>: ראה זהר בראשית לד, א. אוה\"ת סידור ע' פג ואילך."],["1274","109","<b>הוי' דז\"א</b>: זהר אד\"ר נשא קכט, א."],["1275","110","<b>הוי'. . הי' הוה ויהי' כא'</b>: ראה שער היחוד והאמונה פ\"ז. תו\"ח מקץ ריט, ד הערה 62."],["1276","111","<b>כמ\"ש</b>: כמו שהוא."],["1277","112","<b>בתו' נק' חיי עולם</b>: שבת י, א."],["1278","113","<b>במאמר דיפה שיחתן</b>: ראה פלח הרמון ח\"ש עד, ד ואילך."],["1279","114","<b>אומנתו שהוא מלשון אומן</b>: ראה גם בנו\"א כאן לקמן על יד ההערה 144 ויהי אומן."],["1280","115","<b>בכלל מאתיים מנה</b>: ב\"ק עד, א."],["1281","116","<b>את החיים ואת הטוב</b>: נסמן לעיל בהערה 45."],["1282","117","<b>כי טוב חסדך מחיים</b>: תהלים סג, ד."],["1283","118","<b>והבדילה הפרכת</b>: תרומה כו, לג [בדילוג]."]]],[4801940597,"שהוא בחי' חסד שבכתר שלמעלה מן החכמה ויש פרסא מפסיק בין זל\"ז כמו שיש פרסא מפסיק בין אצי' לבי\"ע כו', נמצא שאין ערוך לחיים לגבי הטוב (וזהו שבמאמר יהי רקיע פי' יהי'<sup data-n=\"1284\">*119</sup> רקיע כו' ויעש אלקים את הרקיע<sup data-n=\"1285\">119</sup> כו' ולא כמו במאמר יהי אור שכתיב ויהי אור<sup data-n=\"1286\">120</sup> ולא כתיב עליו עשיי' בפ\"ע והיינו מטעם שיש שני רקיעים בין כתר לחכמה ובין אצי' לבי\"ע כו' וד\"ל).\n<b>וזהו</b> ענין יפה שעה אחת<sup data-n=\"1287\">121</sup> בתשומע\"ט שמגיע בקה\"ק בכתר (כידוע דתרי\"ג מצות דאורייתא וז' דרבנן הוא בחי' תר\"ך<sup data-n=\"1288\">122</sup> משא\"כ בחו\"ב אינו נמשך רק בחי' יש<sup data-n=\"1289\">123</sup>, חצי התחתון דכתר<sup data-n=\"1290\">124</sup> כו') מכל חיי העוה\"ב שהוא בחי' גילוי אור בחו\"ב שהוא בחי' תורה אור<sup data-n=\"1291\">125</sup> כו', וזהו ענין מה שנאמר במשה כי טוב בט' רבתי<sup data-n=\"1292\">126</sup> להיות מקור התורה הוא למעלה מתורה עצמה, וכן בכללות נש\"י מצד אהבה דבכל מאדיך שבק\"ש מעוררים בחי' הטוב הנ\"ל שלמעלה מן החכמה להשפיע חדשות בחכמה דתורה ונעשו משפיעים לתורה כמ\"ש מורשה כו' מאורסה<sup data-n=\"1293\">127</sup>, והיינו שבמאד שלהם אעפ\"י",[["1284","*119","<b>פי' יהי'</b>: אוצ\"ל: כתי' יהי."],["1285","119","<b>ויעש אלקים את הרקיע</b>: בראשית א, ז."],["1286","120","<b>יהי אור. . ויהי אור</b>: בראשית א, ג."],["1287","121","<b>יפה שעה אחת</b>: ראה אבות פ\"ד, מי\"ז."],["1288","122","<b>דתרי\"ג. . וז'. . תר\"ך</b>: ראה לקמן ד\"ה אשה כי תזריע תרכ\"ג בהערות 51-53."],["1289","123","<b>בחו\"ב. . יש</b>: ראה משלי ד, ה. פע\"ח שער תפילות ר\"ה שכ\"ה, פ\"ג [ירושלים תש\"מ תקעא סע\"א]. תו\"ח שמות ח\"א לג, סע\"ג ובהערה 324."],["1290","124","<b>יש חצי התחתון דכתר</b>: ראה גם לקמן ד\"ה את שבתותי תרי\"ב ובהערה 78."],["1291","125","<b>תורה אור</b>: משלי ו, כג."],["1292","126","<b>במשה. . בט' רבתי</b>: שמות ב, ב ובמנחת שי שם. ראה גם תו\"ח שמות ח\"א מג, ד. וש\"נ."],["1293","127","<b>מורשה כו' מאורסה</b>: ברכה לג, ד. ברכות נז, א."]]],[4801940603,"שאינו בלי גבול אמיתי מעוררים מאד העליון בלי גבול אמיתי שלמעלה מן החכמה מטעם הנ\"ל להיות פנימי' הרצון הוא לזה וכמשל צפור המדברת הנ\"ל. ולכן אפי' מי שתורתו אומנתו מפסיק לק\"ש מצד שע\"י הק\"ש ממשיך אוא\"ס ב\"ה בתורה עצמה כו' וד\"ל.\n<b>ומעתה</b> י\"ל ענין המאמר דר' חייא רבא מיומא לא איכוונין בתפלה מצד שהי' תורתו אומנתו לא האריך בתפילה יומא חד בעית לכווני' כו', יובן בהקדים ענין מט\"ט קושר כתרים לקונו<sup data-n=\"1294\">128</sup> מתפלותיהן של ישראל, כי הנה הכתר עשוי מאבנים שמזככין אותם<sup data-n=\"1295\">129</sup> עד שנעשו אבנים טובות מאירים ואז עושים מהם כתר למלך כן למעלה עשיית הכתר הוא מה שאומרים יה\"ר בתפילה לעורר ר\"ר כדי לסלוח עוונות וחטאים שלא כפי משפט התורה דחכמה ונק' כתר בראשו של הקב\"ה ונעשו זה ע\"י אותיות התפילה של ישראל שנתפשטו מגשמיותן ומזדככין ע\"י המלאכים ע\"י דגפיף ונשיק לה<sup data-n=\"1296\">130</sup>, ואח\"כ עולים למעלה מן המלאכים ומעוררים המשכת הרצון להיות מחוק ברחמיך הרבים<sup data-n=\"1297\">131</sup> כו', והנה שרו של עולם היצירה המעלה אותיות התפילה וגם",[["1294","128","<b>מט\"ט קושר כתרים לקונו</b>: ראה זהר בראשית לז, ב. סה\"מ תש\"ח ע' 202 בהערה."],["1295","129","<b>הכתר עשוי מאבנים שמזככין אותם</b>: ראה תו\"א בראשית ח, ב."],["1296","130","<b>אותיות. . דגפיף ונשיק לה</b>: ראה זהר בראשית כג, ב. ויקהל רא, ב. סידור שער החנוכה רעג, א ואילך. מאמרי אדה\"א שמות ח\"א ע' רמז. וש\"נ. סה\"מ תרכ\"ז ר\"ע שצז. תרכ\"ט ע' ג. וש\"נ. ע' קז. תרל\"ה ח\"א ס\"ע רז ואילך."],["1297","131","<b>מחוק ברחמיך הרבים</b>: נוסח רבש\"ע בק\"ש שעהמ\"ט."]]],[4801940609,"ההמשכה שע\"י התפילה נמשך ע\"י נק' ריש גלותא<sup data-n=\"1298\">132</sup> להיות שבזמן הגלות דווקא נעשה ע\"י היחוד משא\"כ בימי משה לא רצה במלאך ואמר אם אין פניך הולכים<sup data-n=\"1299\">133</sup> כו' וכן בזמן הבית הי' נעשה היחוד שהוא בחי' העלאה והמשכה שלא ע\"י המלאכים כו', והנה המעלה כוונת התפילה שהוא מט\"ט דבריאה<sup data-n=\"1300\">134</sup> נק' אלקפטא<sup data-n=\"1301\">135</sup> כו' וזהו שיש ספק אצלו איזה ענין שרשו למעלה ביותר אם כונת התפילה או אותיות התפילה ובאמת שיש יתרון בזה מה שאין בזה כי למ\"ד שמים קדמו<sup data-n=\"1302\">136</sup> שרש כוונת התפילה למעלה יותר ולמ\"ד ארץ קדמה<sup data-n=\"1303\">137</sup> אותיות התפילה שרשן יותר נעלה ובאמת שניהם אמת<sup data-n=\"1304\">138</sup> וכמ\"ש במ\"א וד\"ל.",[["1298","132","<b>שרו של עולם היצירה. . ריש גלותא</b>: באוה\"ת כאן ע' קנה בעה\"מ. ראה עשרה מאמרות מאמר אם כל חי ח\"א (סכ\"ט) ס\"ל."],["1299","133","<b>אם אין פניך הולכים</b>: תשא לג, טו."],["1300","134","<b>מט\"ט דבריאה</b>: ראה גם מאמרי אדה\"א נ\"ך ע' שלד. וש\"נ. תו\"ח בא ח\"א קכג, ג הערה 404."],["1301","135","<b>מט\"ט. . אלקפטא</b>: נסמן בהערה 132 [ושם: אכתריאל]."],["1302","136","<b>שמים קדמו</b>: חגיגה יב, א."],["1303","137","<b>ארץ קדמה</b>: חגיגה שם. ראה סידור שבהערה 130."],["1304","138","<b>שניהם אמת</b>: ראה גם אוה\"ת כאן ע' קנה."]]],[4801940093,"<b>יום א' פ' תזריע שייך לפ' שמיני שנת רחבות</b>\n<b>להבדיל</b> בין הטמא ובין<sup data-n=\"1305\">1</sup> הטהור<sup data-n=\"1306\">2</sup> כו', ואיתא במדרש (ויקרא פי\"ג) א\"ר תנחום בר חנילאי משל לרופא שנכנס לבקר שני חולים א' לחיים וא' למיתה אמר לזה של חיים זה תאכל וזה לא תאכל, ושאינו לחיים אמר כל דבעי הבו לי', כך אומה\"ע שאינן לחיי העוה\"ב כתיב בהם כירק עשב נתתי לכם את כל<sup data-n=\"1307\">3</sup>, אבל ישראל שהם לחיי עוה\"ב זאת הבהמה אשר תאכלו<sup data-n=\"1308\">4</sup> כו', ולהבין למה ענין הבדלה במאכלות אסורות דייקא מביאין לחיי העוה\"ב הלא כל המצות מביאים לחיי העוה\"ב כמאמר כל ישראל יש להם חלק לעוה\"ב<sup data-n=\"1309\">5</sup> וכמאמר ועמך כולם צדיקים<sup data-n=\"1310\">6</sup> כו' ירשו ארץ כו' וצדיקים הם המקיימים תומ\"צ כו'. אך הענין יובן בהקדם עוד ענין הדוגמא לזה והוא מה שנמצא במדרש (ויקרא פ' כ\"א) ע\"פ בזאת יבא אהרן<sup data-n=\"1311\">7</sup> כו' ר\"י פתר קרא<sup data-n=\"1312\">8</sup> בכה\"ג בכניסתו לבית קדה\"ק חבילות חבילות של מצות יש בידו בזכות התורה וזאת התורה<sup data-n=\"1313\">9</sup>, בזכות מילה זאת בריתי<sup data-n=\"1314\">10</sup> כו' יעו\"ש. ולהבין מה שייכות מצות מילה שעי\"ז יכנס כה\"ג לבית קדה\"ק, יש להקדים ענין למנצח על השמינית<sup data-n=\"1315\">11</sup> על מילה שניתנה בשמיני, ולכאורה למה השבח על שניתנה בשמיני וכי אם היתה ניתנה בשביעי לא היתה מצוה, אך הענין הוא שאם היתה ניתנה בשביעי לא היתה מעורר ממקום גבוה כ\"כ, אך עכשיו כאשר ניתנה בשמיני מעוררת במקום גבוה יותר הרבה ולכן יש ע\"ז שבח בפ\"ע כמשי\"ת, ויש להקדים ענין והבדילה הפרוכת<sup data-n=\"1316\">12</sup> בין הקדש ובין קדה\"ק כו' שפירושו ע\"ד הקבלה שיש פרסא מפסיק בין ז\"א הנק' קדש ובין בינה הנק' קדה\"ק (כי עיקר קדה\"ק הוא בחי' עתיקא אך התגלות עתיק הוא בבינה<sup data-n=\"1317\">14</sup> לכן גם הבינה נק' קדה\"ק כו' וד\"ל)<sup data-n=\"1318\">13</sup>, (... וכידוע בענין רקיע על ראשי החיות<sup data-n=\"1319\">15</sup> כו' דקאי על<sup data-n=\"1320\">16</sup> חיוון עילאין שהם בחי' חג\"ת דז\"א והפרסא נמשך מת\"ת",[["1305","1","<b>להבדיל בין הטמא ובין הטהור</b>: מאמר זה הוא הנחת ר' הלל מדרוש כ\"ק אדמו\"ר הצ\"צ.\nמאמר זה הובא במאמר ד\"ה חכלילי עינים תרי\"ז שנדפס בפלח הרמון ויחי קלד, ד."],["1306","2","<b>להבדיל בין הטמא ובין הטהור</b>: שמיני יא, מז."],["1307","3","<b>כירק עשב נתתי לכם את כל</b>: נח ט, ג."],["1308","4","<b>זאת הבהמה אשר תאכלו</b>: פ' ראה יד, ד."],["1309","5","<b>כל ישראל יש להם חלק לעוה\"ב</b>: סנהדרין ר\"פ חלק (צ, א)."],["1310","6","<b>ועמך כולם צדיקים</b>: ישעי' ס, כא."],["1311","7","<b>בזאת יבא אהרן</b>: אחרי טז, ג."],["1312","8","<b>קרא</b>: במדרש שם: קריא."],["1313","9","<b>וזאת התורה</b>: ואתחנן ד, מד."],["1314","10","<b>זאת בריתי</b>: לך יז, י."],["1315","11","<b>למנצח על השמינית</b>: תהלים יב, א. ראה מנחות מג, ב."],["1316","12","<b>והבדילה הפרוכת</b>: תרומה כו, לג [ושם: והבדילה הפרוכת לכם]. ראה גם אוה\"ת על ענינים ע' קפ."],["1317","14","<b>התגלות עתיק הוא בבינה</b>: מובא בכ\"מ בשם הע\"ח — ראה תו\"ח לך פא, ב ואילך. הנסמן במאמרי אדה\"א הנחות תקע\"ז ע' ד. ביאוה\"ז להצ\"צ אחרי ע' שסד."],["1318","13","<b>(כי. . וד\"ל)</b>: ב: כבפנים. ראה הנרשם לקמן (ברשימת הכת\"י כאן) אודות בוך א."],["1319","15","<b>רקיע על ראשי החיות</b>: יחזקאל א, כב. ראה לקו\"ת תזריע כב, ד."],["1320","16","<b>על</b>: ב: גם על."]]],[4801940158,"דאימא כידוע בענין מבטן מי יצא הקרח<sup data-n=\"1321\">17</sup> כו' כדוגמת מיצר הגרון המפסיק בין המוח אל הלב כו' וד\"ל)<sup data-n=\"1322\">18</sup>.\n<b>ולהבין</b> ביאור הדברים ע\"ד ההסבר גם להבין איך נק' הז\"א קדש דהלא מבואר כ\"פ בכתבי החסידו' דז\"א נק' קדוש בוי\"ו וקדש הוא בחי' פרצוף אבא כו'<sup data-n=\"1323\">19</sup> הנה ידוע שיש בחי' סובב וממלא שנק' קוב\"ה ושכינתי'<sup data-n=\"1324\">20</sup>, ויובן עד\"ד מבשרי אחזה<sup data-n=\"1325\">21</sup> בחיות הנפש בגוף שיש בו שני בחי' הא' חיות הבא בדרך התלבשות שהוא מזיגת חיות הנפש באברים בכאו\"א לפי מזגו ותכונתו שיש בזה חילוקי מדריגות במוח החיות רוחני יותר ובלב נתגשם קצת עד שבאברי המעשה הוא מאיר בהגשמה יותר להיות ממנו הילוך גשמי ותנועה גשמי', אך כ\"ז הוא זיו והתפשטות מן הנפש בלבד ולא עצמי' ומהות הנפש כי עצמי' ומהות הנפש לא יתחלק לחלקים רק הוא שורה בהעלם בכל אברי הגוף בהשוואה כו' וזהו בחי' הב' בנפש כו', כן עד\"ז למעלה בענין הקב\"ה ממלא את כל העולם יש בזה שני בחי' הא' בחי' ממכ\"ע שהוא בחי' מלכותך מכ\"ע<sup data-n=\"1326\">22</sup> כו' שאינו רק זיו והתפשטות מעצמו' אלקות שהוא בחי' עצמו' המדות דאצי' ובחי' חיות זה בא<sup data-n=\"1327\">23</sup> בחילוקי מדריגות בכל עולם לפ\"ע דהיינו בעולם הבריאה נמשך גילוי החיות ביותר ולכן היש דבריאה הוא בבחי' ביטול יותר כו' וכמ\"ש שרפים עומדים<sup data-n=\"1328\">24</sup> כו', וביצירה נתמעט החיות יותר מצד שיש עוד פרסא המפסיק בין בריאה ליצירה<sup data-n=\"1329\">25</sup> נוסף על הפרסא שמפסיק בין אצי' לבריאה<sup data-n=\"1330\">26</sup>, ולכן היש דיצי' הוא יותר מורגש, ולכן מתפעלים ברעש<sup data-n=\"1331\">27</sup> כו' עד שבעשי' נתמעט החיות לגמרי ובחי' זאת נק' שכינה, אך בחי' הב' הוא בחי' עצמות אלקות שהוא בחי' המדות דאצי' עצמם הם נמצאים בבחי' העלם בג' עולמות בי\"ע לכולם בהשוואה כו', ונק' סוכ\"ע ואין הכוונה סובב ומקיף מלמעלה<sup data-n=\"1332\">28</sup> דלית אתר פנוי מיני'<sup data-n=\"1333\">29</sup> רק שהוא בהשוואה כו' ובחי' זאת נק' קוב\"ה כי קדוש הוא מובדל שאינו מתגלה בעולמות בי\"ע אפי' בעולם היותר עליון כי לית מתב\"כ<sup data-n=\"1334\">30</sup> רק שורה בהעלם כנ\"ל. אך כ\"ז הוא קדוש בוי\"ו כי הוי\"ו מורה על",[["1321","17","<b>מבטן מי יצא הקרח</b>: איוב לח, כט. ראה סידור שחרית סד, א. שער חג המצות רצא, ב."],["1322","18","<b>וד\"ל)</b>: ב: וד\"ל. ראה לעיל הערה 13."],["1323","19","<b>גם להבין. . כו'</b>: ניתוסף ע\"פ ב."],["1324","20","<b>סובב וממלא שנק' קוב\"ה ושכינתי'</b>: ראה תניא פמ\"א (נח, א)."],["1325","21","<b>עד\"ד </b>[ב: ע\"ד דוגמא]<b> מבשרי אחזה</b>: ע\"פ איוב יט, כו."],["1326","22","<b>מלכותך מכ\"ע</b>: תהלים קמה, יג."],["1327","23","<b>שאינו רק. . בא</b>: ניתוסף ע\"פ ב. ובכת\"י זה: שמאיר."],["1328","24","<b>שרפים עומדים</b>: ישעי' ו, ב."],["1329","25","<b>פרסא המפסיק בין בריאה ליצירה</b>: ראה ע\"ח שער דרושי אבי\"ע שמ\"ב, פי\"ג. פי\"ד. תו\"א לך יב, סע\"ג."],["1330","26","<b>הפרסא. . אצי' לבריאה</b>: ראה ע\"ח שער דרושי נקודות ש\"ח, פ\"ב. לקוטי הש\"ס להאריז\"ל חולין ס, ב ד\"ה לכי ומעטי (כ, ב). הנסמן במאמרי אדה\"א דברים ח\"ג ע' תתפא. וראה גם לקמן מאמר ד\"ה וזכרתי הר\"ת על יד הערה 29 ואילך."],["1331","27","<b>מתפעלים ברעש</b>: ברכת יוצר."],["1332","28","<b>ואין הכוונה סובב ומקיף מלמעלה</b>: ראה תניא פמ\"ח סז, סע\"ב ובמ\"מ הגהות והע\"ק לשם. לקמן מאמר ד\"ה גדולה מילה תר\"כ ובהערה 64."],["1333","29","<b>דלית אתר פנוי מיני'</b>: ראה ת\"ז תנ\"ז צא, ב. ת\"ע קכב, ב. ס' האמונות והדעות לרס\"ג מ\"ב, פי\"ג. תניא פכ\"א ובמ\"מ הגהות והע\"ק לשם. לקו\"ת בהר מא, א. שם בהוספות נב, ג."],["1334","30","<b>לית מתב\"כ</b>: ראה ת\"ז בהקדמה יז, א,"]]],[4801940220,"הירידה<sup data-n=\"1335\">31</sup> והשפלה מגבוה לנמוך כי גם המדות הם נמשכים בבחי' צמצום גדול מעצמות אוא\"ס להיות מקור לעולמות ולכן נק' סוכ\"ע שהוא בגדר עלמין<sup data-n=\"1336\">32</sup> כו'. אך גילוי אור עצמותו שלמעלה מהיות מקור לעולמות אפי' בבחי' סובב ומקיף בחי' זאת מתגלה בבחי' חו\"ב עילאין שנק' או\"א עילאין<sup data-n=\"1337\">33</sup> כו', ולכן נק' החכ' קדש מלה בגרמי'<sup data-n=\"1338\">34</sup> כו' מצד שבו מתגלה עצמות אא\"ס שלמעלה מבחי' סומ\"מ כו'.\n<b>והנה</b> ידוע דבחי' ז\"א מקבל ב' מיני מוחין מבחי' או\"א עילאין, הא' בחי' מוחין דקטנות שהוא בחי' שפע וחיות לצורך קיום העולמות בלבד ומוחין אלו נמשכים מבחי' יחוד חיצוני דאו\"א כו' ונמשכים בבחי' חיצוני' המדות דז\"א, והב' הוא בחי' המשכת מוחין דגדלות שנמשכי' מבחי' יחוד פנימי דאו\"א<sup data-n=\"1339\">35</sup> בבחי' ז\"א והמשכה זאת נמשך בו ע\"י עסק התומ\"צ דמעה\"ת כו' ומוחין אלו נמשכים בבחי' פנימי' הת\"ת דז\"א ומחמת בחי' זאת נק' הז\"א בחי' קדש כו' להיות מתעלה לעצמות החכ\"ע הנק' קדש כנ\"ל. וזהו מי כמוכה באלים הוי'<sup data-n=\"1340\">36</sup> דקאי על פנימית הת\"ת שהוא נאדר בקדש דחכ\"ע כו', וזהו ג\"כ ענין יום השבת שהוא בפנימי' הת\"ת דז\"א שעולה לקבל המוחין מבחי' פנימי' היחוד דאו\"א כו' ולכן נק' יום השבת קדש<sup data-n=\"1341\">37</sup> מצד המשכת פנימי' המוחין שנמשכים בו בז\"א כו' וד\"ל. והנה ידוע שגם שעצמות המוחין דגדלות דאו\"א מאירים בז\"א אינו רק התפשטותם (שזהו התגלותם ע\"י הפרסא שנק' פרוכת המבדיל בין הקדש ובין קדה\"ק כנ\"ל)<sup data-n=\"1342\">38</sup>. אבל עצמות המוחין נשארים בבחי' העלם ומקיף כו' (ובחי'<sup data-n=\"1343\">39</sup> זאת נק' קדה\"ק שהוא בחי' בינה כו' וד\"ל. ..) והנה כמו שיש פרסא המפסיק בין בינה לז\"א כן יש פרסא מפסיק בין ז\"א למל'<sup data-n=\"1344\">40</sup> (וע\"ד חצר הכבד המפסיק בין אברי הנשימה לאברי המזון כו')<sup data-n=\"1345\">41</sup>, וכן יש פרסא מפסיק בין אצילות לבריאה וכן בין בריאה ליצירה וכן בין יצירה לעשי'<sup data-n=\"1346\">42</sup>, וכ\"ז נק' פרסא המפסיק בין קדש לקדש, אך יש פרסא המפסיק בין קדש לחול שהוא בין קדושת העשי' לק\"נ<sup data-n=\"1347\">43</sup> כו' וכן יש פרסא המפסיק בין ק\"נ לגקה\"ט<sup data-n=\"1348\">44</sup>, ונק' הבדלה בין טמא לטהור.",[["1335","31","<b>הוי\"ו מורה על הירידה</b>: ראה אגה\"ת פ\"ד."],["1336","32","<b>סוכ\"ע שהוא בגדר עלמין</b>: ראה תניא פמ\"ח. שערי אורה פט, א ובהערה 1."],["1337","33","<b>או\"א עילאין</b>: ראה ע\"ח שער הזווגים שט\"ו, פ\"א (מ\"ב). פ\"ד. לקמן מאמר ד\"ה את שבתותי תרי\"ב ובהערה 21."],["1338","34","<b>החכ' קדש מלה בגרמי'</b>: ראה זהר אמור צד, ב. שה\"א כט, ב ובהנסמן במ\"מ לשם."],["1339","35","<b>יחוד חיצוני. . פנימי דאו\"א</b>: ראה גם מאמרי אדה\"א בראשית ע' שנו ואילך. דברים ח\"ג ס\"ע תתפט ואילך. סה\"מ תרל\"ח ע' פח ואילך. וש\"נ."],["1340","36","<b>מי כמוכה באלים הוי'</b>: בשלח טו, יא. ראה גם לקמן מאמר ד\"ה וספרתם תרי\"ט על יד הערה 34."],["1341","37","<b>נק' יום השבת קדש</b>: תשא לד, יא. טו. ראה זהר אמור צד, א. שעה\"י קכח, א ובהערה 12."],["1342","38","<b>(שזהו. . כנ\"ל)</b>: ראה לעיל הערה 13."],["1343","39","<b>ובחי'</b>: אוצ\"ל: (... ובחי'. — ראה לעיל הערה 13."],["1344","40","<b>פרסא מפסיק בין ז\"א למל'</b>: ראה גם שעה\"י קטז, א."],["1345","41","<b>(וע\"ד. . כו')</b>: ראה לעיל הערה 13."],["1346","42","<b>פרסא מפסיק. . בין יצירה לעשי'</b>: ראה ע\"ח שער דרושי אבי\"ע שמ\"ב פי\"ג. פי\"ד."],["1347","43","<b>פרסא המפסיק בין קדש לחול. . העשי' לק\"נ</b>: ראה תו\"א לך יג, א. סידור שער המילה קמה, סע\"ב ואילך."],["1348","44","<b>פרסא המפסיק בין ק\"נ לגקה\"ט</b>: ראה סידור שם קמה, ד ואילך. סהמ\"צ להצ\"צ ז, סע\"ב ואילך."]]],[4801940273,"ודוגמא זאת באדם הוא עור הגס שעל הברית קדש ונק' ערלה, ועור הדק<sup data-n=\"1349\">45</sup> שפורעין אותו ומגלין העטרה כידוע, ולכן עור הערלה מסירין לגמרי להיותו מקור ליניקת גקה\"ט שגורם כח המתאוה לדברים האסורים, ועור הדק שהוא מקור לק\"נ שגורם כח המתאווה לדברים המותרים קורעין אותו כי דברים המותרים אין לדחותם להיותם הכרחים רק שצריך להכניס בהם אור האלקי ע\"י כוונתו שמתכוין לאכול לעבודת ה' ולא למלאות תאוותו כו', וזה\"ע בקיעת העור כו'. והנה ע\"י שמסירין בכאן הערלה שהוא מקור הרע עי\"ז גורמים שיתגלה בחי' אור הבינה שהוא למעלה מן הפרוכת המבדיל בין הקדש ובין קדה\"ק ויתגלה בכנס\"י כי מעהמ\"צ אין מגיעים לשם רק להמשיך פנימי' המוחין דאו\"א בז\"א שנק' קדש כנ\"ל (אבל<sup data-n=\"1350\">46</sup> עצמות קה\"ק שהם עצמות או\"א אין מגיע לשם מעה\"ת<sup data-n=\"1351\">47</sup> רק שבאמת הוא ח\"ח<sup data-n=\"1352\">48</sup> ורוצה ה' בעמו להתגלות בתוכם רק כל זמן שהערלה דבינה<sup data-n=\"1353\">49</sup> א\"א להתגלות כי טהור עינים מראות ברע<sup data-n=\"1354\">50</sup> כו' אך כשמסירין הערלה הוא מתגלה מאיליו וממילא כו', וזהו מש\"א הקב\"ה אתם לפי כחכם<sup data-n=\"1355\">51</sup> כי אין בכחכם רק להעביר הרע מלמטה ואני לפי כחי אתגלה בכם בעצמי ומהותי כי כל יכול הוא כו' וד\"ל)<sup data-n=\"1356\">52</sup>. וזה\"ע על מילה שניתנה בשמיני שהוא למעלה מן השבת שנק' שביעי כי שביעי הוא בחי' קדש (... שהוא התגלות פנימי' המוחין דאו\"א בז\"א כו'. ..) משא\"כ שמיני הוא בחי' עצם הבינה הנק' קה\"ק שהוא בחי' שמיני<sup data-n=\"1357\">53</sup> (... למעלה מז\"מ דז\"א כו'. ..), וזהו השבח על מצות מילה שניתנה בשמיני שזה מורה על שהיא מעוררת האור להיות נמשך ממקום גבוה יותר כו' שהוא בחי' עצם הבינה כנ\"ל. ובזה יובן ג\"כ ענין כניסת כה\"ג ביוהכ\"פ לקדה\"ק כי יוהכ\"פ נקרא שבת שבתון<sup data-n=\"1358\">54</sup> לכן בו מאיר בכנס\"י מעצם הבינה<sup data-n=\"1359\">55</sup> הנק' קדה\"ק והוא למעלה מבחי' שבת שמאיר בכנס\"י מפנימי' המוחין דאו\"א שבז\"א ולכן בו הוא סליחות עוונות שלמעלה ממשפט התורה כו' (... וזהו לפני הוי' דז\"א תטהרו<sup data-n=\"1360\">56</sup> כו'. ..), וכח זה הוא ע\"י מצות מילה שמעוררת ג\"כ מבחי' הבינה הנק' קה\"ק כנ\"ל. ובזה יובן גם ענין הנ\"ל שההבדלה במאכלות אסורות שכופה א\"ע להסיר ממנו כח המתאווה לדברים האסורים שזהו כדוגמת המילה רק שהוא ברוחני' שמסיר ומל ערלת הלב וזה מביא דייקא לחיי העוה\"ב שהוא בחי' התגלו'",[["1349","45","<b>עור הגס. . ועור הדק</b>: ראה גם אגה\"ק ס\"ד. תו\"ח מקץ ריט, ב ובהערה 25."],["1350","46","<b>(אבל</b>: ב: אבל. ראה בסמוך הערה 52. — ראה לעיל הערה 13."],["1351","47","<b>מעה\"ת</b>: מעשי התחתונים."],["1352","48","<b>ח\"ח</b>: ב: חפץ חסד."],["1353","49","<b>דבינה</b>: ב תיקן: דבוקה."],["1354","50","<b>טהור עינים מראות ברע</b>: חבקוק א, יג [ושם: רע — ראה מנחת שי שם. מאמרי אדה\"א בראשית ע' צו. וש\"נ. תו\"ח בא ח\"א קכג, ד. וש\"נ]."],["1355","51","<b>אתם לפי כחכם</b>: מדרש תהלים לא, ז."],["1356","52","<b>וד\"ל)</b>: ב: וד\"ל. ראה לעיל הערה 46. — ראה לעיל הערה 13."],["1357","53","<b>הבינה. . שמיני</b>: ראה זהר רעיא מהימנא פינחס רמה, ב. מאמרי אדה\"א דברים ח\"ד ע' א'שדמ. וש\"נ."],["1358","54","<b>יוהכ\"פ נקרא שבת שבתון</b>: אחרי טז, לא. אמור כג, לב. ראה גם הנסמן בתו\"ח בא ח\"א צד, ב."],["1359","55","<b>יוהכ\"פ. . הבינה</b>: ראה תז\"ח צג, ג. פרדס שעה\"כ שכ\"ג, פ\"י מערכת יום בסופו. לקו\"ת מסעי צ, א. סידור שער יוהכ\"פ רמט, ד ואילך."],["1360","56","<b>לפני הוי'. . תטהרו</b>: אחרי שם, ל. ראה גם לקמן מאמר ד\"ה כי ביום הזה יכפר תקצ\"ח על יד הערה 120."]]],[4801940323,"אור עצמו'<sup data-n=\"1361\">57</sup> הבינה (... משא\"כ כל המצות אינם מעוררים רק פנימי' המוחין דאו\"א שבז\"א כנ\"ל וד\"ל. ..).\n<b>והנה</b> איכות הבדלה הנ\"ל הוא ע\"י ב' סימנים שהם מפריס פרסא ומעלת גרה שני הסימנים ביחד, משא\"כ כשאין לו רק סימן א' מסימני טהרה הנ\"ל אז הוא עדיין ממאכלות אסורות כו', ולכן הוא מסתיר על אור הבינה הנק' חיי עוה\"ב, והטעם לשני הסימנים אלו הנה בסימן מפריס פרסא יש ב' טעמים הא' מבואר במק\"מ שמורה בזה שפרסותיו סדוקות הוא מבחי' נוגה<sup data-n=\"1362\">58</sup> שיש בו ג\"כ שני חלקים חלק הטוב וחלק הרע וממילא אינו רע גמור ויוכל להתברר וליכלל בקדושה, משא\"כ כשפרסותיו קלוטות מורה על שאין בו חלק הטוב וממילא הרע הוא רע גמור מבחי' גקה\"ט ולא יוכל להתברר וליכלל בקדושה כו', וטעם הב' (מבואר בשושן סודות<sup data-n=\"1363\">60</sup> כו')<sup data-n=\"1364\">59</sup> שהוא בדוגמא לבחי' מל' דקדושה הנק' בהמה רבה שמתחלקת ג\"כ לב' חלקים להשפיע בבחי' הקדושה וגם בבחי' הקליפה, כי רגלי' יורדות מות<sup data-n=\"1365\">61</sup> כו', וסי' הב' מעלת גרה מורה שמקלסת להקב\"ה כמאמרם במדרש על מלכות בבל<sup data-n=\"1366\">62</sup> כו' וד\"ל. והנה ד' מינים<sup data-n=\"1367\">63</sup> המבוארים בכתוב הם ד' קליפות כנגד אבי\"ע<sup data-n=\"1368\">64</sup>, וקלי' החזיר הוא להבדיל כנגד אצי' דקדושה, ולכן הוא גרוע יותר מכולם כי מצד עירובו הוא מתקנא יותר<sup data-n=\"1369\">65</sup> (כי כלום מתקנא<sup data-n=\"1370\">67</sup> כו')<sup data-n=\"1371\">66</sup>. ולכן הוא גרוע<sup data-n=\"1372\">68</sup> יותר כו', אך לע\"ל כאשר תתברר קליפה זאת (וא' שלא מצא מאמר זה<sup data-n=\"1373\">69</sup> במדרשי חז\"ל) [ע' בלקו\"ת לאדמו\"ר פ' ראה דרוש וכל בוניך ס\"ג ד\"ל ע\"ב. שציין על מאמר זה ועיין במדרש תהלים סי' קמ\"ו ע\"פ מתיר אסורים ובס' מא\"א אות ח' סעיף ו']<sup data-n=\"1374\">70</sup> כמאמרם עתיד החזיר ליטהר<sup data-n=\"1375\">71</sup> כו', אז תחזיר העטרה לבעלי' כמאמרם במדרש ויקרא פ' י\"ג ולמה נק' שמה חזיר שמחזרת עטרה לבעלי' הה\"ד ועלו מושיעים לשפוט כו' והיתה לה' המלוכה<sup data-n=\"1376\">72</sup> (... כמשי\"ת בהג\"ה וד\"ל. ..).",[["1361","57","<b>שמסיר ומל. . עצמו'</b>: ניתוסף ע\"פ ב."],["1362","58","<b>מפריס פרסא. . במק\"מ. . נוגה</b>: ראה מק\"מ לזהר שמיני מא, ב. אוה\"ת שמיני כרך א ע' מה."],["1363","60","<b>בשושן סודות</b>: לתלמיד הרמב\"ן כ\"כ על שער הספר מש\"ע האריז\"ל [כוונת התפלה סט\"ו — בכמה מהדורות ליתא. ראה שם הגדולים ח\"ב מערכת ספרים, שושן סודות. אהל רחל ח\"א ע' 93 ואילך]. ראה שם מז, א ד\"ה סוד להבדיל בין הבהמה. אוה\"ת שמיני שם ע' מד."],["1364","59","<b>(מבואר. . כו')</b>: ראה לעיל הערה 13."],["1365","61","<b>רגלי' יורדות מות</b>: משלי' ה. ה. ראה זהר ויחי רכא, ב. אוה\"ת משלי כרך א ע' תקסד ואילך. קונט' עה\"ח ע' 27 אילך."],["1366","62","<b>שמקלסת להקב\"ה. . על מלכות בבל</b>: ויק\"ר ספי\"ג (קרוב לסופה)."],["1367","63","<b>ד' מינים</b>: שמיני יא, ד-ז."],["1368","64","<b>ד' מינים. . ד' קליפות כנגד אבי\"ע</b>: ראה גם אוה\"ת שמיני שם ע' רלט."],["1369","65","<b>מצד עירובו הוא מתקנא יותר</b>: ראה גם אוה\"ת שם."],["1370","67","<b>כלום מתקנא</b>: ע\"ז נה, א."],["1371","66","<b>(כי. . כו')</b>: ראה לעיל הערה 13."],["1372","68","<b>גרוע</b>: ב: שונא."],["1373","69","<b>זה</b>: ניתוסף ע\"פ ב."],["1374","70","[ע'. . ו']: ניתוסף ע\"פ ב. ושם נכתב זה עה\"ג עם ציון בפנים."],["1375","71","<b>עתיד החזיר ליטהר</b>: ראה (בנוסף להמצויין בפנים) מאמרי אדה\"ז תקס\"ז ע' שכח. שע\"ת עג, ד ובהערה 95. לקמן בהביאור ובהערה 11."],["1376","72","<b>ועלו מושיעים. . המלוכה</b>: עובדי' א, כא [בדילוג]."]]],[4801940094,"<b>ביאור על הנ\"ל</b>\n[ביאור שרשי הדברים<sup data-n=\"1377\">1</sup> לפ\"ד בענין ב' סימנים הא' מפרסת פרסא מורה שיכול להתברר בירור הא' שהוא בחי' בירור דשם ב\"ן כנ\"ל שהמל' נק' בחי' בהמה רבה ומתחלקת להשפיע בבחי' הטוב ובחי' הרע כו' אך בחי' מעלת גרה הוא בירור שני שמברר בירור אחר בירור והוא בירור דשם מ\"ה שע\"י בירור זה דוקא עולים הניצוצות לשרשן בעולם התהו ומעוררים אורות בלתי מוגבלים שהם בבחי' א\"ס שיתגלה למטה בבחי' כלים דתיקון שזה\"ע חיי העוה\"ב שזה\"ע עטרותיהם בראשיהם<sup data-n=\"1378\">2</sup> והיינו הכתרים דעולם התהו יתגלו בראשיהם שהוא כלים דחב\"ד של הצדיקים שהוא מעולם התיקון, לכן המאכלים שנשלם בהם שני התנאים דוקא מביא אכילתן לחיי עוה\"ב אבל כשחסר תנאי מעלת גרה הוא סימן שלא יוכל להתברר בירור שני ולא יוכל לעורר חיי העוה\"ב וכן כשחסר תנאי<sup data-n=\"1379\">3</sup> מפריס פרסא אע\"פ שהיא מעלת גרה אינו מורה על בירור שני כיון שעדיין לא נתברר בירור הא' איך יתברר בירור שני אלא רק מרחוק הוא מקלס ומשבח להקב\"ה כנ\"ל במדרש על מלכות בבל<sup data-n=\"1380\">4</sup> אבל לא נתברר ונכלל באלקות כו'.\n<b>והנה</b> קלי' חזיר הוא קליפה שנגד אצי' וידוע בשם הרה\"מ נ\"ע שקליפות אצי' הוא בחי' ראומה<sup data-n=\"1381\">5</sup> ראו מ\"ה שאני בטל מצד שהביטול מורגש בו ביותר ולכן החזיר פרסותיו סדוקות שהוא מורה על ביטול רק שהוא קליפה מצד שהביטול מורגש בו ביותר ורוצה שהכל ידעו ממנו מצד שכוונת הביטול הוא להיות בבחי' יש ולכן הוא פושט טלפין<sup data-n=\"1382\">6</sup> ומראה לאחרים ראו שאני טהור כו', וכן עשו שהוא ז\"א דקליפה<sup data-n=\"1383\">7</sup> דאצי' נגד יעקב שהוא מרכבה לז\"א דקדושה<sup data-n=\"1384\">8</sup> דאצי' הראה שהוא צדיק ולכן שאל איך מעשרין את התבן<sup data-n=\"1385\">9</sup>, ולכן כאשר תתברר קליפה זאת ותוכלל בנש\"י (וזהו כוונתם עתיד החזיר ליטהר<sup data-n=\"1386\">10</sup> שאין הכוונה גשם החזיר<sup data-n=\"1387\">11</sup> כי לא יחליף ולא ימיר דתו<sup data-n=\"1388\">12</sup> ח\"ו רק הניצוצות והחיות שבו והיינו מה שהוא רוצה להיות בבחי' יש זה יתברר ויוכלל בקדושה כו') תתהווה ממנה התהוות דקדושה בכאו\"א מישראל שהו\"ע ויגבה לבו",[["1377","1","<b>ביאור שרשי הדברים</b>: ביאור מר\"ה על מאמר ד\"ה להבדיל בין הטמא תרט\"ז שנדפס לפנ\"ז."],["1378","2","<b>העוה\"ב. . עטרותיהם בראשיהם</b>: ראה ברכות יז, א."],["1379","3","<b>מעלת גרה. . תנאי</b>: ניתוסף ע\"פ ב."],["1380","4","<b>כנ\"ל במדרש על מלכות בבל</b>: בסיום המאמר שלפנ\"ז."],["1381","5","<b>הרה\"מ. . ראומה</b>: וירא כב, כד. ראה גם לקמן מאמר ד\"ה את שבתותי תקצ\"ח ובהערות 125-126."],["1382","6","<b>החזיר. . פושט טלפין </b>[ב: טלפיו]: ב\"ר פס\"ה, א."],["1383","7","<b>עשו שהוא ז\"א דקליפה</b>: ראה ע\"ח שער הקליפות שמ\"ח, פ\"ג."],["1384","8","<b>יעקב. . לז\"א דקדושה</b>: ראה ע\"ח שם. שער פרצופי זו\"ן של\"א, פ\"א."],["1385","9","<b>איך מעשרין את התבן</b>: ראה ב\"ר פס\"ג, י. יל\"ש (רמז קי) ורש\"י תולדות כה, כז."],["1386","10","<b>עתיד החזיר ליטהר</b>: נסמן בסיום המאמר שלפנ\"ז."],["1387","11","<b>שאין הכוונה גשם החזיר</b>: ראה בהנסמן בהערה שלפנ\"ז. שיעורים בספר התניא פ\"נ ע' 691 בהערה. מאמר ד\"ה והחרים אחש\"פ תשמ\"ה. סה\"ש תנש\"א ח\"א ע' 162 ואילך."],["1388","12","<b>לא יחליף ולא ימיר דתו</b>: ע\"פ פיוט יגדל. תניא פכ\"ה."]]],[4801940159,"בדרכי הוי'<sup data-n=\"1389\">13</sup> והוא מדת המל' דקדושה שנק' שעיר להוי'<sup data-n=\"1390\">14</sup> כי הוא מוכרח בהתחלת עבודה אבל בגמר העבודה צ\"ל ביטול בתכלית כמאמר הבעש\"ט ע\"פ כל שאור<sup data-n=\"1391\">15</sup> וכל דבש לא תקטירו כו' קרבן ראשית כו' ואל המזבח כו', וזה\"ע גאוותן של ישראל<sup data-n=\"1392\">16</sup> כו' שהוא בחי' המל' דקדושה כח ההתנשאות דקדושה הנ\"ל שעז\"א במסתרים תבכה נפשי<sup data-n=\"1393\">17</sup> על שניטלה כו', וזה\"ע שתחזיר עטרה היינו שע\"י הבירורים דקליפת חזיר שיוכללו בקדושה תבנה ותכונן בנין המל' בפרצוף שלם שהוא גילוי כח ההתנשאות דקדושה וזהו חזרת עטרה לבעלי', וזהו ועלו מושיעים<sup data-n=\"1394\">18</sup> לשפוט את הר עשו היינו לברר אותו כי המשפט נק' בירור כי בירור הוא שמעלה את הניצוץ למקומו שהי' מתחלה, וזה\"ע משפט בלה\"ק, שפי' לס’ד ר כל דבר שיהי' על מקומו וכמאמר הירושלמי וכי יש משפט לעצים אלא קרש כו' כנ\"ל במאמר יהי לבי<sup data-n=\"1395\">19</sup> תמים<sup data-n=\"1396\">20</sup> כו', ועי\"ז והיתה לה' המלוכה שתבנה בפרצוף שלם כו' וד\"ל כנלע\"ד בדא\"פ. ..).",[["1389","13","<b>ויגבה לבו בדרכי הוי'</b>: דהי\"ב יז, ו."],["1390","14","<b>המל' שנק' שעיר </b>[ב: שער]<b> להוי'</b>: ראה זהר בהקדמה ז, ב. רע\"מ תרומה קנח, א. לקמן מאמר ד\"ה והתהלכתי תרכ\"ב ובהערה 10."],["1391","15","<b>כמאמר הבעש\"ט ע\"פ כל שאור</b>: ויקרא ב, יא-יב. כתר שם טוב קה\"ת סשצ\"ג נז, א ואילך."],["1392","16","<b>גאוותן של ישראל</b>: נסמן בהערה שלאח\"ז."],["1393","17","<b>במסתרים תבכה נפשי</b>: ירמי' יג, יז. חגיגה ה, ב."],["1394","18","<b>שתחזיר עטרה. . ועלו מושיעים</b>: ראה סיום המאמר שלפנ\"ז."],["1395","19","<b>וכמאמר הירושלמי. . במאמר יהי לבי תמים</b>: פלח הרמון שמות ס\"ע שמה ואילך."],["1396","20","<b>יהי לבי תמים</b>: ב: שקודם לזה."]]],[4801940095,"<b>ש\"ק פ' תזריע שנת הנ\"ל — תרכ\"ג</b>\n<b>אשה</b> כי תזריע<sup data-n=\"1397\">1</sup> וילדה זכר<sup data-n=\"1398\">2</sup> כו'. הנה כנ\"י נק' אשה<sup data-n=\"1399\">3</sup> כמ\"ש לזאת יקרא אשה<sup data-n=\"1400\">4</sup> כי מאיש לוקחה זאת, והענין הוא כי הנה אשה הוא אש ה'<sup data-n=\"1401\">5</sup> והה' הוא מ\"ש בה' בראם<sup data-n=\"1402\">6</sup> שהוא ענין ה' מוצאות הפה שמהם נמשכו העשרה מאמרות וחילופיהן ותמורותיהם ונמשך מזה ריבוי הצירופים לאין שיעור להוות רבוי הנבראים לאין קץ ולהחיותם, ומקור הדיבור שהוא מקור כל הצירופים הוא אות ה' אתא קלילא<sup data-n=\"1403\">7</sup> דלית בה מששא כמו למטה באדם הברת הה' שהוא הארה בעלמא הנמשך מהבל הלב לפה להיות מקור הדיבור והוא הארה בעלמא שאינו נוגע לעצמות ומהות הנפש כי הוא התפשטות חיצוני' הנפש שאין בזה מפנימיותה כלל כו', כן למעלה מקור המחי' והמהווה את כל עולמות הנבראים מאין ליש בדרך או\"פ הנק' ממכ\"ע וגם אור המקיף את כולם בהשוואה הנק' סוכ\"ע הכל הוא רק זיו והארה מעצמות אלקות די\"ס דאצי' שהוא בחי' מדת מלכותו ית' שאינה אלא זיו והתפשטות מי\"ס דאצי' כמו למטה באדם מדת המלוכה שאינה אלא זיו והתפשטות על זולתו להיות מלך על עם משא\"כ בעצמי' הנפש כשהוא לבדו אין לה מציאת כלל כו' כן למעלה מדת המלוכה הוא התפשטות מעצמות אלקות להיות מלך על עם שהם הנבראים מאין ליש שנק' עם מלשון עוממות<sup data-n=\"1404\">8</sup> ועי\"ז הם בטלים אליו ית' כמו למטה העם הם בתכלית הביטול אל המלך כו' [רק למעלה גם התהוותם נמשך מבחי' מדת המלוכה כו'], ולהיות מדת המלוכה אינה רק זיו והתפשטות לזאת נק' בשם ה' אתא קלילא דלית",[["1397","1","<b>אשה כי תזריע</b>: הנחת ר' הלל מדרוש כ\"ק אדמו\"ר הצ\"צ.\nמאמר הצ\"צ הוא ד\"ה זה שנדפס באוה\"ת תזריע כרך ב ע' תצו [סה\"מ תרכ\"ו ע' עד וראה הנסמן בהמפתח שם ע' ]."],["1398","2","<b>אשה כי תזריע וילדה זכר</b>: תזריע יב, ב."],["1399","3","<b>כנ\"י נק' אשה</b>: ראה במדב\"ר פ\"ט, מד."],["1400","4","<b>לזאת יקרא אשה</b>: בראשית ב, כג."],["1401","5","<b>אשה הוא אש ה'</b>: ראה סוטה יז, א. זהר בראשית מח, ב. ביאוה\"ז נח ז, ב. תו\"ח בשלח ח\"א רלח, ב. וש\"נ."],["1402","6","<b>בה' בראם</b>: בראשית ב, ד. ראה מנחות כט, ב. ב\"ר פי\"ב, ב."],["1403","7","<b>אות ה' אתא קלילא</b>: ראה לקו\"ת האזינו עד, ד: והה' הוא אות קלילא דלית בי' מששא כמבואר באקדמות. תו\"ח ח\"ש קכא, ג ובהערה 48."],["1404","8","<b>עם מלשון עוממות</b>: שער היחוד והאמונה פ\"ז. ראה אוה\"ת שמות ע' פט. סה\"מ תר\"ס ע' ה."]]],[4801940160,"בה מששא שהוא פנימי' המהות ועצמי' אלקות רק זיו והתפשטות חיצוני' כו'. אך בחי' אשה אש ה' היינו פנימי' התשוקה שבמדת המלוכה ליכלל במקורה שהוא מהו\"ע אלקות די\"ס שנלקחה ממנו [כידוע דבנין המל' מעשיראה דכולהו<sup data-n=\"1405\">9</sup> כו'], ותשוקה זאת הוא בבחי' רשפי אש, ולכן נק' אשה אש ה' כו' וד\"ל.\nב) <b>והנה</b> בנש\"י יש שני בחי' שלפעמים נק' בשם בנים כמ\"ש בנים אתם לה' אלקיכם<sup data-n=\"1406\">10</sup> והיינו מצד שרשם בפנימי' הכלים דאצי' וזהו ישראל עלה במח'<sup data-n=\"1407\">11</sup> כו' והיינו בחי' כלים דאצי' וכידוע דמוח הבן נמשך ממוח האב<sup data-n=\"1408\">12</sup> ולכן יש בהם אה' הטבעי' לדבקה בו [... היינו בבחי' אא\"ס המלובש בבחי' המדות דאצי' כמארז\"ל וכי אפשר לדבקה בו<sup data-n=\"1409\">13</sup> אלא הדבק במדותיו כו'. ..], וזהו המ\"ע דואהבת את הוי' אלקיך ולכאורה איך שייך ציווי על האה'<sup data-n=\"1410\">14</sup> כו' אך להיות שיש בהם אה' זאת בטבע כאהבת הבן אל האב והציווי אינו אלא לעוררה שתהי' נמשכת מהעלם אל הגילוי בלבד והיינו ע\"י ההתבוננו' בדברים המעוררים את האה' כו', אך מה שנק' בשם אשה [... כי כללות נש\"י בחי' כנסת ישראל נק' אשה וממנה נמשך רשפי אש התשוקה בכל נשמה פרטי' ונק' כל נשמה פרטי' בשם אשה כו'. ..] הוא למעלה מבחי' בנים הנ\"ל. והענין הוא דאהבת הבן אל האב היינו מצד שרשו להיות עצמי' עמו וממנו לוקח כן בנש\"י מצד שעלו במח' שענין מח' זאת הכוונה הוא במוחין שבמדות",[["1405","9","<b>דבנין המל' מעשיראה דכולהו</b>: ראה זהר פינחס רנג, רע\"ב. שעה\"י קמא, ב ובהנסמן במ\"מ לשם."],["1406","10","<b>בנים אתם לה' אלקיכם</b>: פ' ראה יד, א."],["1407","11","<b>ישראל עלה במח'</b>: ראה ב\"ר פ\"א, ד. שע\"ת קטו, ב. תו\"ח שמות ח\"א לב, ב ובהערה 248."],["1408","12","<b>דמוח הבן נמשך ממוח האב</b>: ראה ת\"ז תי\"ח לב, סע\"א. תו\"ח בא ח\"א קטז, ב הערה 49."],["1409","13","<b>וכי אפשר לדבקה בו</b>: ראה כתובות קיא, ב. שע\"ת לב, א ובהערות 4-5."],["1410","14","<b>דואהבת. . ציווי על האה'</b>: ואתחנן ו, ה. ראה גם לקו\"ת ואתחנן יא, ב. מאמרי אדה\"א ויקרא ח\"ב ע' תשלו ואילך (ובהנסמן שם ע' תשלז). הנחות תקע\"ז ע' שטז. תו\"ח נח מט, ג ובהנסמן במ\"מ לשם. ויקהל ח\"ב שצה, ג. וש\"נ. סה\"מ תרל\"ח ע' רנו הערה 13. המשך זאת חנוכת המזבח תר\"ם פט\"ז."]]],[4801940221,"דאצי' שזהו ענין פנימי' הכלים דאצי' [כידוע דבד\"כ הכלים דחב\"ד הוא בחי' פנימי' הכלים וכלים דחג\"ת ונה\"י נק' אמצעי' הכלים וחיצוני' הכלים אע\"פ שבד\"פ יש בכ\"א בחי' פנימי אמצעי חיצון כו'] שמצד זה נק' נש\"י בנות ירושלים ירא של\"ם<sup data-n=\"1411\">15</sup> כמבואר בלק\"ת במאמר שחורה אני<sup data-n=\"1412\">16</sup> כו' שמחמת זה יש להם בחי' ביטול בלי הסתר כלל שזהו יראה שלימה כו' אך בחי' ביטול זה הוא בחי' אא\"ס המלובש במדות דאצי' שהמדות הם מקורי ההשתלשלו' דבי\"ע כמ\"ש כי אמרתי עולם חסד יבנה<sup data-n=\"1413\">17</sup> כו', אך בחי' חו\"ב יש בהם שני בחי' הא' מה שנעשים מקור להמשיך מוחין למדות דאצי' ובחי' זאת הוא מקור למקור לחיות העולמות כו' [ונק' יסו\"ת בל' הקבלה] ובחי' זאת הוא בחי' המדות שבחו\"ב<sup data-n=\"1414\">18</sup> שמהם נעשים מוחין למדות [ונק' יסו\"ת כנ\"ל וזהו ענין מה שלפעמים נאמר כי ששת ימים כו' ולא בששת ימים והיינו שית יומין עילאין דבהון עביד קוב\"ה שמי' וארעא כמבואר בזהר<sup data-n=\"1415\">19</sup> ולפעמי' נאמר בעשרה מאמרות נבה\"ע<sup data-n=\"1416\">20</sup> והיינו כאשר נחשב המוחין השייך למדות עם המדות הם תשעה בחי' עם מדת המלוכה היא עשרה כו', וזהו בראשית בחוכמא<sup data-n=\"1417\">21</sup> היינו חכ' השייך למדות כו' וד\"ל]. אך יש בחי' חו\"ב עילאין שהם למעלה מהיות מקור לעולמות ונק' אור המאיר לעצמו למעלה מהיות מקור לזולתו כו' [ונק' או\"א עילאין<sup data-n=\"1418\">22</sup> בל' הקבלה ועד\"מ באדם התחתון יש ב' מיני שכל א' איך להתנהג במדותיו שזהו בחי' שכל השייך למדות והב' להשכיל השכלות עמוקות לעצמו כו'].\n<b>והנה</b> שרש התורה הוא בחי' חכמה עילאה שלמעלה מהיות מקור לעולמות כו', וזהו התורה קדמה לעולם אלפים שנה<sup data-n=\"1419\">23</sup> שהוא ענין אלפך חכמה אלפך בינה<sup data-n=\"1420\">24</sup> כו'. והנה נאמר ביום חתונתו זה מתן תורה<sup data-n=\"1421\">25</sup> והיינו שבשעת מתן תורה קבלו נש\"י המלובשים בגופים דייקא [כי להם דייקא ניתנה התו' ולא לנשמות שאינם מלובשים בגופים] טיפת חכמה עילאה דתורה דייקא שמחמת זה נק' אשה אש ה' והיינו שנמשך בהם רשפי אש התשוקה בבחי' כלות הנפש לבחי' עצמות אא\"ס שבחו\"ב עילאין שלמעלה מהיות מקור לעולמות כו', וזהו למעלה מבחי' בנים הנ\"ל",[["1411","15","<b>ירושלים ירא של\"ם</b>: ראה ב\"ר פנ\"ו, י. תוד\"ה הר תענית טז, א. מאמרי אדה\"ז על פרשיות התורה ח\"א ע' רצה ובהנסמן במ\"מ לשם. עט\"ר שער ר\"ה ע' 56. סה\"מ תרכ\"ז ע' תיד. וש\"נ."],["1412","16","<b>בלק\"ת במאמר שחורה אני</b>: שה\"ש ו, ג."],["1413","17","<b>כי אמרתי עולם חסד יבנה</b>: תהלים פט, ג. ראה גם לעיל ע' קיג ובהערה 90."],["1414","18","<b>יסו\"ת. . המדות שבחו\"ב</b>: [ ישראל סבא ותבונה] ראה שעה\"י קי, ב ובהערה 15. שם קנז, ג ואילך. לעיל ע' ז."],["1415","19","<b>כי ששת ימים. . בזהר</b>: תשא לא, יז. ראה זהר ויחי רמז, א. אמור צד, רע\"ב. מאמרי אדה\"א דברים ח\"א ע' רז ואילך. וש\"נ. לקמן מאמר ד\"ה את שבתותי תרי\"ב על יד הערה 19 ואילך."],["1416","20","<b>בעשרה מאמרות נבה\"ע</b>: אבות רפ\"ה."],["1417","21","<b>בראשית בחוכמא</b>: תרגום ירושלמי בראשית א, א."],["1418","22","<b>או\"א עילאין</b>: ראה ע\"ח שער הזווגים שט\"ו, פ\"א (מ\"ב). פ\"ד. לקמן מאמר ד\"ה את שבתותי תרי\"ב ובהערה 21."],["1419","23","<b>התורה קדמה לעולם אלפיים שנה</b>: ראה שבת פח, ב וברש\"י שם. מדרש תהלים צ, ד. הנסמן במאמרי אדה\"א דברים ח\"א ע' כ."],["1420","24","<b>אלפך חכ' אלפך בינה</b>: ע\"פ איוב לג, ג. שבת קד, א."],["1421","25","<b>ביום חתונתו זה מתן תורה</b>: שה\"ש ג, יא. תענית כו, ב (במשנה). ראה מאמרי אדה\"א דברים ח\"ג ע' תתמז בהערה."]]],[4801940274,"כי בחי' בנים הוא בחי' ההתקשרות לבחי' אא\"ס המלובש בבחי' המדות דאצי' כנ\"ל אך בחי' אשה הוא רשפי התשוקה להיות כלה שארי ולבבי<sup data-n=\"1422\">26</sup> לעצמו' אא\"ס שבחכמה ובינה עילאין והיינו מה שעל כל דיבור פרחה נשמתם<sup data-n=\"1423\">27</sup> שמזה נעשה מקור בכללות נש\"י להיות להם מס\"נ באחד<sup data-n=\"1424\">28</sup> שזהו כלות הנפש אליו ולא למדותיו<sup data-n=\"1425\">29</sup> כו' וכמבואר במ\"א ע\"פ עולת תמיד העשוי' בהר סיני<sup data-n=\"1426\">30</sup> שמה שכללות נש\"י עולים תמיד במס\"נ בק\"ש בכל יום נעשה זאת בהר סיני ע\"י גילוי עשה\"ד דתורה שהוא מחכמה עילאה דייקא ולכן על כל דבור פרחה נשמתן שמצד זה יש להם כח בכל יום למסור נפשם באחד כו' וד\"ל. ובחי' זאת נק' אשה שהוא למעלה מבחי' בנים כו', וזהו לזאת יקרא אשה כי מאיש לוקחה זאת שיש בזה ב' פירושים הא' דקאי על בחי' המל' דאצי' שנק' אשה אש ה' כי מאיש שהוא בחי' ז\"א שהוא בחי' המדות דאצי' עם המוחין השייך למדות כו' וממנו לוקח בחי' המל' דאצי' כידוע דבנין המל' מעשיראה דכולהו ממל' שבכתר נמשך כתר מל' וממל' דחכ' בחי' חכ' שבמל' כו' ולזאת תשוקת המל' להיות נכללת במקורה כמאמר למען יזמרך כבוד<sup data-n=\"1427\">31</sup> דנהורא תתאה קארי תדיר לנהו\"ע<sup data-n=\"1428\">32</sup> כו' ותשוקה זאת נמשכה בכ\"א מישראל בפרט שהוא הניצוץ אלקי שמלובש ביחידה שבו שנמשך מבחי' המל' דאצי' [כמאמר כל ישראל בני מלכים<sup data-n=\"1429\">33</sup> כו'], ותשוקת הניצוץ ג\"כ להתפשט מלבושי הנר\"ן לא לחפוץ בשום דבר גשמי דעשי' ולא שום דבר רוחני אפי' מעולם הבריאה כו' רק להיות כלה שארי ולבבי להיות נכלל בעצמי' האצי' כו'.\n<b>והנה</b> זהו בחי' רצוא שבנשמה אך אח\"כ מתגלה שרש הנשמה שמפנימי' הכלים דאצי' שנק' בנות ירושלים כנ\"ל ופועלת בחי' שוב להתלבש בנר\"ן בכדי להמשיך גילוי אא\"ס שבאצי' למטה בבי\"ע להיות בנין הזכר מהחסדי'<sup data-n=\"1430\">34</sup> שהוא בחי' ז\"א דאצי' לזאת גם הנשמה אשר לוקחה משם יש בה טבע החסדי' להיות נמשך למטה כו', ושני הבחי' ביחד דרו\"ש הנ\"ל נק' בנים כו' כמו הבן שיש בו חלק האב שהוא בחי' הלובן וחלק האם שהוא בחי' אודם כו' ומשניהם נעשה הגוף כו' כמאמר שלשה שותפים באדם<sup data-n=\"1431\">35</sup> אב ואם כו' כך אית אב ואם לנשמתא כו' וחלק האם הוא",[["1422","26","<b>כלה שארי ולבבי</b>: תהלים עג, כו."],["1423","27","<b>שעל כל דיבור פרחה נשמתם</b>: ראה שבת פח, ב. מאמרי אדה\"א ויקרא ח\"א ע' ג. וש\"נ. נ\"ך ע' שפא. וש\"נ. תו\"ח בראשית יא, ב."],["1424","28","<b>מס\"נ באחד</b>: ראה זהר רע\"מ משפטים קיט, א. צו לג, א. מאמרי אדה\"א דברים ח\"ב ע' תו. וש\"נ. שמות ח\"א ע' רעח ואילך. הנחות תקע\"ז ע' שא."],["1425","29","<b>אליו ולא למדותיו</b>: ואתחנן ד, ז. במאמרי אדה\"ז תקס\"ג ח\"א ע' קכו: שארז\"ל בספרי. ראה פרדס שער הכוונה של\"ב, פ\"ב. מאמרי אדה\"א ויקרא ח\"א ע' נ. וש\"נ. נ\"ך ע' לד. וש\"נ."],["1426","30","<b>ע\"פ עולת תמיד העשוי' בהר סיני</b>: דרוש בפתיחה זו נזכר גם ברשימת הרח\"א ביחובסקי במפתח דרושי ר' הלל שבבוך 1228 [אבל לא צויין מקומו]. ראה גם אוה\"ת פינחס ע' א'קעח. ע' א'קעט."],["1427","31","<b>למען יזמרך כבוד</b>: תהלים ל, יג."],["1428","32","<b>דנהורא תתאה קארי תדיר לנהו\"ע</b>: ראה זהר היכלות פקודי רנו, ב. תרומה קמ, רע\"א. וישלח קעח, ב. לך עז, ב. פו, ב."],["1429","33","<b>כל ישראל בני מלכים</b>: שבת סז, א. ראה גם שע\"ת מ, ב ובהערה 9. ראה גם לקמן מאמר ד\"ה וספרתם הה' על יד הערה 67."],["1430","34","<b>בנין הזכר מהחסדי'</b>: ראה זהר תזריע מח, ב. נשא קמה, ב. ע\"ח שער מ\"ן ומ\"ד שט\"ל, דרוש י."],["1431","35","<b>שלשה שותפים באדם</b>: ראה נדה לא, א."]]],[4801940324,"בחי' הניצוץ אלקי הנ\"ל שהוא מבחי' המל' דאצי' והוא בחי' האודם שהוא בחי' גבו' כו' וחלק האב שהוא בחי' שרש הנשמה מבחי' פנימי' המוחין דז\"א כנ\"ל שהוא בחי' הלובן כו' ומשני הבחי' ביחד נמשך בחי' הנשמה הנק' בנים כו' וזהו בנים אתם להוי' אלקיכם הוי' הוא בחי' ז\"א<sup data-n=\"1432\">36</sup> דאצי' כו' ואלקיכם הוא בחי' פנימי' המל'<sup data-n=\"1433\">37</sup> דאצי' שנק' כנ\"י<sup data-n=\"1434\">38</sup> ומשני הבחי' ביחד נמשך בחי' נש\"י שנק' בשם בנים כו', אך יש בחי' עליונה יותר שנק' מחמת זה אשה כו' כי יש לפרש פי' ב' בתיבת לזאת יקרא אשה כי מאיש לוקחה אש יו\"ד<sup data-n=\"1435\">39</sup> דחכ\"ע והיינו בחי' גבו' דאבא ובחי' זאת קבלו ישראל בשעת מתן תורה, ומצד זה יש להם תשוקה ברשפי אש ליכלל למעלה בבחי' עצמו' אא\"ס המלובש בחו\"ב עילאין שהוא למעלה מהיות מקור לעולמות כנ\"ל [ויתפרש מי לי בשמים<sup data-n=\"1436\">40</sup> הוא בחי' ז\"א דאצי' ועמך לא חפצתי בארץ הוא המל' דאצי' שלא יחפוץ בבחי' זאת רק להיות כלה שארי ולבבי לבחי' אא\"ס שבחו\"ב עילאין כו' וד\"ל]. והנה לגילוי בחי' זאת תזכה הנשמה מצד ירידתה בגוף ולומדת התורה שבעוה\"ז הגשמי ועי\"ז באה לבחי' רשפי אש להיות כלה שארי ולבבי לעצמו' שלמעלה מהיות מקור לעולמות כנ\"ל וזהו מש\"א במשנה דאבות חביבין ישראל שנק' בנים למקום כו' ואח\"כ א' חביבין ישראל שניתן להם כלי חמדה<sup data-n=\"1437\">41</sup> שהוא התורה שעי\"ז באים לבחי' אש ה' שלמעלה מבחי' בנים כנ\"ל וד\"ל.\n<b>והנה</b> על בחי' זאת א' אשה כי תזריע כו' הזריעה הוא עסק המצות כמאמר זרעו לכם לצדקה<sup data-n=\"1438\">42</sup> כו' וכללות המצות נק' בשם צדקה<sup data-n=\"1439\">43</sup> ועשיות המצות שאיש הישראלי עושה נק' בשם זריעה כמשל זרעוני גינה שאינם נאכלים מצד שאין בהם שום טעם כלל אך כאשר נזרעין בארץ יצמיחו פירות בטוב טעם [ודוקא בארץ המוכנת לזה אבל במדבר לא יצמיח מאומה כו'] כן כנ\"י נק' בשם ארץ חפץ כמ\"ש כי תהיו אתם לי ארץ חפץ<sup data-n=\"1440\">44</sup> כו' והטעם כי מדת המלוכה מתפשטת על כל הנבראים הרוחניים כמו המלאכים שבכל ג' העולמות דבי\"ע כולם עומדים ברום עולם<sup data-n=\"1441\">45</sup> ומשמיעים ביראה שהוא בחי' ביטול למדת מלכותו ית' ועי\"ז מתהפכים מיש לאין כו' אך המלאכים אינם בבחי' נפרד כ\"כ כו', אך נש\"י ירדו בגופים גשמיי' והם בבחי' נפרד לכן כאשר המה בטלים אליו ע\"י קיום התומ\"צ בהם נשלם עיקר המלוכה כי אין מלך בלא עם<sup data-n=\"1442\">46</sup> מלשון עוממות שהמה בבחי' יש נפרד שם הוא עיקר גילוי",[["1432","36","<b>הוי'. . ז\"א</b>: זהר אד\"ר נשא קכט, א."],["1433","37","<b>ואלקיכם. . המל'</b>: ראה זהר בראשית כב, א."],["1434","38","<b>המל'. . שנק' כנ\"י</b>: ראה זהר בלק קצז, א."],["1435","39","<b>מאיש. . אש יו\"ד</b>: ראה סוטה יז, א. פרדס שעה\"כ שכ\"ג, פ\"א מערכת אשה. סידור שער הק\"ש פ, סע\"ב ואילך. תו\"ח בשלח ח\"א רלח, ב. וש\"נ."],["1436","40","<b>מי לי בשמים</b>: תהלים עג, כה."],["1437","41","<b>חביבין ישראל שנק' בנים. . כלי חמדה</b>: אבות פ\"ג, מי\"ד."],["1438","42","<b>זרעו לכם לצדקה</b>: הושע י, יב."],["1439","43","<b>וכללות המצות נק' בשם צדקה</b>: ראה מאמרי אדה\"א ויקרא ח\"ב ע' עדרת. וש\"נ. תו\"ח שמות ח\"א יד, א ובהערה 628."],["1440","44","<b>כי תהיו אתם לי ארץ חפץ</b>: מלאכי ג, יב [בהוספת תיבת: לי — ראה אוה\"ת כאן ע' תצז. הנסמן במאמרי אדה\"א שמות ח\"א ע' ו. לקמן מאמר ד\"ה אם בחוקותי תר\"י על יד הערה 91]."],["1441","45","<b>כולם עומדים ברום עולם</b>: ברכת יוצר."],["1442","46","<b>אין מלך בלא עם</b>: בחיי וישב לח, ל. ראה הנסמן במאמרי אדה\"ז על פרשיות התורה ח\"ב לע' תרלא."]]],[4801940372,"המלוכה לכן נק' כנ\"י ארץ חפץ כי בהם עיקר חפץ הפנימי שבמדת המלוכה ולכן בהם הוא הזריעה דתומ\"צ הגשמיי' כמו התפילין שהם בקלף גשמי וכן הציצית הם בצמר גשמי, ולהיותם מלובשים בדברים גשמיי' לכן אין בהם גילוי אור כלל וכמשל זרעוני גינה שאין בהם טעם כלל כו' אך כשעושה איש הישראלי את המצוה היינו שמניח התפילין בראשו ומתעטף בטלית שעם הציצית ממשיך עי\"ז להיות הקב\"ה מניח תפילין<sup data-n=\"1443\">47</sup> היינו שנמשך תוס' אורות עליונים מעצמו' אא\"ס ונעשין מוחין דחב\"ד ומתלבשים במדות העליונות דאצי' שנק' קוב\"ה כו' וכן הקב\"ה מתעטף בטלית<sup data-n=\"1444\">48</sup> שהוא מקיף העליון דתורה אור שעל זה נאמר עוטה אור כשלמה כו' [כמבואר בסידור שער הציצית<sup data-n=\"1445\">49</sup> ] וחוטי הציצית הם הארות הבוקעים מן המקיף בפנימי והוא ענין ל\"ב נ\"ח<sup data-n=\"1446\">50</sup> שמאירים במדות העליונות דאצי' שנק' בשם קוב\"ה כנ\"ל, ונמצא שכללו' המצו' הם המשכות אורות עליונים למעלה במדות העליונו' והם תרי\"ג מצות דאורייתא<sup data-n=\"1447\">51</sup> וז' דרבנן<sup data-n=\"1448\">52</sup> שמספרם תר\"ך<sup data-n=\"1449\">53</sup> וממשיכים תר\"ך עמודי אור<sup data-n=\"1450\">54</sup>, ויש עוד בחי' במצות והיינו שע\"י שנעשים בדברים גשמיי' מתבררי' הניצוצים מעולם התוהו שנפלו בדברים הגשמיי' ועולים למעלה ונעשים כלים לאורות הנ\"ל שנמשכים על ידם וזהו מדריגת המ\"ע שהם רמ\"ח פיקודי' רמ\"ח אברים דמלכא<sup data-n=\"1451\">55</sup> כלים לאורות כו', משא\"כ שס\"ה ל\"ת הם כדוגמת הגידין שעל ידם נמשך חיות הנפש להתלבש באברים כן ע\"י הל\"ת נמשכים אורות עליונים הנ\"ל שנתעוררו ע\"י מעהמ\"צ ומתלבשים בהכלים שנעשים ע\"י המצות כו' וד\"ל. וזהו שמי עם י\"ה שס\"ה<sup data-n=\"1452\">56</sup> זכרי עם ו\"ה רמ\"ח ובד\"כ י\"ה הוא בחי' אור ו\"ה הוא בחי' כלי' כו' [... הגם שבכל ספי' מע\"ס יש בחי' אור וכלי אך עיקר גילוי הכלים הוא במדות כו' שהוא בחי' ו\"ה דשם הוי' משא\"כ בחו\"ב שהוא בחי' י\"ה לא נתגלו הכלים גילוי גמור, וכמבואר במ\"א שעצם הסברא דבינה יכולים להטותה<sup data-n=\"1453\">57</sup> לחסד ולדין וד\"ל. ..].",[["1443","47","<b>הקב\"ה מניח תפילין</b>: ברכות ו, א. ראה גם תו\"א מקץ לה, ב. סה\"מ תרכ\"ז ע' מה. וש\"נ. ע' קיא. וש\"נ."],["1444","48","<b>הקב\"ה מתעטף בטלית</b>: ראה ר\"ה יז, ב."],["1445","49","<b>עוטה אור כשלמה. . בסידור שער הציצית</b>: תהלים קד, ב. ראה שם ג, ג ואילך."],["1446","50","<b>וחוטי הציצית. . ל\"ב נ\"ח</b>: ראה זח\"ג תוספת שא, א. מאמרי אדה\"א בראשית ע' שצד. וש\"נ."],["1447","51","<b>תרי\"ג מצות דאורייתא</b>: ראה מכות כג, סע\"ב. כללי המצות לר\"י גיקטיליא מערכת שש מאות [צפת תשנ\"ב ע' 208]. לקו\"ש יתרו כרך כו ס\"ע 424 ואילך. אג\"ק שלו ח\"ג ע' רג."],["1448","52","<b>וז' דרבנן</b>: ראה אגה\"ק סכ\"ט. דרך חיים פנ\"ו. פס\"ד. לקו\"ש יתרו כרך כא ע' 401. לקו\"ש שופטים כרך כט ע' 104 ואילך. וש\"נ."],["1449","53","<b>תרי\"ג. . וז' דרבנן שמספרם תר\"ך</b>: ראה תורת העולה להרמ\"א ח\"ג פל\"ח (לב, א). של\"ה יתרו שיו, א. מאו\"א מערכת תר\"ך סנ\"ו. הנסמן במאמרי אדה\"ז על פרשיות התורה ח\"א לע' שלח."],["1450","54","<b>תר\"ך עמודי אור</b>: ראה פרדס שער מהות והנהגה ש\"ח, פ\"ג. לקו\"ת להאריז\"ל חבקוק. מאמרי אדה\"א ויקרא ח\"ב ע' תסא. וש\"נ. תו\"ח בראשית מה, ג הערה 32."],["1451","55","<b>רמ\"ח פיקודי' רמ\"ח אברים דמלכא</b>: ראה ת\"ז ת\"ל (עד, סע\"א). תניא רפכ\"ג. סידור שער החנוכה רפ, א. שע\"ת עב, ג הערה 17."],["1452","56","<b>שמי עם י\"ה שס\"ה</b>: ראה שמות ג, טו. ת\"ז בהקדמה ד, סע\"ב. ה, א. לקו\"ת פקודי ג, ב ובהנסמן במ\"מ לשם. מאמרי אדה\"א דברים ח\"ג ע' תתקי. וש\"נ. תו\"ח בא ח\"א קיד, א. וש\"נ. סה\"מ תרכ\"ז ע' קכט. וש\"נ."],["1453","57","<b>שעצם הסברא דבינה יכולים להטותה</b>: ראה גם סידור שער כוונת המקוה קנז, ד. מאמרי אדה\"ז תקס\"ז ע' רפז. פלח הרמון יתרו ע' רמו."]]],[4801940417,"והנה כל הנ\"ל הן הבירור והעלאה שנעשה ע\"י מעה\"מ והן ההמשכה שנעשה ע\"י מעה\"מ הוא הכל כשאיש הישראלי עושה אותם ולא כשיעשה אותם מי שהוא אינו ישראל וכן כשלא יתקיימו ע\"י איש הישראלי כמו התפילין כשיהיו מונחים על השולחן אע\"פ שכבר נגמרו בקדושה כהלכתן לא יפעלו מאומה רק כשיניח אותם איש הישראלי על ראשו אז יעוררו שיהי' הקב\"ה מניח תפילין וכן עד\"ז בכל המצות כו' וד\"ל, ולכן נק' ישראל בשם ארץ חפץ כמו ארץ המצמיח כל מיני צמיחה וטעמי הפירות כו' כן המה המצמיחים אורות עליונים ומלבישים אותם בכלים ע\"י מעהמ\"צ שלהם כנ\"ל וד\"ל, ולכן נק' ג\"כ בשם אשה כמ\"ש אשה יראת ה' היא תתהלל<sup data-n=\"1454\">58</sup> מל' בהלו נרו עלי ראשי<sup data-n=\"1455\">59</sup> כי המה דייקא ממשיכים תוס' אורות ע\"י מעהמ\"צ כנ\"ל וד\"ל [... ולפ\"ד שני הבחי' שבמל' מה שנק' ארץ ומה שנק' אשה כו' הנה ארץ הוא בחי' הדומם שבבחי' המל' דאצי' והיינו מל' דמל' שנעשית כתר לבריאה שבחי' זאת נק' עפר שבקרקע המשכן<sup data-n=\"1456\">60</sup> והיא המשפלת עצמה לברר בירורים דנוגה שבג' עולמות דבי\"ע ובפרטי פרטיות הנה מל' דמל' נעשית ג\"כ פרצוף וי' כלים הפנימי' נעשים נשמה לעולם הבריאה וי' כלים האמצעי' נעשים נשמה לעולם היצירה וי' כלים החיצוני' נעשים נשמה לעולם העשיי' ובחי' מל' דמל' דעשי' מהווה כל עולם העשי' הרוחני והגשמי ובעשי' גשמי' הוא עיקר הבירור ע\"י מעה\"מ הגשמיי' ובחי' זאת נק' ארץ שהוא בחי' המל' דעשי' המתלבשת בעולם העשי' הגשמי לברר בירורי' שנק' בשם צמיחה כו' משא\"כ בחי' חו\"ב עילאין שבמל' דאצי' הוא בחי' מדבר שבה [כי בבחי' המל' גופא יש דצח\"מ כידוע] בחי' זאת נק' אשה כו' ובבחי' זאת הוא רשפי אש התשוקה ליכלל במקורה, והנה עד\"מ הגשמי המאכלים שצומחים מן הארץ מתבררים ע\"י אדם האוכל אותם ונעשים דם כדמו ובשר כבשרו וממשיכים חיות לכל האברים גם אל המוח ומשם נמשך הזרע וגם זרע האשה נמשך מן המוח שלה כן ברוחני' כל הבירורים דנוגה דבי\"ע עולים למעלה באצי' בבחי' חו\"ב דמל' ופועלים רשפי אש במל' דאצי' ליכלל למעלה בעצמי' האצי' ותשוקה זאת נק' העלאת מ\"ן וגורם המשכת מ\"ד היינו המשכת אורות העליונים שנמשכים ע\"י המצות שנק' רמ\"ח פיקודין כנ\"ל ושמירת הל\"ת כנ\"ל, וע\"ד העבודה בפרט בכל איש מישראל בחי' השפלות בעצם שיש בו שמחמת זה בכחו לקבל עומ\"ש לכל אשר יגזור ה' [כענין נעשה קודם לנשמע כו'] בחי' זאת נק' ארץ כי ארץ מל' א רצ ה שהוא מקור כל רצון בחי' קבלת עומ\"ש, ומה שהוא מוסר נפשו באחד שהוא רשפי אש התשוקה אליו ממש בחי' זאת נק' אשה כו' וד\"ל. ..].\nג) <b>והנה</b> להבין ענין אשה כי תזריע וילדה זכר כו' הנה ארז\"ל אשה מזרעת תחילה<sup data-n=\"1457\">61</sup> יולדת זכר איש מזריע תחילה יולדת נקבה, וביאור מאמרם ז\"ל צריך להקדים ענין שימני כחותם על לבך<sup data-n=\"1458\">62</sup> שזהו תש\"ר כחותם על זרועך זהו תש\"י",[["1454","58","<b>אשה יראת ה' היא תתהלל</b>: משלי לא, ל."],["1455","59","<b>בהלו נרו עלי ראשי</b>: איוב כט, ג."],["1456","60","<b>מל'. . עפר שבקרקע המשכן</b>: ראה נשא ה, יז. רמ\"ז לזהר תזריע מו, ב. וראה גם שה\"א מד, א ובהערה 2."],["1457","61","<b>אשה מזרעת תחילה</b>: נדה לא, א."],["1458","62","<b>שימני כחותם על לבך</b>: שה\"ש ח, ו. ראה ת\"ז תכ\"ב סה, ב. לקו\"ת שה\"ש מה, א. וש\"נ."]]],[4801940458,"ומבואר בסידור שער התפילין<sup data-n=\"1459\">63</sup> שיש שני חותמות חותם בולט וחותם שוקע, ומחותם הבולט שמלמטה למעלה נמשך מלמעלה למטה בחי' חותם שוקע וזהו תש\"י כו'. ומחותם שוקע שמלמטה למעלה נמשך מלמעלה למטה חותם הבולט וזהו תש\"ר כו'. והנה חותם הבולט מלמטה למעלה הוא בחי' אה' כרשפי אש שמפשיט א\"ע מגדרי הכלי לא לחפוץ בשום דבר גשמי ורוחני רק ליכלל בעצמותו המאיר לעצמו למעלה מהיות מקור לעולמות והוא בחי' חו\"ב עילאין [למעלה מחו\"ב השייך למדות שנק' יסו\"ת כנ\"ל] ובהם מלובש מז\"ת דאריך [כידוע דאו\"א מלבישים לזרועות דאריך<sup data-n=\"1460\">64</sup> כו'] ועי\"ז נמשך מלמעלה למטה מבחי' ז\"ת דאריך תוס' אורות ומתלבשים באו\"א ונמשכים בבחי' מוחין לז\"א והמוחין מתפשטי' בכל אברים דז\"א שהם רמ\"ח פיקודין כנ\"ל ונק' המשכה זאת חותם שוקע מלמעלה למטה להיות שפע זאת מלובשת בתוך הכלים ולבושים דאו\"א וז\"א וזהו בחי' זכרי עם ו\"ה רמ\"ח מ\"ע שהמצות הם כלים ולבושים להלביש אא\"ס בתוכם, אך בחי' חותם שוקע מלמטה למעלה הוא בחי' יר\"ע יראה פנימי' שאחר האה' כרשפי אש [כידוע דד' אותיות הוי' הוא בחי' דחו\"ר רחימו ודחילו<sup data-n=\"1461\">65</sup> עילאה כו'] ושרשה ביוד דשם הוי' אין דחכ\"ע הנה בחי' זאת מעורר חותם הבולט שיהי' נמשך מלמעלה למטה היינו המשכת שפע מבחי' ג\"ר דאריך שאינם מלובשים בכלים ולבושים כלל והיינו ג\"כ שמי עם י\"ה שס\"ה ל\"ת שע\"י הל\"ת שמירה מן הרע בלבד מצד היראה וביטול עי\"ז נמשך בחי' י\"ה שבהוי' דאריך שהוא ג\"ר שבו כו' וד\"ל.\n<b>ובזה</b> יובן ענין אשה מזרעת תחילה יולדת זכר כו' כי הנה מבואר למעלה בפי' אשה שהוא בחי' אש ה' והיינו רשפי אש האה' רבה אליו כמ\"ש למעלה מהיות מקור לעולמות כו' הנה זהו עצם מהותה שהוא מהגבורות [כידוע דבנין הנוק' מהגבורות<sup data-n=\"1462\">66</sup> כו'], וזהו חותם בולט עדיין שהוא בחי' יש כו', אך ההזרעה שלה היינו כשבאה לבחי' יראה פנימי' שלמעלה מבחי' אה' רבה הנ\"ל ואז באה לבחי' אין ממש שהוא ביטול גמור בחי' מ\"ה דחכמה וזהו חותם שוקע שמלמטה למעלה [וזהו סמכוני באשישות<sup data-n=\"1463\">67</sup> באיש ואשה והיינו כשהוא בבחי' איש ועושה עצמו כאשה להיות בבחי' חותם שוקע כו' וזהו כי כאיש גבורתו<sup data-n=\"1464\">68</sup> היינו ההתגברות לבטל א\"ע מכל וכל לבוא לבחי' אשה חותם שוקע בחי' ביטול ואין כו', ומבחי' כזאת נעשה סמיכה לכנ\"י בזה\"ג כו' ממכי\"ק<sup data-n=\"1465\">69</sup> ] ועי\"ז נמשך חותם בולט מלמעלה למטה גילוי עצמו' אא\"ס בחי' מ\"ה דעתיק והוא בחי' דכורא דעתיק שבכחו לגלות רוממות עצמותו כמ\"ש למטה ממש",[["1459","63","<b>בסידור שער התפילין</b>: טו, א."],["1460","64","<b>דאו\"א מלבישים לזרועות דאריך</b>: ראה ע\"ח שער או\"א שי\"ד, פ\"א. הנסמן במאמרי אדה\"ז על פרשיות התורה ח\"א לע' שנד."],["1461","65","<b>דד' אותיות. . דחו\"ר רחימו ודחילו</b>: ראה זהר רע\"מ נשא קכג, סע\"א. מאמרי אדה\"ז תקס\"ב ח\"ב ע' תקמז ובהנסמן במ\"מ לשם. ש\"א מ, א ואילך. שע\"ת כו, א הערה 4. סה\"מ תרכ\"ז ע' קנג. וש\"נ."],["1462","66","<b>דבנין הנוק' מהגבורות</b>: ראה ע\"ח שער תיקון הנוקבא של\"ד, פ\"ה. מאמרי אדה\"א דברים ח\"א ע' ריח. וש\"נ. תו\"ח בשלח ח\"א רמד, א. וש\"נ."],["1463","67","<b>סמכוני באשישות</b>: שה\"ש ב, ה. ראה ת\"ז רתס\"ד צה, א. תי\"ט לט, ב."],["1464","68","<b>כי כאיש גבורתו</b>: ס' שופטים ח, כא."],["1465","69","<b>ממכי\"ק</b>: ממאמר כתב יד קדשו (של הצ\"צ). התוכן — ראה אוה\"ת כאן ע' תק. לקמן מאמר ד\"ה והתהלכתי תרכ\"ב הערה 50."]]],[4801940495,"בעולמות הנבראים מאין ליש [וזהו פי' עתיק כמעתיק מספר אל ספר<sup data-n=\"1466\">70</sup> כו' שהוא כח הירידה למטה כו'] וזהו יולדת זכר [כי לידה נק' השפע בבי\"ע שהוא אור של תולדה כו' וד\"ל] [והגם שמבואר למעלה שהשפע הוא מבחי' ג\"ר דאריך עיקר השפע הוא דכורא דעתיק רק שהלבוש הוא ג\"ר דאריך אך הלבוש אינו מסתיר כלל לכן נק' שפע זאת בולט בלי לבושים כלל כמו עצם הרצון שאינו מורכב בשום פרט דשכל ומדות אינו לבוש המסתיר כלל לעונג המלובש בו כו' כנלע\"ד בדרך אפשר], אך כשאיש מזריע תחילה כשההתעוררות באה מלמעלה הגם שפועל במקבל בחי' ביטול דחותם שוקע כו' כיון שבחי' ביטול הנ\"ל לא נפעל במקבל מעצמו רק מלמעלה [והגם שחותם הבולט דמ\"ה כרשפי אש הי' במקבל מצד עצמו זה אינו נק' התעוררות כי עיקר המעורר הוא ביטול בחי' אין כו'] הנה התעוררות זאת נמשך רק מבחי' נוק' דעתיק שהוא בחי' ב\"ן דעתיק רוממות עצמי' [זהו פי' ב' בתיבת עתיק מלשון נעתק ומובדל<sup data-n=\"1467\">71</sup> כו'] ואין בכח בחי' זאת להתגלות כמ\"ש למטה בבי\"ע רק הארה וזהו יולדת נקב\"ה הארה בעלמא נתגלה בעולמות הנבראים מאין ליש כו' וד\"ל להיות ההמשכה נמשכת דרך כלים ולבושים לזאת אינו נמשך רק הארה [וזהו חותם בולט מלמטה למעלה כי להיותה הארה בעלמא לזאת תשוקתם ליכלל במקורה אשר לוקחה משם כו' וד\"ל]<sup data-n=\"1468\">72</sup>.\n<b>וזהו</b> ההפרש בין קבלת התורה שקבלו ישראל בשעת מתן תורה ובין קבלת התורה שקבלו ישראל בימי הפורים, שבשעת מתן תורה לא היתה רק התעוררות מלמעלה מצד עצמו ליתן להם התורה [ומה שהקדימו נעשה לנשמע<sup data-n=\"1469\">73</sup> שהוא ביטול גמור בחי' חותם שוקע זהו נפעל בהם מלמעלה מצד אתעדל\"ע כו'] ולכן לא האירה בהם רק הארה בעלמא מבחי' חכמתו העצמי' [שהוא בחי' חכ' שבבחי' נוק' דע\"י כנ\"ל] ולכן לא נתקבל אור התורה בבחי' פנימי' גמור רק בבחי' מקיף וזהו כפה עליהם הר כגיגי'<sup data-n=\"1470\">74</sup> כו' ונק' החלו לעשות<sup data-n=\"1471\">75</sup> התחלת בלבד משא\"כ בימי הפורים ע\"י מסי\"נ שלהם על התורה נתעורר חכמה העצמי' ממש [שהוא בחי' חכ' דדכורא דע\"י] ולכן נתקבל בהם אור חכמתו העצמי' בבחי' פנימי למטה כמו למעלה ולכן נאמר וקיבל היהודים שנתקבל בהם בבחי' פנימי ממש את אשר החלו בשעת מתן תורה<sup data-n=\"1472\">76</sup> בבחי' מקיף כו' וד\"ל. וזהו מה ראו על ככה<sup data-n=\"1473\">77</sup> ומה הגיע אליהם כו' מה ראו על ככה היינו מה שקבלו בנפשם בחי' מ\"ה דחכמתו העצמי' שהיא התורה ומ\"ה הגיע עליהם מלמעלה לעוזרם לזה ההתעוררות שנתעוררו מכח עצמם כו' [כי הגם שהיה ההתעוררות מכח עצמם מ\"מ אלמלא הקב\"ה עוזרו<sup data-n=\"1474\">78</sup> אין יכול לו כו' רק שההתחלה הי' מהם כו' וד\"ל].",[["1466","70","<b>עתיק כמעתיק מספר אל ספר</b>: ראה גם לקו\"ת חוקת סז, ב. מאמר שני המאורות להרי\"א עפשטיין ע' 34."],["1467","71","<b>עתיק מלשון נעתק ומובדל</b>: ראה לקמן מאמר ד\"ה ונקדשתי תקצ\"ח על יד הערה 34."],["1468","72","[וזהו. . וד\"ל]: אינו ברור ואולי כ\"ז נמחק בגוכת\"י. ב: ליתא. גד: וד\"ל."],["1469","73","<b>שהקדימו נעשה לנשמע</b>: שבת פח, א."],["1470","74","<b>כפה עליהם הר כגיגי'</b>: שבת שם."],["1471","75","<b>החלו לעשות</b>: נסמן בהערה הבאה."],["1472","76","<b>וקיבל היהודים. . מתן תורה</b>: אסתר ט, כג. ראה שבת פח, א. מאמרי אדה\"א נ\"ך ע' תקטו. וש\"נ."],["1473","77","<b>מה ראו על ככה</b>: ראה אסתר ט, כו. ראה גם תו\"א מג\"א קיח, ד."],["1474","78","<b>אלמלא הקב\"ה עוזרו</b>: קדושין ל, ב. סוכה נב, ב. ראה תניא רפי\"ג."]]],[4801940527,"[ולפ\"ד הטעם למה כשאיש מזריע אין ההמשכה רק מבחי' נוק' דעתיק כנ\"ל יובן ע\"פ מ\"ש בסידור בשער ברהמ\"ז<sup data-n=\"1475\">79</sup> שבתחילת ההשתלשלות הי' מצד שחפץ חסד בעצמו ע\"כ עלה ברצונו להטיב ורצון זה הי' מקור לכל ההשתלשלות וממנו נמשכים כל העולמות חיותם והתהוותם מרכד\"ר עד סוכד\"ר כו', אך אח\"כ תלוי במעה\"ת<sup data-n=\"1476\">80</sup> ומבואר שם אשר סומ\"ע מוכיח על תחילת המחשבה שמה שהי' בתחילה חפץ חסד חפץ זה הוא שיהי' לו דירה בתחתונים [וכמארז\"ל נתאווה הקב\"ה להיות לו דירה בתחתונים<sup data-n=\"1477\">81</sup> כו'] והמשכה זאת להיות לו דירה תהי' ע\"י מעשה התחתוני' דייקא, נמצא שבחי' חפץ חסד זה הוא בחי' מקבל מבחי' סוף מעשה שעלה במחשבה תחילה כי סוף מעשה השפיע הח פ ץ הנ\"ל להיות חפץ להיטיב כו' וזהו בחי' דכורא ונוק' דע\"י כי בחי' נוק' דע\"י הוא בחי' העונג שברצון להטיב שנק' חפץ חסד [כי חפץ הוא פנימי' הרצון<sup data-n=\"1478\">82</sup> שהוא העונג שבו כו'] ודכורא דע\"י הוא בחי' עונג הנעלם שצפה שיקבל מסוף מעשה, ולכן כשאשה מזרעת תחילה שמתעוררים התחתונים בכח עצמם לתשובה ותומ\"צ [ורק עזר נמשך להם מלמעלה כמאמר אלמלא הקב\"ה עוזרו כו'] ממילא נשלם עונג הנעלם הנ\"ל שבסומ\"ע ושלימות העונג גורם התגלותו [כמו כשאדם בונה בנין כשמשלים אותו ברצונו מתענג מאד בגילוי משא\"כ באמצע העשי' העונג הוא בהעלם כו'] ונגלה עונג נעלם זה למטה בעשי' גשמי וזהו יולדת זכר בחי' דכורא דע\"י שהוא בחי' עונג הנעלם הנ\"ל שמתגלה למטה וזהו יולדת כי ההתגלות נק' לידה כו' משא\"כ כשאיש מזריע תחילה כו' היינו כשאין התחתונים מתעוררים מעצמם רק שמעוררים אותם מלמעלה שאז לא נשלם הכוונה בשלימות לכן יולדת נקבה שאינו מתגלה למטה בבי\"ע רק בחי' עונג המלובש ברצון להטיב שנק' חפץ חסד שהוא בחי' נוק' דע\"י כנלע\"ד בדרך אפשר].\nד) <b>והנה</b> ארז\"ל על פ' הנה נחלת ה' בנים שכר פרי הבטן<sup data-n=\"1479\">83</sup> בשכר שמשהין עצמן כו' כדי שתזרע אשתו תחילה כו' בשכר זה הויין לון בנים זכרים כו'. ויובן בהקדם המבואר בזהר [תרומה קמב]<sup data-n=\"1480\">84</sup> שהמשכת הטיפה יש בה ג' בחי' אור מים רקיע כו' וכן הוא בהמשכת השכל ממקורו מבחי' אין יש ג' בחי' הנ\"ל, בחי' אור הוא כאשר השכל הפרטי הוא כלול עדיין בכח המשכיל שנק' אין והיינו כשכבר נתעורר לבוא לידי גילוי שהוא מוכן לבוא לידי גילוי במוח החכמה אך עדיין לא נתגלה [והיינו בעת היגיעה שמייגע עצמו להבין קודם שמבין כו'] זהו בחי' אור ואח\"כ כשמבריק ומתגלה במוח החכמה נק' מים שזהו בחי' נקודה דחכמה קודם שמתפשט בהשגה דבינה כו' ואח\"כ כשמתלבש נקודת השכל באותיות ההשגה דבינה זהו בחי' רקיע וזהו בחי' קרח בחי' אגלידו מיא שזהו מה שנקודת השכל מתלבשת באותיות",[["1475","79","<b>בסידור בשער ברהמ\"ז</b>: קט, ב ואילך."],["1476","80","<b>שבתחילת ההשתלשלות. . במעה\"ת</b>: [ במעשה התחתונים] ראה ע\"ח שער דרושי הנקודות ש\"ח, ספ\"ו."],["1477","81","<b>נתאווה הקב\"ה. . בתחתונים</b>: ראה תניא רפל\"ו. לעיל ע' עב ובהערה 17."],["1478","82","<b>חפץ הוא פנימי' הרצון</b>: ראה שו\"ת צ\"צ חאבה\"ע סרס\"ג (ח, ד). מאמרי אדה\"א דברים ח\"ד ע' א'רצ. וש\"נ."],["1479","83","<b>הנה נחלת ה'. . הבטן</b>: תהלים קכז, ג. ראה נדה עא, א."],["1480","84","<b>בזהר </b>[תרומה קמב]: כנצ\"ל: קסז. ראה סידור שחרית ע, א. המשך חייב אדם לברך תרל\"ח ספכ\"א ואילך."]]],[4801940554,"ההשגה או במשל זר ועי\"ז נעשה הולדת המדות מן השכל. והנה בחי' רקיע הנ\"ל נק' בטן כמ\"ש מבטן מי יצא הקרח הנורא<sup data-n=\"1481\">85</sup> כו' [כידוע דת\"ת גופא<sup data-n=\"1482\">86</sup> ושליש העליון הוא עד החזה ושליש האמצעי הוא עד הטבור ושליש התחתון הוא מן הטבור ולמטה, והנה מת\"ת דאימא משליש התחתון שבו נעשה כתר לז\"א<sup data-n=\"1483\">87</sup> וזהו מבטן מ\"י שהוא בינה<sup data-n=\"1484\">88</sup> כו'].\n<b>וע\"ד</b> הנ\"ל בהמשכת שכל שהוא בחי' גילוי אור מעצמי' הנפש שצ\"ל ג' בחי' הנ\"ל כ\"ה בהמשכת הטיפה שהוא המשכה יותר נעלית להיותו המשכת עצמות הנפש להוליד בדומה צ\"ל ג\"כ ע\"ד זה להיות נמשך בג' בחי' הנ\"ל אור הוא בלחלוחי' הרוחני' וכאשר מתלבשת בגשם המוחין ונמשכת דרך ח\"י חוליות השדרה עד הברית שהוא בחי' יסוד הוא בחי' מים ואח\"כ כשמתקבלת ונקלטת ברחם הנוק' נק' רקיע ושם נגמר הולדת הולד להצטייר ברמ\"ח אברים כו' וכ\"ה למעלה בהמשכת הנשמה ממקורא דכולא שהוא מבחי' פנימי' עצמותו כמאמר ויפח כו' מאן דנפח<sup data-n=\"1485\">89</sup> מתוכי' נפח כו' ונמשכת עד היסוד עליון כמאמר אור זרוע לצדיק<sup data-n=\"1486\">90</sup> ומשם נמשך להתלבש בבחי' המל' דאצי' וע\"י המל' נבראת מאין ליש כמאמר טהורה היא אתה בראתה<sup data-n=\"1487\">91</sup>, אך באמת יש ג' בחי' אור מים רקיע הנ\"ל בטיפת הדכר עצמה [כמבואר בע\"ח שער מ\"ן ומ\"ד דרוש<sup data-n=\"1488\">92</sup> ] ובחי' רקיע שבטיפת הדכר נק' בטן מי כו' והיינו בחי' ת\"ת דאימא שנעשה כתר לז\"א ולכן כל מה שמשהה יותר לעכב השפע שתשהה יותר קודם שתתלבש בבחי' רקיע הנ\"ל בא השפע מבחי' גבוה יותר וממילא נמשך השפע למטה כמו למעלה שזהו בחי' לידת זכר ולא הארה בעלמא שנק' לידת נקבה כנ\"ל וד\"ל.\n<b>וזהו</b> כלל גדול בכ\"מ שכל מה שהשפע שוהה יותר להתגלות היא נמשכת ממקום גבוה יותר, וכמו שבבטן הנוק' כל שהולד שוהה יותר הוא בבחי' קיום יותר כמו אלי' שנשתהה בבטן הנוק' יב\"ח<sup data-n=\"1489\">93</sup> לכן מתקיים עם חומר גופו כי עלה השמים עם חומר גופו מפני שהי' בו בחי' ביטול בחומר גופו יותר מצד שיהוי הקליטה בבטן הנוק' כנ\"ל וכל שהביטול הוא ביותר הוא מתקיים ביותר [כידוע בשם הרה\"מ נ\"ע בענין יראת ה' לחיים<sup data-n=\"1490\">94</sup> כו'], כן הוא בבחי' טיפת הדכר עצמה כל שהיא שוהה יותר",[["1481","85","<b>מבטן מי יצא הקרח הנורא</b>: איוב לח, כט [בהוספת תיבת: הנורא. תיבות: הקרח הנורא הובא ביחזקאל א, כב]."],["1482","86","<b>דת\"ת גופא</b>: ראה זהר רע\"מ פינחס רכג, א. ת\"ז בהקדמה יז, א."],["1483","87","<b>מת\"ת דאימא. . נעשה כתר לז\"א</b>: ראה ע\"ח שער מוחין דצלם שכ\"ג, רפ\"ה ורפ\"ז. מאמרי אדה\"א דברים ח\"ג ע' תתעג. וש\"נ."],["1484","88","<b>מ\"י שהוא בינה</b>: זהר משפטים קיז, ב. לקו\"ת פקודי ד, ג. תו\"ח פקודי ח\"ב תמג, ד ובהערה 78."],["1485","89","<b>ויפח כו' מאן דנפח</b>: בראשית ב, ז. ראה תניא רפ\"ב. שה\"א צח, א הערה 5."],["1486","90","<b>אור זרוע לצדיק</b>: תהלים צז, יא."],["1487","91","<b>טהורה היא אתה בראתה</b>: ברכת אלקי נשמה."],["1488","92","<b>שער מ\"ן ומ\"ד דרוש</b>: ה'."],["1489","93","<b>אליהו. . יב\"ח</b>: ראה גם שה\"א צח, ב ובהערה 15."],["1490","94","<b>הרה\"מ. . יראת ה' לחיים</b>: משלי יט, כג. ראה סידור שער הק\"ש פב, סע\"ג. לקמן מאמר ד\"ה גדולה מילה תר\"כ ובהערות 49-48."]]],[4801940572,"לבוא הוא הסימן שהוא מבחי' עצמי' יותר ומיוחדת עם העצמי' ביותר ולכן שיהוי על הבטן גורם הולדת זכרים שהוא בחי' גבוה יותר, וכ\"ה ברוחני' השכל כשמשכיל השכל במהירות ומתפעל תומ\"י שנק' נמהרי לב אין השכל מבורר כ\"כ מן הפסולת וממילא ההתפעלות אינה מבוררת ונקי' כ\"כ משא\"כ כששוהה זמן רב ומעיין בעומק הדעת וההשגה להבין היטב את השכל לאשורו ולעמקו אז השכל שמאיר במוחו שנמשך מלמעלה מן השכל [כמאמר והחכמה מאין תמצא<sup data-n=\"1491\">95</sup> כו'] מבורר ונקי מאוד מחלקי הטעות שהוא הפסולת שבשכל וממילא ההתפעלות הנולד מן השכל ממילא ומאליו [בלתי בחירה ורצון לזה כמבואר בקו' ההתפעלות<sup data-n=\"1492\">96</sup> כו'] היא מבוררת ונקי' מתערובת פסולת והיא לה' לבדו בלתי הרגשת עצמו כלל כו' וד\"ל.\n<b>וזהו</b> ג\"כ ענין חסידים הראשונים היו שוהין שעה אחת קודם התפלה<sup data-n=\"1493\">97</sup> כו' להיות שהמשכת הטיפה היא בברכת שים שלום<sup data-n=\"1494\">98</sup> ונמשכת ע\"י ח\"י ברכאן שהם כנגד ח\"י חוליות השדרה שהטיפה נמשכת על ידיהם כמבואר בגמ' פ' א\"ע<sup data-n=\"1495\">99</sup> כו' [... וחסידים הראשונים היו מדריגת דכר כו' ואפשר לומר שגם בכל הנשמות יש בהם בחי' דכר דאצי' רק שהוא בהעלם ובחי' זאת היא המתפללת כו' כמבואר בתשו' הרה\"מ נ\"ע על שאלת אדמו\"ר הזקן נ\"ע איך אנו מתפללי' הלא אנו בני רחל<sup data-n=\"1496\">100</sup> והתובעת בפה כו' והשיב כי אנו במדריגת צדיקים שהוא למעלה מבחי' רחל, והכוונה כנ\"ל הגם שכללות נש\"י נמשכים מבחי' המל' דאצי' היינו חלק האם שבהם אבל חלק האב הוא מבחי' פנימי' הכלים דז\"א דאצי' כו' ולכן תפילתן אינה בקשה רק המשכה כו' כי בחי' הדכר שבהם מתגלה בעת התפילה כו' וד\"ל. ..], ולכן היו שוהין שעה אחת כדי שתהי' המשכת הטיפה ממקום גבוה יותר וזהו ג\"כ כוונת רז\"ל בענין הקטרת שהי' צוברה<sup data-n=\"1497\">101</sup> כדי שיהי' עשנה שוהה לבוא כו' [וזהו שנאמר לעתיד כי לא בחיפזון תצאו<sup data-n=\"1498\">102</sup> כו' להיות שתהי' ההמשכה ממקום גבוה יותר שאין למעלה הימנו והיינו מפנימי' עתיק כו' ממכי\"ק<sup data-n=\"1499\">103</sup> וזהו תקראי אישי ולא תקראי לי עוד בעלי<sup data-n=\"1500\">104</sup> וזהו ג\"כ ממכי\"ק<sup data-n=\"1501\">105</sup> ועדיין אינו מובן לי עד יערה<sup data-n=\"1502\">106</sup> כו'], וזהו דבר אל בני ישראל כו' אשה כי תזריע כו' להיות אשה מזרעת תחילה ומה שייך זה אל בנ\"י אלא הכוונה להיות משהין עצמן כו' בכדי שתהי' ההשפעה ממקום גבוה יותר כו' וד\"ל.",[["1491","95","<b>והחכמה מאין תמצא</b>: איוב כח, יב."],["1492","96","<b>בקו' ההתפעלות</b>: נדפס במאמרי אדה\"א קונטרסים — ראה שם ע' פט."],["1493","97","<b>חסידים הראשונים. . התפלה</b>: ברכות ל, ב."],["1494","98","<b>שהמשכת הטפה היא בברכת שים שלום</b>: ראה פע\"ח שער העמידה ש\"ט, פ\"כ."],["1495","99","<b>ח\"י ברכאן. . השדרה. . בגמ' פ' א\"ע</b>: ראה ברכות כח, ב."],["1496","100","<b>בתשו' הרה\"מ. . אנו בני רחל</b>: ראה או\"ת קה\"ת הוספות סס\"ג ע' 36."],["1497","101","<b>הקטרת שהי' צוברה</b>: יומא מט, ב."],["1498","102","<b>כי לא בחיפזון תצאו</b>: ישעי' נב, יב."],["1499","103","<b>ממכי\"ק</b>: ממאמר כתב יד קדשו (של הצ\"צ). ראה אוה\"ת כאן ע' תקב."],["1500","104","<b>תקראי אישי ולא תקראי לי עוד בעלי</b>: הושע ב, יח."],["1501","105","<b>ממכי\"ק</b>: נסמן לעיל בהערה 103."],["1502","106","<b>עד יערה </b>: ישעי' לב, טו."]]],[4801940096,"<b>מהרר\"ה נ\"ע</b>\n<b>שמעתי</b> מרא\"פ ששמע ממהרמ\"ט שאמר בשם אדמו\"ר הזקן נ\"ע בענין איש מזריע<sup data-n=\"1503\">2</sup> תחלה<sup data-n=\"1504\">1</sup> יולדת נקבה אשה מזרעת תחלה יולדת זכר, ופי' המת\"כ<sup data-n=\"1505\">3</sup> הטעם להיות שכאשר האיש מזריע תחלה אזי בא אח\"כ זרע הנקבה וגובר עליו לכן יולדת נקבה וכן להיפוך שכאשר בא זרע האיש אח\"כ גובר ויולדת זכר, ואמר אדמו\"ר נ\"ע שאין טעם זה עולה ע\"פ ההלכה שנפסקה דתתאה גבר<sup data-n=\"1506\">4</sup> וכאן זרע הבא אח\"כ הוא עליון ואיך הוא גובר. לכן אמר שאמיתת הטעם הוא כך להיות שהאיש עצמותו הוא בחי' דכר והתוס' שבו הוא בחי' נוק' והאשה עצמותה היא בחי' נוק' והתוס' שבה הוא בחי' דכר, וכלל הענין שכל הזריעה אינו מבחי' העצם אלא בחי' תוס', ולכן כאשר האיש מזריע תחלה שאז הזרע שלו הוא תחתון והזרע שלו הוא מבחי' התוס' שבו שהוא בחי' נוק' ותתאה גבר ולכן יולדת נקבה, משא\"כ כאשר האשה מזרעת תחלה שאז הזרע שלה הוא תחתון והזרע שלה הוא מבחי' התוס' שבה שהוא בחי' דכר ותתאה גבר לכן יולדת זכר עכ\"ד.\n<b>ואפשר</b> להבין דברים אלו ע\"פ הידוע בכהאריז\"ל שבחי' המדות דאצי' הנק' ז\"א לא נאצל רק וי\"ו מדות<sup data-n=\"1507\">5</sup> בסוד שרש והמוחי' באים בו בסוד תוס', וידוע שג\"ר שבתחתון העלול שהוא בחי' המקבל שבו מהעילה<sup data-n=\"1508\">7</sup> שהוא בחי' ביטול העלול בעילתו, משא\"כ חג\"ת שבו הוא עצם המהות שלו ומה שנעשה משפיע למטה הוא בחי' נה\"י<sup data-n=\"1509\">6</sup>, ונמצא שעצמות הז\"א שהוא מה שנאצל בסוד שרש הוא ע\"י<sup data-n=\"1510\">8</sup> בחי' דכר והתוס' שבו הוא המוחי' הוא בחי' נוק' מקבל מבחי' אימא, אך בבחי' משפיע למטה",[["1503","2","<b>איש מזריע תחלה</b>: ברכות ס, א. נדה לא, א. ראה ויק\"ר ספי\"ד."],["1504","1","<b>שמעתי וכו' איש מזריע תחילה</b>: דרוש ר' הלל.\nלהבא לקמן ראה גם לקו\"ת תזריע יט, ג ובהנסמן במ\"מ לשם. מאמרי אדה\"א דרושי חתונה ח\"א ע' שיב. ד\"ה אשה כי תזריע תשכ\"ה (קונט' ב' ניסן תשמ\"ט — סה\"מ מלוקט ח\"ג ע' צא ואילך). לקו\"ש תזריע כרך יב ע' 70 ואילך. כרך יז ע' 155 הערה 59. וראה גם סידור דרושים לחתונה קלד, ב. מאמרי אדה\"א דרושי חתונה ח\"א ע' רכא ואילך ובשולי היריעה שם. וש\"נ. ע' שיא ואילך.\nמאמר זה באריכות ובשינויים וכו' ובתוס' התחלה ד\"ה האזינו יודפס בעז\"ה בפלח הרמון במקומו בפ' האזינו.\nראה עוד ע\"ד המאמר לקמן ברשימת הכת\"י כאן."],["1505","3","<b>ופי' המת\"כ</b>: ראה שם בויק\"ר ד\"ה שמזיע ראשון. וראה גם רמב\"ן לס\"י פ\"ג, מ\"ו. פי' הטור־ מושב זקנים ר\"פ תזריע. מדרש תלפיות ענף אשה מזריע תחלה. מאמרי אדה\"א דרושי חתונה ח\"א ע' שיב. בלקו\"ת כאן: והפלסופים — ובהערות וציונים לשם יט, א: ראה ברבנו בחיי. מהר\"ש ויטאל (בהג' דרך אמת להקדמת ת\"ז — ג, ב [בת\"ז עם כסא מלך ירושלים ט, ב]). מק\"מ [כנצ\"ל: רמ\"ז] ר\"פ תזריע [בדפי הספר לח, ב]."],["1506","4","<b>דתתאה גבר</b>: ראה פסחים עו, א. רמב\"ם הל' מאכלות אסורות פ\"ט, הי\"ז. טושו\"ע יו\"ד ס\"צ, ס\"ד. סק\"ה, ס\"ג. וראה מאמרי אדה\"א דרושי חתונה ח\"א ע' שיב."],["1507","5","<b>ז\"א. . וי\"ו מדות</b>: ראה ע\"ח שער המוחין ש\"כ, פ\"א."],["1508","7","<b>העלול. . מהעילה</b>: בלקו\"ת ברכה צה, ב: בספרים. ראה גם רמב\"ם הל' יסוה\"ת פ\"ב, ה\"ו."],["1509","6","<b>שג\"ר. . חג\"ת. . נה\"י</b>: ראה פרדס שער ב' פ\"ז. אוה\"ת שמות ע' לג."],["1510","8","<b>ע\"י</b>: א: ליתא."]]],[4801940161,"דא<sup data-n=\"1511\">10</sup> הוא בחי' נה\"י<sup data-n=\"1512\">9</sup>, אך בבחי' המל' דאצי' מבואר שם שלא נאצל רק הכתר שבה בסוד שרש והט\"ס באים בבחי' תוס'<sup data-n=\"1513\">11</sup> וידוע שהכתר שבה הוא דבוק בחזה תמיד כמ\"ש לעולם ה' דברך נצב בשמים<sup data-n=\"1514\">12</sup> וא\"כ הוא מקבל תמיד מז\"א וא\"כ עצמי' המל' דהיינו מה שנאצל בה בסוד שרש הוא בחי' נוק' אבל התוס' שלה הם הט\"ס המשפיעי' בבי\"ע הם בחי' דכר וכידוע בענין ואמונה כ\"ז וקיים<sup data-n=\"1515\">13</sup> כו' וד\"ל.",[["1511","10","<b>דא</b>: כ\"ה בהכת\"י."],["1512","9","<b>אך. . נה\"י</b>: שם: ליתא."],["1513","11","<b>המל'. . בסוד שרש והט\"ס. . תוס'</b>: ראה ע\"ח (שער מיעוט הירח) של\"ו, פ\"א. פ\"ב. לקו\"ת צו יא, ב. ביאוה\"ז להצ\"צ כרך א ע' תצו ואילך. סה\"מ תרל\"ח ע' ח. מאמרי אדה\"ז על פרשיות התורה ח\"ב ע' תתפו."],["1514","12","<b>לעולם ה' דברך נצב בשמים</b>: תהלים קיט, פט. ראה ע\"ח שער מוחין דצלם שכ\"ג, ספ\"ה. שער הירח של\"ה, פ\"א. פע\"ח שער התפלה ש\"א, פ\"ז."],["1515","13","<b>ואמונה כ\"ז </b>[בד: ליתא]<b> וקיים</b>: ברכת אמת ואמונה בתפלת ערבית. ראה מאמרי אדה\"א בראשית ע' קעג. וש\"נ. תו\"ח בשלח ח\"א קפט, ג. וש\"נ."]]],[4801940097,"<b>ענין</b> זכר בא לעולם<sup data-n=\"1516\">1</sup> שלום בא לעולם<sup data-n=\"1517\">2</sup> תיכף קודם המילה ומה יתחדש אחר המילה, יובן ע\"ד ששמענו מאדמו\"ר שליט\"א<sup data-n=\"1518\">3</sup> בביאור דהחלצו<sup data-n=\"1519\">4</sup> כו' בענין שרש השלום שנמשך מבחי' ד\"ע ושרשו בבחי' קרומא דאוירא שלמע' מבחי' חכ\"ס שנק' משכיל כי אנו רואים שלא כל העתים שוות להאיר השכל מכח המשכיל ותלוי בכח עליון יותר מכח המשכיל שהוא בחי' קרומא הנ\"ל דחפיא על מוחא. והנה ידוע בע\"ח דבהאי קרומא אחזי רדל\"א נהורי'<sup data-n=\"1520\">5</sup> כו'. ויובן ע\"ד המבואר בתו' הנ\"ל ברשימ' שלי<sup data-n=\"1521\">6</sup> שהרמז אינו דומה לבחי' האותיו' שמלבישים על השכל אבל הרמז להיותו רק מעבר לזאת יאיר ע\"י עצם השכל כמ\"ש אצל המשפיע ממש. וכך יובן למעלה דדי לחכימא חכ\"ע דאצי' ברמיזה<sup data-n=\"1522\">7</sup> היא הארת האי קרומא שהוא העיקר לפעול הארת אוא\"ס בחכ' כנ\"ל אך ע\"י יאיר אור העצמות דקמי' כחשיכא כאורה<sup data-n=\"1523\">8</sup> ולא אתרמיז בשום רמיזא כלל ועי\"ז יפעול הביטול בחכ' להתחבר בבינה שזהו עיקר התיקון ועשיית השלום שהוא ע\"י דעת העליון המייחד חו\"ב<sup data-n=\"1524\">9</sup> כו' וד\"ל.",[["1516","1","<b>ענין זכר בא לעולם</b>: דרוש מר\"ה (רק חלק).\nראה עוד ע\"ד המאמר לקמן ברשימת הכת\"י."],["1517","2","<b>זכר. . שלום בא לעולם</b>: ראה נדה לא, ב."],["1518","3","<b>מאדמו\"ר שליט\"א</b>: כ\"ק אדמו\"ר הצ\"צ."],["1519","4","<b>בביאור דהחלצו</b>: ד\"ה להבין שרשי הדברים הנ\"ל [פה ליבאויץ, להבין ביאור שני המאמרים דוהשיבו במשקל ומאמר החלצו כו' נא' ליל ה' פ' במדבר שנת הנ\"ל — תקצ\"ט — יודפס בע\"ה בפלח הרמון במדבר]. ראה לקו\"ת מטות פז, ג."],["1520","5","<b>דבהאי קרומא אחזי רדל\"א נהורי'</b>: ראה ע\"ח שער א\"א שי\"ג, פ\"ד ופ\"ו."],["1521","6","<b>בתו' הנ\"ל ברשימ' שלי</b>: ד\"ה להבין הענין מה שקוראים פ' דגלים לפני מ\"ת — יום ג' פ' במדבר תקצ\"ט [יודפס בע\"ה בפלח הרמון במדבר]."],["1522","7","<b>דדי לחכימא. . ברמיזה</b>: ראה רשב\"ם בראשית כג, טז. מדרש משלי כב, טו. זהר בראשית כו, ב. הנסמן במאמרי אדה\"ז על פרשיות התורה ח\"ב לע' תשנב. מאמרי אדה\"א שמות ח\"א ע' סט."],["1523","8","<b>כחשיכא כאורה</b>: תהלים קלט, יב. ראה לקו\"ת צו יב, א. סידור סדר הגדה רצז, רע\"ד. עט\"ר דרוש לעשי\"ת ע' נא. סה\"מ תרכ\"ז ע' תצד."],["1524","9","<b>דעת העליון המייחד חו\"ב</b>: ראה גם לקו\"ת להאריז\"ל שמות ג, ד. לקו\"ת מטות פו, ד. פז, ג. נשא כב, ב. כו, א. תו\"א משפטים עה, א. ב."]]],[4801940162,"אך ידוע בכהאריז\"ל שכמו דמל' דא\"ק עתיק לאצילות<sup data-n=\"1525\">10</sup> כן מל' דא\"ס בחי' עתיק לא\"ק<sup data-n=\"1526\">11</sup> והחכ' שבו נק' ג\"כ בחי' משכיל אך הוא בחי' משכיל לאיתן האזרחי<sup data-n=\"1527\">12</sup> פי' אותיות איתן משמשות לעתיד<sup data-n=\"1528\">13</sup> והאזרחי הכוונה מה שעתיד להזריח<sup data-n=\"1529\">14</sup> והוא ענין אור הראשון שגנזו בתורה<sup data-n=\"1530\">15</sup> באותיות שבה דווקא שזהו אש שחורה ע\"ג אש לבנה<sup data-n=\"1531\">16</sup>, ע' בתורה דועשית חג שבועות<sup data-n=\"1532\">17</sup> המיוסדת על מאמר ויקרא א' זעירא, וזהו מה שנז\"ל דהאי רדל\"א אחזי נהורי בהאי קרומא שהוא ענין אור הגנוז בתוך החושך שעתיד לבוא לידי גילוי וכנ\"ל במשל הרמז שאינו אלא מעבר בלבד וע\"י יתגלה אח\"כ עצם השכל. אך ידוע דאוא\"ס בעא\"ע ויש חושך למעלה מאור זה וזהו בחי' חכ\"ס דא\"ק שהוא בחי' חושך לאור זה וזהו נק' בחי' משכיל לאיתן כו'. והארת האור הנ\"ל מתוך החושך הנ\"ל הנק' משכיל לאיתן תלוי בכח יותר עליון כנ\"ל ובה אחזי נהורי' מבחי' מל' דא\"ס עצמו שהוא בחי' עתיק לא\"ק כו'. ותן לחכם ויחכם עוד<sup data-n=\"1533\">18</sup> בבחי' עצמי' אוא\"ס שלפני הצמצום מה שעלה ברצה\"פ להיטיב<sup data-n=\"1534\">19</sup> שהוא בחי' חפץ חסד דהראשון נק' איתן האזרחי ויש בחי' משכיל לאיתן זה והארתו מבחי' משכיל הנ\"ל תלוי בכח יותר עליון דבי' אחזי נהורי' מבחי' מלך יחיד<sup data-n=\"1535\">20</sup> כו' וד\"ל. והנה בחי' הזכר שרשו בבחי' הדעת בחי'<sup data-n=\"1536\">22</sup> זכרון<sup data-n=\"1537\">21</sup> (ויש לו דעת שלם הכולל חו\"ג משא\"כ הנוק'<sup data-n=\"1538\">23</sup> כו') וכאשר בא לעולם בבחי' הלידה אז שלום בא לעולם הנאצל לפעול היחוד בכל ד' אותיות דשם הוי' והוא באצי' והארה בעלמא מאיר בבי\"ע.",[["1525","10","<b>דמל' דא\"ק עתיק לאצילות</b>: ראה ע\"ח שער סדר אצי' ש\"ג, פ\"ב. לקו\"ת מסעי צה, ב. לעיל ע' פד ובהערה 24."],["1526","11","<b>מל' דא\"ס בחי' עתיק לא\"ק</b>: ראה גם מאמרי אדה\"א קונטרסים ע' תכה. וש\"נ."],["1527","12","<b>משכיל לאיתן האזרחי</b>: תהלים פט, א."],["1528","13","<b>אותיות איתן משמשות לעתיד</b>: ראה גם קו\"א לתניא קסא, א. לקו\"ת ר\"פ ראה."],["1529","14","<b>והאזרחי. . שעתיד להזריח</b>: ראה גם לקו\"ת ראה יח, סע\"א. מאמרי אדה\"ז הקצרים ע' עג. וש\"נ. ע' עד."],["1530","15","<b>אור הראשון שגנזו בתורה</b>: ראה לקו\"ת במדבר יח, ד ובהנסמן במ\"מ לשם. מאמרי אדה\"ז על פרשיות התורה ח\"ב ע' תשמו ובהנסמן במ\"מ לשם. תו\"ח מקץ רכח, ג. ויחי רמא, ד. תצוה ח\"ב שמב, א. מאמרי אדה\"א בראשית ע' תה. וש\"נ. אוה\"ת ואתחנן כרך ו ע' ב'רטו. סה\"מ תרכ\"ז ע' תסד. וש\"נ. לקו\"ש בראשית כרך י ע' 10. לעיל ע' עח. לקמן מאמר ד\"ה כי תבואו וגו' ושבתה תר\"ט על יד הערה 81."],["1531","16","<b>אש שחורה ע\"ג אש לבנה</b>: ראה רש\"י שה\"ש ה, טז ד\"ה שחורות. הנסמן במאמרי אדה\"א ויקרא ח\"ב ע' תקעח."],["1532","17","<b>דועשית חג שבועות</b>: נזכר גם ברשימת הרח\"א ביחובסקי מדרושי ר\"ה במפתח שבראש בוך 1228 בפ' ראה ואינו תח\"י."],["1533","18","<b>ותן לחכם ויחכם עוד</b>: משלי ט, ט. ראה גם מאמרי אדה\"ז תקס\"ב ח\"ב ע' שלט."],["1534","19","<b>מה שעלה ברצה\"פ להיטיב</b>: ראה ע\"ח שער עגו\"י ש\"א, ענף ב. לעיל ע' לה הערות 62-3."],["1535","20","<b>מלך יחיד</b>: נוסח ברכת ישתבח."],["1536","22","<b>הדעת בחי' זכרון</b>: ראה גם מאמרי אדה\"א קונטרסים ע' רמד."],["1537","21","<b>הזכר. . זכרון</b>: ראה מאו\"א מערכת זכור סי\"ב."],["1538","23","<b>הזכר. . דעת שלם. . הנוק'</b>: ראה גם לקו\"ת להאריז\"ל שמות ג, ד."]]],[4801940098,"<b>למנצח</b> על<sup data-n=\"1539\">2</sup> השמינית<sup data-n=\"1540\">1</sup> על המילה שניתנה בשמיני<sup data-n=\"1541\">3</sup> ואיתא בתיקונים תמן מל תמן נצח<sup data-n=\"1542\">4</sup>. הנה ארז\"ל כל המתיישב ביינו<sup data-n=\"1543\">5</sup> מדעת קונו יש בו. הנה בחי' יין שרשו חסדים דאימא<sup data-n=\"1544\">6</sup> או גבורות דאימא<sup data-n=\"1545\">7</sup> ומלובש בו חסדים דאבא<sup data-n=\"1546\">8</sup> או גבורה דעתיק<sup data-n=\"1547\">9</sup> כו' וע\"ד העבודה האהבה עזה כרשפי אש שנולדה מצד ההתבוננות איך דכולא קמי' כלא חשיב<sup data-n=\"1548\">10</sup> שיש בזה ג' מדריגות האחת כאשר היא בבחי' רשפי אש בלבד להכלל במקורו מקה\"ח<sup data-n=\"1549\">11</sup> ולא לחפוץ בהתפשטות חיים הן רוחני' הן גשמי' כו' שזהו בחי' גבורות דאימא כו' והב' כאשר נעשה בחי' התיישבות באה' זאת מצד שמאיר בו בחי' חיי החיים<sup data-n=\"1550\">12</sup> עצמות אוא\"ס בבחי' התיישבות בכלי המוח ונק' אה' בתענוגים ב' מיני עונג דרו\"ש וזהו בחי' חסדים דאבא המתלבשים בגבו' דאימא להמתיק כנ\"ל והג' הוא בחי' העלי' בעונג הנ\"ל בעילוי אחר עילוי בלי שיעור עד שלא יפול בו שביעה כלל שזהו ענין לאסתכלא ביקרא דמלכא<sup data-n=\"1551\">13</sup> יקר דווקא פנימי' העונג. וזהו בכ\"י יהי' בעיניך כחדשים<sup data-n=\"1552\">14</sup> מי איכא זקנה קמי' קוב\"ה<sup data-n=\"1553\">15</sup> קמי' דווקא, וזהו בחי' גבור' דעתיק שהוא בחי' גילוי האה' מבחי' יחידה כרשפי אש למע' מן ההשגה שבאה בבחי' התיישבות בכלי ואעפ\"כ אין לה שיעור כו'. והנה זהו בחי' השבת בג' סעודות, סעודתא דחקל תפוחין קדישין<sup data-n=\"1554\">16</sup> הוא עליות",[["1539","2","<b>למצח על השמינית</b>: תהלים יב, א."],["1540","1","<b>למנצח על השמינית</b>: לע\"ע לא נתברר אם מאמר זה הוא הנחה מדרוש כ\"ק אדמו\"ר הצ\"צ או שזה דרוש עצמו.\nלמאמר זה ראה לקו\"ת פ' תזריע כ, סע\"ג ואילך. אוה\"ת תזריע כרך ב' ע' תקב ואילך. ספר המצות להצ\"צ ע' 18 ואילך. סידור שער המילה קלט, ג ואילך.\nראה עוד ע\"ד המאמר לקמן ברשימת הכת\"י."],["1541","3","<b>על המילה שניתנה בשמיני</b>: מנחות מג, ב."],["1542","4","<b>בתיקונים תמן מל תמן נצח</b>: וכ\"ה בסידור שער המילה קמ, ד. אוה\"ת תזריע כרך ב ע' תקיא. ובלקו\"ת כאן כא, ב: בת\"ז. ראה הנסמן במ\"מ לקו\"ת שם. בסהמ\"צ להצ\"צ ע' 18 וע' 20: אי' בזהר תמן נצח תמן מל."],["1543","5","<b>כל המתיישב ביינו</b>: ראה ערובין סה, א ושם: המתפתה ביינו יש בו מדעת קונו. . המתיישב. . דעת ע' זקנים. לקמן פיסקא והנה עם."],["1544","6","<b>יין שרשו חסדים דאימא</b>: ראה גם ביאוה\"ז שמיני סג, ג."],["1545","7","<b>יין שרשו. . גבורות דאימא</b>: ראה סידור שער הסוכות רס, ד. ביאוה\"ז שמיני סד, א. מאמרי אדה\"א בראשית ע' רפז. וש\"נ. תו\"ח וישלח קצג, ג ובהערה 14. תצוה ח\"ב שמז, ג."],["1546","8","<b>ומלובש בו חסדים דאבא</b>: ראה גם ביאוה\"ז נח ח, סע\"ב."],["1547","9","<b>ומלובש בו. . גבורה דעתיק</b>: ראה רמ\"ז לזהר בלק קפט, א. ביאוה\"ז שמיני סד, ג."],["1548","10","<b>דכולא קמי' כלא חשיב</b>: ראה זהר בהקדמה יא, ב. ראשית חכמה שער היראה פ\"א (ז, רע\"א). מאמרי אדה\"ז תקס\"ו ע' שמא. מאמרי אדה\"א דברים ח\"ב ע' תרנג."],["1549","11","<b>מקה\"ח</b>: מקור החיים."],["1550","12","<b>חיי החיים</b>: יומא עא, א."],["1551","13","<b>לאסתכלא ביקרא דמלכא</b>: ראה זהר מקץ קצט, א. בראשית לח, א-ב. פקודי רמז, ב. תרומה קלד, א."],["1552","14","<b>בכ\"י יהי' בעיניך כחדשים</b>: ראה לקח טוב ואתחנן ו, ו. מאמרי אדה\"א דברים ח\"א ע' רסו ואילך. וש\"נ. הנחות תקע\"ז ע' שו ואילך וע' שיט. לקמן מאמר ד\"ה והתהלכתי תר\"ב על יד הערה 32. ד\"ה והתהלכתי תרט\"ו על יד הערה 23. ד\"ה והתהלכתי תרכ\"ב על יד הערה 37 ואילך. ד\"ה בשברי לכם הא' בסופו. ד\"ה בשברי לכם תקצ\"ט בסופו."],["1553","15","<b>מי איכא זקנה קמי' קוב\"ה</b>: ראה יבמות טז, ב. מאמרי אדה\"א קונטרסים ע' צב ד\"ה והנה. שעה\"י קפו, ג. שע\"ת כט, ב. תו\"ח תולדות קנג, א הערה 9."],["1554","16","<b>סעודתא דחקל תפוחין קדישין</b>: ראה זהר יתרו פח, ב. המשך תער\"ב ח\"ב ע' א'צז ואילך. אוה\"ת בהר כרך ד ע' א'קנב. לקו\"ש בשלח כרך לא ע' 247."]]],[4801940163,"המל' מקור נש\"י<sup data-n=\"1555\">18</sup> עד בחי' מוחין דאימא<sup data-n=\"1556\">17</sup> בבחי' החסדים שבהם ומצד זה נק' בשם קדישין כו' (כי כל קדושה במוחין<sup data-n=\"1557\">19</sup> ) וזהו ויכל אלקים<sup data-n=\"1558\">20</sup> כו' בחי' כליון<sup data-n=\"1559\">21</sup> כו', והב' סעודת שחרית שנמשך בחי' תענוג הפשוט בבחי' זו\"נ בחי' אהבה אחרי אשר כבר עלו בחי' זו\"נ (מקורי נש\"י<sup data-n=\"1560\">23</sup> כמאמר בנים אתם להוי' אלקיכם<sup data-n=\"1561\">24</sup> כו') לאו\"א בבחי' הכתרים<sup data-n=\"1562\">22</sup> שבהם כידוע בכהאריז\"ל וזהו<sup data-n=\"1563\">25</sup> מדריגות אה' בתענוגים הנ\"ל), והג' הוא בחי' סעודה שלישית עליות הז\"א אל הדיקנא<sup data-n=\"1564\">26</sup> בחי' המזלות הנמשכים ממותרי חכ\"ס<sup data-n=\"1565\">27</sup> הנק' נובלות וכל נובלות הוא מהפנימי' דווקא שהוא בחי' גבורה דע\"י המלובש בחכ\"ס<sup data-n=\"1566\">28</sup> וגם המל' עולה עד כתר אבא בחי' אין דחכ' שלמעלה מהתיישבות בהשגה, וגילוי זה הוא בבחי' חלק הנשמה שבגוף שנמשך מבחי' מל' משא\"כ עצם הנשמה ששרשה מבחי' ז\"א מקבל מבחי' הדיקנא כו' וד\"ל.\n<b>והנה</b> על בחי' ב' אמר וישבות ביום<sup data-n=\"1567\">29</sup> ולא כתב בחי' אלקים מצד שעיקר עלי' הוא בבחי' ז\"א ומל' טפולה<sup data-n=\"1568\">30</sup> אלי', ואח\"כ ויברך אלקים<sup data-n=\"1569\">*31</sup> גבו' דע\"י את יום השביעי (זו\"נ ביחד זכר ונקבה בראם אז דווקא ויברך אותם<sup data-n=\"1570\">31</sup> כו' וד\"ל), וכל ג' המשכות הנ\"ל המשכתם לבוא לידי גילוי הוא בקידוש על היין ששרשו בבחי' תבונה אם הבנים<sup data-n=\"1571\">32</sup> או עצמות בינה או בינה דע\"י שמוליד ג' בחי' אה' הנ\"ל כו' וד\"ל. והנה כל הנ\"ל נק' בחי' כד מסתכל ז\"א בפנים מקבל ק\"ן נהורין<sup data-n=\"1572\">33</sup> (עיין ברשימה דביאור הסבי<sup data-n=\"1573\">34</sup> ששמעתי מאדמו\"ר שליט\"א תקצ\"ח) ויש בזה ג' מדריגות משם ב\"ן עליות",[["1555","18","<b>המל' מקור נש\"י</b>: ראה הנסמן בהערה 23. אוה\"ת ויקהל ע' ב'קי. לקמן מאמר ד\"ה אם בחוקותי הג' על יד הערה 128. ד\"ה בשברי לכם הא' אחר הערה 50."],["1556","17","<b>עליות המל'. . מוחין דאימא</b>: ראה גם בענין עליות המל' פע\"ח שער השבת שי\"ח, פי\"ג ופי\"ד."],["1557","19","<b>כל קדושה במוחין</b>: ראה פע\"ח שם פ\"ו. פי\"ג ופי\"ד."],["1558","20","<b>ויכל אלקים</b>: בראשית ב, ב."],["1559","21","<b>ויכל. . כליון</b>: ראה רקאנטי עה\"פ. לקו\"ת תזריע כאן כ, ד. בהר מב, ג. ד. בלק עב, א."],["1560","23","<b>זו\"נ (מקורי נש\"י</b>: ראה ע\"ח שער המלכים שי\"א, רפ\"ו. פע\"ח שער הק\"ש ש\"ח, פ\"ז. פי\"ב. מבו\"ש ש\"ב ח\"ב פ\"ב. לקמן מאמר ד\"ה את שבתותי תרי\"ב ובהערה 72. ד\"ה בשברי לכם הא' פיסקא וביאור הענין."],["1561","24","<b>בנים אתם להוי' אלקיכם</b>: פ' ראה יד, א."],["1562","22","<b>עלו בחי' זו\"נ. . לאו\"א בבחי' הכתרים</b>: ראה פע\"ח שער השבת שי\"ח, פכ\"ב. שער ר\"ה שכ\"ד, פ\"ו."],["1563","25","<b>וזהו</b>: אוצ\"ל: (וזהו."],["1564","26","<b>עליות הז\"א אל הדיקנא</b>: ראה פע\"ח שם פ\"ו. פי\"א. פי\"ג. פכ\"ב ופכ\"ג."],["1565","27","<b>המזלות הנמשכים ממותרי חכ\"ס</b>: ראה גם לקמן ביאור מאמר ד\"ה והניף הכהן אותם על יד הערה 66. מאמרי אדה\"א דברים ח\"א ס\"ע רכו ואילך."],["1566","28","<b>גבורה דע\"י המלובש בחכ\"ס</b>: ראה ע\"ח שער א\"א שי\"ג, פ\"ו-ז."],["1567","29","<b>וישבות ביום</b>: בראשית ב, ב."],["1568","30","<b>טפולה</b>: כנצ\"ל: טפילה."],["1569","*31","<b>ויברך אלקים</b>: בראשית ב, ג."],["1570","31","<b>זכר ונקבה בראם. . ויברך אותם</b>: בראשית ה, ב."],["1571","32","<b>תבונה אם הבנים</b>: ראה ע\"ח שער הזווגים שט\"ו, ספ\"ו. מבו\"ש ש\"ד ח\"ב, פ\"י."],["1572","33","<b>כד מסתכל ז\"א. . ק\"ן נהורין</b>: ראה גם תו\"א ויחי מח, ב. לקו\"ת מסעי צג, סע\"ג. וש\"נ. המשך תער\"ב ח\"ב ע' א'רה. בהערה הבאה."],["1573","34","<b>ברשימה דביאור הסבי</b>: פלח הרמון שה\"ש צח, א. ויש להוסיף ביאור זה לרשימת מאמרי דא\"ח של הצ\"צ (קה\"ת תשנ\"ד) משנה זו (תקצ\"ח)."]]],[4801940222,"המל'<sup data-n=\"1574\">35</sup> כנ\"ל, עליות עונג הפרטי להתכלל במקורו והמשכות עונג הפשוט עד שנעשה התיישבות הוא בחי' שם מ\"ה כו' והמשכות גילוי העונג דיחידה הוא שם ע\"ב וזהו חכלילי עינים<sup data-n=\"1575\">36</sup> תוקף האדמומית דעיינין דזו\"נ מלמטה למעלה עיני תמיד אל הוי'<sup data-n=\"1576\">37</sup> ממשיך הסתכלות מלמעלה למטה עין הוי' (דעתיק ואריך) אל יראיו<sup data-n=\"1577\">38</sup> (בחי' זו\"נ) וכ\"ז הוא מיין דקידוש של שבת כו' וד\"ל. (וע' בתו\"א פ' ויחי במאמר חכלילי עם הביאור ובהגהת אדמו\"ר שליט\"א דף ע\"ט ע\"א בד\"ה<sup data-n=\"1578\">39</sup> וצ\"ע בתניא ובתניא פי\"ט ובפרק מ\"ג ותבין היטיב איך שבמדריגות אה' דשם מ\"ה יש ג\"כ בחי' תענוג רק הוא בהגבלה כו' ואינו גילוי תענוג העיקרי אך גילוי האה' משם ע\"ב היא עלי' (בעילוי אחר עילוי) בלי שיעור שזהו ע\"י רשפי אש דווקא כו'. ולכן נאמר בפמ\"ג כשלהבת העולה מאיליה כו' וד\"ל).\n<b>והנה</b> כל הנ\"ל הוא בחי' המשכות שם מ\"ה לברר ב\"ן<sup data-n=\"1579\">40</sup>, ויובן ע\"פ הידוע בכהאריז\"ל שמבחי' שם מ\"ה החדש דא\"ק<sup data-n=\"1580\">41</sup> נמשך בחי' טנת\"א ונתחבר עם טנת\"א דב\"ן (ובחי' שם ע\"ב הנזכר למעלה הוא ג\"כ לגבי א\"ק הארה מבחי' שם מ\"ה דא\"ק רק שהוא בחי' הטעמים דב\"ן כו') והטעמים ונקודות דשם מ\"ה שנעשו בחי' עתיק ואריך דדכורא הוא בחי' אה' בתענוגים הנ\"ל והתגין ואותיות דשם מ\"ה הוא מדריגות אה\"ר (שאין בזה גילוי תענוג העיקר כנ\"ל) הנ\"ל, אך בבחי' אותיות דמ\"ה אפשר שיש עוד מדריגה אחת השייכות לבחי' מל' אתוון זעירין<sup data-n=\"1581\">42</sup> כו' והוא מדריגה אה' עזה כרשפי אש כו' (ואעפ\"י שזה נק' בירור דשם ב\"ן בתו\"א בביאור דחכלילי היינו משום שזהו בבחי' מל' שנק' בכלל שם ב\"ן אבל עיקר הבירור הוא מבחי' שם מ\"ה שבמל' כי האיש דרכו לכבוש<sup data-n=\"1582\">43</sup> כו' וד\"ל). והנה אעפ\"י שמבואר בע\"ח שמבחי' שם מ\"ה החדש ניתקן כל עולם האצילות<sup data-n=\"1583\">44</sup> שזהו בחי' טנת\"א דמ\"ה שמתפשט בכל פרצופי האצי' היינו רק יש<sup data-n=\"1584\">45</sup> הארת שם מה החדש אבל עצמות שם מ\"ה הוא למעלה מבחי' התהו והתיקון כי הוא מבחי' א\"ק שלמעלה מכל ההשתלשלות דאבי\"ע. והענין הוא דג' מדריגות דשם מ\"ה היינו שם ע\"ב וס\"ג שבו הכולל טעמים ונקודות דאו\"א ושם מ\"ה שבו הכולל בחי' תגין דאו\"א ושם ב\"ן הכולל בחי' אותיות דזו\"נ באים בהעלם בימות החול בשם ב\"ן לברר אותו ונק' אתעדל\"ת ומאתעדל\"ת זאת נמשך אתעדל\"ע<sup data-n=\"1585\">46</sup> התגלות דשם מ\"ה בג' מדריגות דאה' בתענוגים ואה\"ר ואה\"ע (ואה' בתענוגים הוא טעמים ונקודות שבו ואה\"ר תגין ואה\"ע אה' עזה כרשפי אש אותיות וזהו באופן אחר מדלעיל כו').",[["1574","35","<b>ב\"ן. . המל'</b>: ראה ע\"ח שער רפ\"ח ניצוצין שי\"ח, פ\"ג. שעה\"י קמה, א הערה 14."],["1575","36","<b>חכלילי עינים</b>: ויחי מט, יב."],["1576","37","<b>עיני תמיד אל הוי'</b>: תהלים כה, טו."],["1577","38","<b>עין הוי'. . אל יריאיו</b>: תהלים לג, יח."],["1578","39","<b>ע\"ט ע\"א בד\"ה</b>: בהוצאת תקצ\"ז. ולפנינו מז, ג (בד\"ה ובזה יובן)."],["1579","40","<b>מ\"ה לברר ב\"ן</b>: ראה ע\"ח שער טנת\"א ש\"ה, פ\"א. מאמרי אדה\"א דברים ח\"א ע' ה. וש\"נ. ח\"ב ע' תקעג ואילך. ח\"ד ע' א'ריג ואילך."],["1580","41","<b>שם מ\"ה החדש דא\"ק</b>: ראה (ולחלק הבא לקמן) ע\"ח שער התיקון ש\"י, פ\"ב."],["1581","42","<b>מל' אתוון זעירין</b>: ראה רמ\"ז ר\"פ ויקרא. הנסמן במאמרי אדה\"א ויקרא ח\"א ע' יד."],["1582","43","<b>האיש דרכו לכבוש</b>: יבמות סה, ב."],["1583","44","<b>שם מ\"ה. . האצילות</b>: ע\"ח שבהערה 41."],["1584","45","<b>יש</b>: אוצ\"ל: שיש."],["1585","46","<b>ומאתעדל\"ת. . אתעדל\"ע</b>: ראה זהר לך פח, א. תו\"ח שמות ח\"א מא, א ובהערה 189."]]],[4801940275,"אך כ\"ז הוא בחי' אתעדל\"ע המתגלה לפ\"ע אתעדל\"ת (וההפרש בין שם מ\"ה המתלבש בשם ב\"ן לברר בימות החול שזהו אתעדל\"ע המלובש בהעלם לעורר באתעדל\"ת ובין שם מ\"ה המתגלה בשבת הוא ששם מ\"ה המברר הוא בחי' ו\"ד ביוד דחכ' בד\"כ ואעפ\"כ יש בו כל המדריגות דטנת\"א כנ\"ל ושם מ\"ה המתגלה בשבת הוא בחי' מ\"ה העצמי בחי' י' דחכ' שנק' קדש מלה בגרמי'<sup data-n=\"1586\">47</sup> וישראל עבמ\"ח<sup data-n=\"1587\">48</sup> הוא שם מ\"ה המברר מדות דחכ' ובשבת מתעלין במ\"ה העצמי ונק' אנשי קדש<sup data-n=\"1588\">49</sup> שלמעלה מקדוש בוי\"ו כו' וד\"ל). אבל יש בחי' אתעדל\"ע שאינו בא מצד אתעדל\"ת כלל כי אין אתעדל\"ת מגיע לשם כלל והוא עצמי' דשם מ\"ה החדש הנ\"ל שנחשב מבחי' א\"ק כנ\"ל, והוא הנמשך ע\"י המילה שאינו נחשב לאתעדל\"ת כלל להיות פעולתו אינו אלא רק להעביר הערלה בלבד (וכמו סו\"מ<sup data-n=\"1589\">50</sup> שית' כו') שהו\"ע העברת הרע אזי ממילא שורה כו' וזהו\"ע מילה באותו מקום<sup data-n=\"1590\">51</sup> שהוא בבחי' יסוד דא\"ק כו' וד\"ל.\n<b>והנה</b> עם הקדמה זאת יובן ענין כל המתיישב ביינו מדעת קונו יש בו, וביאור הדברים הנה כתי' והחכ' תחי' בעלי'<sup data-n=\"1591\">52</sup>, ויוכל להתפרש באופן זה ע\"ד ששמעתי בשם אדמו\"ר נ\"ע<sup data-n=\"1592\">53</sup> שא' בשם אדמו\"ר הזקן נ\"ע שיש בחי' מוחא שלטא על לבא<sup data-n=\"1593\">54</sup> שהוא ענין חיצוני' המדות המתפעלים מצד השכל ובבחי' זאת המוח הוא בחי' משפיע והלב הוא בחי' מקבל (ולמעלה היינו בחי' ז\"א שמקבל מאו\"א בחי' מוחין), ויש בחי' לבא שלטא על מוחא<sup data-n=\"1594\">55</sup> שהוא בחי' נקודת הלב שלמע' מן השכל כו' (ולמעלה היינו בחי' שרש המדות שהוא למעלה מאו\"א ושרשם בז\"ת דע\"י וא\"א וכמאמר הידוע דז\"א בעתיקא אחיד ותלי'<sup data-n=\"1595\">56</sup> ) מדות דיחידה, ובבחי' זאת הלב משפיע אל המוח והמוח מקבל נמצא שהמוח מקבל מבחי' פנימי' הלב ומשפיע בבחי' חיצוני' הלב, אבל יש עוד בחי' דמוחא שלטא על לבא אפי' על פנימי' הלב המשפיע בו כו' עכ\"ד. ושרש הדברים היינו שאנו רואים שיש בכח החכ' למשול על רוחו העצמי,",[["1586","47","<b>דחכ' שנק' קדש מלה בגרמי'</b>: ראה זהר אמור צד, ב. לקו\"ת מסעי צג, א. מאמרי אדה\"א דברים ח\"ג ע' תתקב."],["1587","48","<b>וישראל עבמ\"ח</b>: ראה ב\"ר פ\"א, ד. שע\"ת קטו, ב. תו\"ח שמות ח\"א לב, ב ובהערה 248."],["1588","49","<b>אנשי קדש</b>: משפטים כב, ל [ושם: ואנשי]. ראה לקו\"ת בהעלותך ל, סע\"ג ואילך. יו\"כ סט, ב. לקמן מאמר ד\"ה שבת שבתון על יד הערה 58."],["1589","50","<b>סו\"מ</b>: סור מרע."],["1590","51","<b>מילה באותו מקום</b>: ראה שבת קח, א. סידור שער המילה כאן קלט, ד."],["1591","52","<b>והחכ' תחי' בעלי'</b>: קהלת ז, יב [ושם: החכמה — ראה גם לקמן ביאור מאמר ד\"ה שבת שבתון על יד הערה 21. מאמרי אדה\"א דברים ח\"א ע' ש. וש\"נ. סה\"מ תרל\"ח ע' נג הערה 292]."],["1592","53","<b>אדמו\"ר נ\"ע</b>: כ\"ק אדה\"א."],["1593","54","<b>מוחא שלטא על לבא</b>: ראה תניא פי\"ב. מאמרי אדה\"א דברים ח\"ב ע' תצ. וש\"נ. ראה גם מאמרי אדה\"ז על ענינים ע' תיט ואילך. עט\"ר ע' 38 ואילך."],["1594","55","<b>לבא שלטא על מוחא</b>: ראה גם מאמרי אדה\"ז על פרשיות התורה ח\"ב ע' תתמא. אמ\"ב שער הק\"ש מח, ב. עט\"ר שם."],["1595","56","<b>דז\"א בעתיקא אחיד ותלי'</b>: ראה זהר אד\"ז האזינו רצב, א. סה\"מ תרנ\"ו ע' תכז ובהערה לשם. תרל\"ב ח\"א ס\"ע יג ואילך. וש\"נ. תו\"ח בא ח\"א קל, ב ובהערה 796. ד\"ה זה היום תשמ\"א [קונט' ר\"ה תשמ\"ח — נדפס בסה\"מ מלוקט ח\"ב ס\"ע קח ואילך אות יא]."]]]]});
